--
-- Name: bootstrap_admin_tenant_link(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bootstrap_admin_tenant_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    default_tenant_id UUID;
BEGIN
    -- Only run if user is ADMIN and ACTIVE
    IF NEW.role = 'admin' AND NEW.ativo = true THEN
        
        -- Check if link already exists
        IF NOT EXISTS (
            SELECT 1 
            FROM empresa_profissionais ep 
            JOIN empresas e ON e.id = ep.empresa_id 
            WHERE ep.profissional_id = NEW.id 
              AND e.empresa_tipo = 'tenant'
              AND ep.ativo = true
        ) THEN
            -- Find default tenant
            SELECT id INTO default_tenant_id
            FROM empresas
            WHERE empresa_tipo = 'tenant' AND ativo = true
            LIMIT 1;

            IF default_tenant_id IS NOT NULL THEN
                -- Create the link safely
                VALUES (gen_random_uuid(), default_tenant_id, NEW.id, 'Admin Auto-Linked', true);
                
                RAISE NOTICE 'BOOTSTRAP: Auto-linked admin % to tenant %', NEW.email, default_tenant_id;
            ELSE
                RAISE WARNING 'BOOTSTRAP FAILED: No tenant found for admin %', NEW.email;
            END IF;
        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.bootstrap_admin_tenant_link() OWNER TO postgres;

--
-- Name: bootstrap_admin_tenant_link_after(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bootstrap_admin_tenant_link_after() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_tenant_id UUID;
    link_exists BOOLEAN;
BEGIN
    IF NEW.role NOT IN ('admin', 'super_admin') THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM empresa_profissionais ep
        JOIN empresas e ON e.id = ep.empresa_id
        WHERE ep.profissional_id = NEW.id
          AND ep.ativo = true
          AND e.empresa_tipo = 'tenant'
          AND e.ativo = true
    ) INTO link_exists;

    IF link_exists THEN
        RETURN NEW;
    END IF;

    SELECT id INTO target_tenant_id
    FROM empresas
    WHERE empresa_tipo = 'tenant'
      AND ativo = true
    ORDER BY created_at ASC
    LIMIT 1;

    IF target_tenant_id IS NOT NULL THEN
            profissional_id,
            empresa_id,
            funcao,
            ativo,
            created_at
        ) VALUES (
            NEW.id,
            target_tenant_id,
            'Administração (Bootstrap)',
            true,
            NOW()
        )
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.bootstrap_admin_tenant_link_after() OWNER TO postgres;

--
-- Name: bulk_create_deadline_notifications(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bulk_create_deadline_notifications(payloads jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    inserted_count INT;
BEGIN
    -- Bulk insert from JSONB array
        profissional_id,
        tipo,
        mensagem,
        metadata,
        created_at
    )
    SELECT
        (p->>'profissional_id')::UUID,
        'deadline_reminder',
        p->>'message',
        p->'metadata',
        NOW()
    FROM jsonb_to_recordset(payloads) AS p(
        profissional_id TEXT,
        message TEXT,
        metadata JSONB
    );

    GET DIAGNOSTICS inserted_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'inserted', inserted_count
    );
END;
$$;


ALTER FUNCTION public.bulk_create_deadline_notifications(payloads jsonb) OWNER TO postgres;

