-- Name: can_change_deadline(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_change_deadline(p_os_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    os_record RECORD;
BEGIN
    -- Buscar dados da OS
    SELECT status, created_by, deleted_at
    INTO os_record
    FROM tarefas 
    WHERE id = p_os_id;
    
    -- OS não encontrada ou excluída
    IF os_record IS NULL OR os_record.deleted_at IS NOT NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Admin sempre pode (se ativa)
    IF is_admin_safe() THEN
        RETURN TRUE;
    END IF;
    
    -- Criador pode se pendente
    IF os_record.created_by = p_user_id 
       AND os_record.status = 'pendente' THEN
        RETURN TRUE;
    END IF;
    
    RETURN FALSE;
END;
$$;


