--
-- Name: count_unassigned_tasks(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.count_unassigned_tasks() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT COUNT(*)::INTEGER
  FROM tarefas t
  WHERE t.status NOT IN ('concluida', 'cancelada')
  AND NOT EXISTS (
    SELECT 1
    FROM tarefas_micro tm
    WHERE tm.tarefa_id = t.id
    AND tm.profissional_id IS NOT NULL
  );
$$;


