--
-- Name: identificar_gargalo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.identificar_gargalo(p_tarefa_id uuid) RETURNS TABLE(micro_task_id uuid, funcao text, profissional_nome text, tempo_atraso_minutos integer)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        mt.id AS micro_task_id,
        mt.funcao,
        p.nome AS profissional_nome,
        EXTRACT(EPOCH FROM (NOW() - mt.deadline_at)) / 60 AS tempo_atraso_minutos
    FROM tarefas_micro mt
    INNER JOIN profissionais p ON mt.profissional_id = p.id
    WHERE mt.tarefa_id = p_tarefa_id
      AND mt.deadline_at IS NOT NULL
      AND mt.status != 'concluida'
      AND NOW() > mt.deadline_at
    ORDER BY mt.created_at ASC
    LIMIT 1;
END;
$$;


