--
-- Name: is_os_participant(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_os_participant(p_os_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM tarefas t
        WHERE t.id = p_os_id
        AND (
            -- Admin vê tudo (usando função safe)
            is_admin_safe()
            OR
            -- Criador da OS
            t.created_by = auth.uid()
            OR
            -- Atribuído direto (OS simples)
            t.assigned_to = auth.uid()
            OR
            -- Atribuído via micro-task (OS complexa)
            EXISTS (
                SELECT 1 FROM tarefas_micro tm
                WHERE tm.tarefa_id = t.id
                AND tm.profissional_id = auth.uid()
            )
        )
    );
END;
$$;


