--
-- Name: notify_task_assignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_task_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Only on INSERT with assigned_to
  IF (TG_OP = 'INSERT' AND NEW.assigned_to IS NOT NULL) THEN
    IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN
      VALUES (
        NEW.assigned_to, 
        'task_assigned', 
        'Nova Tarefa', 
        'Uma nova tarefa foi atribuída a você: ' || NEW.titulo, 
        'task', 
        NEW.id
      );
    END IF;
  -- Only on UPDATE when assignee changes
  ELSIF (TG_OP = 'UPDATE' AND NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL) THEN
    IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN
      VALUES (
        NEW.assigned_to, 
        'task_assigned', 
        'Nova Atribuição', 
        'Tarefa atribuída a você: ' || NEW.titulo, 
        'task', 
        NEW.id
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_task_assignment() OWNER TO postgres;

--
-- Name: notify_task_completion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_task_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
      profissional_id,
      type,
      title,
      message,
      entity_type,
      entity_id
    )
    SELECT
      id,
      'task_completed',
      'Tarefa concluída',
      NEW.titulo || ' foi concluída',
      'task',
      NEW.id
    FROM profissionais
    WHERE role = 'admin' AND ativo = true;
  END IF;
  RETURN NEW;
END;
$$;


