-- Name: queue_macro_completion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_macro_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN
        VALUES (
            'macro_completed',
            'task',
            NEW.id,
            jsonb_build_object(
                'title', 'Tarefa Concluída',
                'message', 'A tarefa macro "' || NEW.titulo || '" foi concluída.',
                'link', '/admin/tasks'
            )
        )
        ON CONFLICT (entity_id, event_type) WHERE status IN ('pending', 'processing') DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


