-- Name: set_tarefas_concluida_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_tarefas_concluida_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'concluida' AND (OLD.status IS NULL OR OLD.status != 'concluida') THEN
        NEW.concluida_at = now();
    ELSIF NEW.status != 'concluida' AND OLD.status = 'concluida' THEN
        NEW.concluida_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


