--
-- Name: os_dashboard_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.os_dashboard_summary AS
 SELECT id,
    empresa_id,
    titulo,
    status,
    priority,
    deadline,
    assigned_to,
    created_at,
        CASE
            WHEN ((deadline < now()) AND (status <> ALL (ARRAY['completed'::text, 'concluida'::text, 'concluído'::text, 'done'::text]))) THEN true
            ELSE false
        END AS is_overdue
   FROM public.tarefas t;


