--
-- Name: tarefas_com_status_real; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.tarefas_com_status_real AS
 SELECT id,
    cliente_id,
    titulo,
    descricao,
    departamento_id,
    assigned_to,
    created_by,
    deadline,
    priority,
    status,
    em_atraso_desde,
    created_at,
    completed_at,
    area_id,
    requested_by,
    drive_link,
    empresa_id,
    prioridade,
    ((now() > deadline) AND (status <> 'concluida'::text)) AS is_overdue,
        CASE
            WHEN ((now() > deadline) AND (status <> 'concluida'::text)) THEN (EXTRACT(epoch FROM (now() - deadline)) / (3600)::numeric)
            ELSE (0)::numeric
        END AS hours_overdue
   FROM public.tarefas t;


