  WHERE ((ep.empresa_id = empresas.id) AND (ep.profissional_id = auth.uid()) AND (ep.ativo = true)))) OR (public.is_admin_safe() AND (empresa_tipo = 'operacional'::text) AND public.is_admin_of_tenant(tenant_id))));


