CASE
    WHEN (EXISTS ( SELECT 1
       FROM public.profissionais
      WHERE ((profissionais.id = auth.uid()) AND (profissionais.role = 'admin'::text)))) THEN public.check_admin_micro_task_access(id)
    ELSE true
END);


