     JOIN public.empresa_profissionais ep2 ON ((ep1.empresa_id = ep2.empresa_id)))
  WHERE ((ep1.profissional_id = auth.uid()) AND (ep2.profissional_id = profissionais.id) AND (ep1.ativo = true) AND (ep2.ativo = true)))) OR (id = auth.uid())));


