--
-- Name: objects Admins can delete company uploads; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Admins can delete company uploads" ON storage.objects FOR DELETE USING (((bucket_id = 'task-attachments'::text) AND (auth.role() = 'authenticated'::text) AND (EXISTS ( SELECT 1
   FROM (public.empresa_profissionais ep
     JOIN public.profissionais p ON ((p.id = ep.profissional_id)))
  WHERE ((ep.profissional_id = auth.uid()) AND ((ep.empresa_id)::text = (storage.foldername(objects.name))[1]) AND (p.role = 'admin'::text))))));


--
-- Name: objects Company members can view attachments; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Company members can view attachments" ON storage.objects FOR SELECT USING (((bucket_id = 'task-attachments'::text) AND (auth.role() = 'authenticated'::text) AND (EXISTS ( SELECT 1
   FROM public.empresa_profissionais ep
  WHERE ((ep.profissional_id = auth.uid()) AND ((ep.empresa_id)::text = (storage.foldername(objects.name))[1]) AND (ep.ativo = true))))));


--
-- Name: objects Users can delete own uploads; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Users can delete own uploads" ON storage.objects FOR DELETE USING (((bucket_id = 'task-attachments'::text) AND (auth.uid() = owner)));


--
-- Name: objects Users can upload to company folder; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Users can upload to company folder" ON storage.objects FOR INSERT WITH CHECK (((bucket_id = 'task-attachments'::text) AND (auth.role() = 'authenticated'::text) AND (EXISTS ( SELECT 1
   FROM public.empresa_profissionais ep
  WHERE ((ep.profissional_id = auth.uid()) AND ((ep.empresa_id)::text = (storage.foldername(objects.name))[1]) AND (ep.ativo = true))))));


