COPY cron.job (jobid, schedule, command, nodename, nodeport, database, username, active, jobname) FROM stdin;
1	0 * * * *	\n    SELECT net.http_post(\n        url:='https://gyooxmpyxncrezjiljrj.supabase.co/functions/v1/notify-overdue-tasks',\n        headers:='{"Content-Type": "application/json", "Authorization": "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imd5b294bXB5eG5jcmV6amlsanJqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3MzQzNDcxMTYsImV4cCI6MjA0OTkyMzExNn0.Ux7qVJJPjHJGdODnqkJEGqLxSPLBJVxlBqwGVDnOPLk"}'::jsonb,\n        body:='{}'::jsonb\n    ) as request_id;\n    	localhost	5432	postgres	postgres	t	notify-overdue-tasks-hourly
2	*/30 * * * * *	SELECT process_notification_queue();	localhost	5432	postgres	postgres	t	process-notification-queue
3	0 3 * * *	DELETE FROM notification_queue WHERE status IN ('completed', 'failed') AND processed_at < NOW() - INTERVAL '7 days';	localhost	5432	postgres	postgres	t	cleanup-notification-queue
4	*/5 * * * *	\n    SELECT net.http_post(\n        url := 'https://gyooxmpyxncrezjiljrj.supabase.co/functions/v1/meeting-reminders',\n        headers := jsonb_build_object(\n            'Authorization', \n            'Bearer ' || current_setting('app.settings.anon_key')\n        )\n    ) AS request_id;\n    	localhost	5432	postgres	postgres	t	meeting-reminders-cron
