COPY supabase_migrations.schema_migrations (version, statements, name, created_by, idempotency_key, rollback) FROM stdin;
20251215130303	{"-- TVG Flow - Schema Inicial\nCREATE TABLE IF NOT EXISTS clientes (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  nome TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS departamentos (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  nome TEXT NOT NULL UNIQUE,\n  cor_hex TEXT DEFAULT '#6366f1',\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS profissionais (\n  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  nome TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,\n  departamento_id UUID REFERENCES departamentos(id) ON DELETE SET NULL,\n  role TEXT NOT NULL CHECK (role IN ('admin', 'profissional')),\n  ativo BOOLEAN DEFAULT true,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS tarefas (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  cliente_id UUID REFERENCES clientes(id) ON DELETE SET NULL,\n  titulo TEXT NOT NULL,\n  descricao TEXT,\n  departamento_id UUID REFERENCES departamentos(id) ON DELETE SET NULL,\n  assigned_to UUID REFERENCES profissionais(id) ON DELETE SET NULL,\n  created_by UUID REFERENCES profissionais(id) ON DELETE SET NULL,\n  deadline TIMESTAMP WITH TIME ZONE NOT NULL,\n  priority TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'urgent')),\n  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'in_progress', 'completed', 'overdue')),\n  em_atraso_desde TIMESTAMP WITH TIME ZONE,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n  completed_at TIMESTAMP WITH TIME ZONE\n);\n\nCREATE TABLE IF NOT EXISTS arquivos_tarefas (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  tarefa_id UUID REFERENCES tarefas(id) ON DELETE CASCADE,\n  research_drive_link TEXT,\n  final_drive_link TEXT,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS push_subscriptions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  profissional_id UUID REFERENCES profissionais(id) ON DELETE CASCADE,\n  subscription JSONB NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS logs_tarefas (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  tarefa_id UUID REFERENCES tarefas(id) ON DELETE CASCADE,\n  usuario_id UUID REFERENCES profissionais(id) ON DELETE SET NULL,\n  acao TEXT NOT NULL,\n  dados_anteriores JSONB,\n  dados_novos JSONB,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_tarefas_assigned_to ON tarefas(assigned_to);\nCREATE INDEX IF NOT EXISTS idx_tarefas_created_by ON tarefas(created_by);\nCREATE INDEX IF NOT EXISTS idx_tarefas_status ON tarefas(status);\nCREATE INDEX IF NOT EXISTS idx_tarefas_deadline ON tarefas(deadline);\nCREATE INDEX IF NOT EXISTS idx_tarefas_departamento ON tarefas(departamento_id);\nCREATE INDEX IF NOT EXISTS idx_profissionais_departamento ON profissionais(departamento_id);\nCREATE INDEX IF NOT EXISTS idx_profissionais_role ON profissionais(role);\nCREATE INDEX IF NOT EXISTS idx_logs_tarefas_tarefa_id ON logs_tarefas(tarefa_id);\nCREATE INDEX IF NOT EXISTS idx_push_subscriptions_profissional ON push_subscriptions(profissional_id);"}	initial_schema	redestvgmulti@gmail.com	\N	\N
20251215130329	{"-- TVG Flow - Row Level Security (RLS)\nALTER TABLE clientes ENABLE ROW LEVEL SECURITY;\nALTER TABLE departamentos ENABLE ROW LEVEL SECURITY;\nALTER TABLE profissionais ENABLE ROW LEVEL SECURITY;\nALTER TABLE tarefas ENABLE ROW LEVEL SECURITY;\nALTER TABLE arquivos_tarefas ENABLE ROW LEVEL SECURITY;\nALTER TABLE push_subscriptions ENABLE ROW LEVEL SECURITY;\nALTER TABLE logs_tarefas ENABLE ROW LEVEL SECURITY;\n\n-- Helper Functions\nCREATE OR REPLACE FUNCTION is_admin()\nRETURNS BOOLEAN AS $$\nBEGIN\n  RETURN EXISTS (\n    SELECT 1 FROM profissionais\n    WHERE id = auth.uid()\n    AND role = 'admin'\n    AND ativo = true\n  );\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE OR REPLACE FUNCTION is_active_profissional()\nRETURNS BOOLEAN AS $$\nBEGIN\n  RETURN EXISTS (\n    SELECT 1 FROM profissionais\n    WHERE id = auth.uid()\n    AND ativo = true\n  );\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Políticas: profissionais\nCREATE POLICY \\"Admin tem acesso total a profissionais\\"\n  ON profissionais FOR ALL\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Profissional pode ver próprio registro\\"\n  ON profissionais FOR SELECT\n  USING (id = auth.uid() AND ativo = true);\n\n-- Políticas: clientes\nCREATE POLICY \\"Admin tem acesso total a clientes\\"\n  ON clientes FOR ALL\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Profissional pode visualizar clientes\\"\n  ON clientes FOR SELECT\n  USING (is_active_profissional());\n\n-- Políticas: departamentos\nCREATE POLICY \\"Admin tem acesso total a departamentos\\"\n  ON departamentos FOR ALL\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Profissional pode visualizar departamentos\\"\n  ON departamentos FOR SELECT\n  USING (is_active_profissional());\n\n-- Políticas: tarefas\nCREATE POLICY \\"Admin tem acesso total a tarefas\\"\n  ON tarefas FOR ALL\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Profissional pode ver tarefas atribuídas\\"\n  ON tarefas FOR SELECT\n  USING (\n    is_active_profissional() AND \n    (assigned_to = auth.uid() OR created_by = auth.uid())\n  );\n\nCREATE POLICY \\"Profissional pode criar solicitações\\"\n  ON tarefas FOR INSERT\n  WITH CHECK (\n    is_active_profissional() AND \n    created_by = auth.uid()\n  );\n\nCREATE POLICY \\"Profissional pode atualizar tarefas atribuídas\\"\n  ON tarefas FOR UPDATE\n  USING (\n    is_active_profissional() AND \n    assigned_to = auth.uid()\n  )\n  WITH CHECK (\n    is_active_profissional() AND \n    assigned_to = auth.uid()\n  );\n\n-- Políticas: arquivos_tarefas\nCREATE POLICY \\"Admin tem acesso total a arquivos\\"\n  ON arquivos_tarefas FOR ALL\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\nCREATE POLICY \\"Profissional pode ver arquivos de suas tarefas\\"\n  ON arquivos_tarefas FOR SELECT\n  USING (\n    is_active_profissional() AND\n    EXISTS (\n      SELECT 1 FROM tarefas\n      WHERE tarefas.id = arquivos_tarefas.tarefa_id\n      AND (tarefas.assigned_to = auth.uid() OR tarefas.created_by = auth.uid())\n    )\n  );\n\nCREATE POLICY \\"Profissional pode gerenciar arquivos de suas tarefas\\"\n  ON arquivos_tarefas FOR INSERT\n  WITH CHECK (\n    is_active_profissional() AND\n    EXISTS (\n      SELECT 1 FROM tarefas\n      WHERE tarefas.id = arquivos_tarefas.tarefa_id\n      AND tarefas.assigned_to = auth.uid()\n    )\n  );\n\nCREATE POLICY \\"Profissional pode atualizar arquivos de suas tarefas\\"\n  ON arquivos_tarefas FOR UPDATE\n  USING (\n    is_active_profissional() AND\n    EXISTS (\n      SELECT 1 FROM tarefas\n      WHERE tarefas.id = arquivos_tarefas.tarefa_id\n      AND tarefas.assigned_to = auth.uid()\n    )\n  )\n  WITH CHECK (\n    is_active_profissional() AND\n    EXISTS (\n      SELECT 1 FROM tarefas\n      WHERE tarefas.id = arquivos_tarefas.tarefa_id\n      AND tarefas.assigned_to = auth.uid()\n    )\n  );\n\n-- Políticas: push_subscriptions\nCREATE POLICY \\"Profissional gerencia próprias subscriptions\\"\n  ON push_subscriptions FOR ALL\n  USING (profissional_id = auth.uid())\n  WITH CHECK (profissional_id = auth.uid());\n\n-- Políticas: logs_tarefas\nCREATE POLICY \\"Admin pode ver todos os logs\\"\n  ON logs_tarefas FOR SELECT\n  USING (is_admin());\n\nCREATE POLICY \\"Profissional pode ver logs de suas tarefas\\"\n  ON logs_tarefas FOR SELECT\n  USING (\n    is_active_profissional() AND\n    EXISTS (\n      SELECT 1 FROM tarefas\n      WHERE tarefas.id = logs_tarefas.tarefa_id\n      AND (tarefas.assigned_to = auth.uid() OR tarefas.created_by = auth.uid())\n    )\n  );\n\nCREATE POLICY \\"Sistema pode inserir logs\\"\n  ON logs_tarefas FOR INSERT\n  WITH CHECK (true);"}	rls_policies	redestvgmulti@gmail.com	\N	\N
20251217170748	{"-- REMOVER POLÍTICAS ANTIGAS\nDROP POLICY IF EXISTS \\"Profissionais podem ver próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais podem atualizar próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode ver todos profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode inserir profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode atualizar profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais view own profile\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais update own profile\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins view all profiles\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins insert profiles\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins update profiles\\" ON profissionais;\n\n-- CRIAR POLÍTICAS CORRETAS\nCREATE POLICY \\"Profissionais veem próprio perfil\\" ON profissionais FOR SELECT TO authenticated USING (id = auth.uid());\nCREATE POLICY \\"Profissionais atualizam próprio perfil\\" ON profissionais FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());\nCREATE POLICY \\"Admin vê todos perfis\\" ON profissionais FOR SELECT TO authenticated USING ( (SELECT role FROM profissionais WHERE id = auth.uid()) = 'admin' OR id = auth.uid() );\nCREATE POLICY \\"Admin insere profissionais\\" ON profissionais FOR INSERT TO authenticated WITH CHECK ( (SELECT role FROM profissionais WHERE id = auth.uid()) = 'admin' );\nCREATE POLICY \\"Admin atualiza profissionais\\" ON profissionais FOR UPDATE TO authenticated USING ( (SELECT role FROM profissionais WHERE id = auth.uid()) = 'admin' );"}	fix_rls_recursion	redestvgmulti@gmail.com	\N	\N
20251217170910	{"-- Adicionar colunas se não existirem\nDO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'profissionais' AND column_name = 'area_id') THEN ALTER TABLE profissionais ADD COLUMN area_id UUID REFERENCES areas(id); END IF; END $$;\nDO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'tarefas' AND column_name = 'area_id') THEN ALTER TABLE tarefas ADD COLUMN area_id UUID REFERENCES areas(id); END IF; END $$;\nDO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'tarefas' AND column_name = 'requested_by') THEN ALTER TABLE tarefas ADD COLUMN requested_by UUID REFERENCES profissionais(id); END IF; END $$;\n\n-- Criar índices\nCREATE INDEX IF NOT EXISTS idx_profissionais_area ON profissionais(area_id);\nCREATE INDEX IF NOT EXISTS idx_tarefas_area ON tarefas(area_id);\nCREATE INDEX IF NOT EXISTS idx_tarefas_requested_by ON tarefas(requested_by);\n\n-- Remover políticas antigas de tarefas\nDROP POLICY IF EXISTS \\"Professionals view own notifications\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissionais veem tarefas do setor ou solicitadas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissionais podem criar tarefas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissionais atualizam tarefas do setor\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Admin acesso total tarefas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissionais veem tarefas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissionais criam tarefas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissionais editam tarefas do setor\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Admin total\\" ON tarefas;\n\n-- Criar políticas corretas\nCREATE POLICY \\"Profissionais veem tarefas\\" ON tarefas FOR SELECT TO authenticated USING ( EXISTS ( SELECT 1 FROM profissionais p WHERE p.id = auth.uid() AND p.ativo = true AND ( tarefas.area_id IS NULL OR p.area_id = tarefas.area_id OR tarefas.requested_by = p.id ) ) );\nCREATE POLICY \\"Profissionais criam tarefas\\" ON tarefas FOR INSERT TO authenticated WITH CHECK ( EXISTS ( SELECT 1 FROM profissionais WHERE id = auth.uid() AND ativo = true ) );\nCREATE POLICY \\"Profissionais editam tarefas do setor\\" ON tarefas FOR UPDATE TO authenticated USING ( EXISTS ( SELECT 1 FROM profissionais p WHERE p.id = auth.uid() AND p.ativo = true AND p.area_id = tarefas.area_id ) ) WITH CHECK ( EXISTS ( SELECT 1 FROM profissionais p WHERE p.id = auth.uid() AND p.ativo = true AND p.area_id = tarefas.area_id ) );\nCREATE POLICY \\"Admin total\\" ON tarefas FOR ALL TO authenticated USING ( EXISTS ( SELECT 1 FROM profissionais WHERE id = auth.uid() AND role = 'admin' AND ativo = true ) );\n\n-- Triggers\nCREATE OR REPLACE FUNCTION set_requested_by_if_null() RETURNS TRIGGER AS $$ BEGIN IF NEW.requested_by IS NULL THEN NEW.requested_by := auth.uid(); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER;\nDROP TRIGGER IF EXISTS trigger_set_requested_by ON tarefas;\nCREATE TRIGGER trigger_set_requested_by BEFORE INSERT ON tarefas FOR EACH ROW EXECUTE FUNCTION set_requested_by_if_null();\n\nCREATE OR REPLACE FUNCTION notify_task_requested() RETURNS TRIGGER AS $$ BEGIN IF NEW.requested_by IS NOT NULL AND NEW.area_id IS NOT NULL THEN IF (SELECT p.area_id FROM profissionais p WHERE p.id = NEW.requested_by) IS DISTINCT FROM NEW.area_id THEN INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id) SELECT p.id, 'task_requested', 'Nova solicitação recebida', NEW.titulo, 'task', NEW.id FROM profissionais p WHERE p.area_id = NEW.area_id AND p.ativo = true AND p.id != NEW.requested_by; END IF; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER;\nDROP TRIGGER IF EXISTS trigger_notify_task_requested ON tarefas;\nCREATE TRIGGER trigger_notify_task_requested AFTER INSERT ON tarefas FOR EACH ROW EXECUTE FUNCTION notify_task_requested();"}	areas_full_compliance	redestvgmulti@gmail.com	\N	\N
20251217171146	{"-- REMOVER TODAS AS POLÍTICAS DE PROFISSIONAIS\nDROP POLICY IF EXISTS \\"Profissionais podem ver próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais podem atualizar próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode ver todos profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode inserir profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode atualizar profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin pode deletar profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais view own profile\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais update own profile\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins view all profiles\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins insert profiles\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins update profiles\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admins delete profiles\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais veem próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais atualizam próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin vê todos perfis\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin insere profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin atualiza profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin deleta profissionais\\" ON profissionais;\n\n-- CRIAR POLÍTICAS SIMPLES SEM RECURSÃO\n-- Profissionais veem apenas próprio perfil (SEM subquery)\nCREATE POLICY \\"Ver próprio perfil\\" ON profissionais FOR SELECT TO authenticated USING (id = auth.uid());\n\n-- Profissionais atualizam apenas próprio perfil (SEM subquery)\nCREATE POLICY \\"Atualizar próprio perfil\\" ON profissionais FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());\n\n-- Admin vê todos (usando role da própria linha)\nCREATE POLICY \\"Admin vê todos\\" ON profissionais FOR SELECT TO authenticated USING (role = 'admin' OR id = auth.uid());\n\n-- Admin insere (usando role da própria linha do usuário logado)\nCREATE POLICY \\"Admin insere\\" ON profissionais FOR INSERT TO authenticated WITH CHECK ((SELECT role FROM profissionais WHERE id = auth.uid()) = 'admin');\n\n-- Admin atualiza (usando role da própria linha do usuário logado)\nCREATE POLICY \\"Admin atualiza\\" ON profissionais FOR UPDATE TO authenticated USING ((SELECT role FROM profissionais WHERE id = auth.uid()) = 'admin');\n\n-- Admin deleta (usando role da própria linha do usuário logado)\nCREATE POLICY \\"Admin deleta\\" ON profissionais FOR DELETE TO authenticated USING ((SELECT role FROM profissionais WHERE id = auth.uid()) = 'admin');"}	fix_rls_recursion_v2	redestvgmulti@gmail.com	\N	\N
20251217171342	{"-- DESABILITAR RLS TEMPORARIAMENTE\nALTER TABLE profissionais DISABLE ROW LEVEL SECURITY;\n\n-- REMOVER TODAS AS POLÍTICAS\nDROP POLICY IF EXISTS \\"Ver próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Atualizar próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin vê todos\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin insere\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin atualiza\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin deleta\\" ON profissionais;\n\n-- REABILITAR RLS\nALTER TABLE profissionais ENABLE ROW LEVEL SECURITY;\n\n-- CRIAR POLÍTICAS CORRETAS SEM RECURSÃO\n-- Todos autenticados podem ver todos os profissionais (simplificado por enquanto)\nCREATE POLICY \\"Autenticados veem profissionais\\" ON profissionais FOR SELECT TO authenticated USING (true);\n\n-- Profissionais atualizam apenas próprio perfil\nCREATE POLICY \\"Atualizar próprio perfil\\" ON profissionais FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());\n\n-- Apenas service role pode inserir (via Edge Function)\nCREATE POLICY \\"Service role insere\\" ON profissionais FOR INSERT TO service_role WITH CHECK (true);\n\n-- Apenas service role pode deletar\nCREATE POLICY \\"Service role deleta\\" ON profissionais FOR DELETE TO service_role USING (true);"}	disable_rls_profissionais_temp	redestvgmulti@gmail.com	\N	\N
20251217171528	{"-- SOLUÇÃO DEFINITIVA: Desabilitar RLS em profissionais\n-- A autenticação já é feita pelo Supabase Auth, não precisamos de RLS aqui\n\n-- Remover todas as políticas\nDROP POLICY IF EXISTS \\"Autenticados veem profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Atualizar próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Service role insere\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Service role deleta\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Ver próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin vê todos\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin insere\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin atualiza\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin deleta\\" ON profissionais;\n\n-- Desabilitar RLS completamente\nALTER TABLE profissionais DISABLE ROW LEVEL SECURITY;"}	disable_rls_profissionais_final	redestvgmulti@gmail.com	\N	\N
20251217171744	{"-- REATIVAR RLS COM POLÍTICAS SEGURAS (SEM RECURSÃO)\n\n-- Habilitar RLS\nALTER TABLE profissionais ENABLE ROW LEVEL SECURITY;\n\n-- POLÍTICA 1: Todos autenticados podem VER todos os profissionais\n-- (Necessário para o AuthContext funcionar)\nCREATE POLICY \\"Autenticados veem todos\\" \nON profissionais FOR SELECT \nTO authenticated \nUSING (true);\n\n-- POLÍTICA 2: Profissionais podem ATUALIZAR apenas próprio perfil\nCREATE POLICY \\"Atualizar próprio perfil\\" \nON profissionais FOR UPDATE \nTO authenticated \nUSING (id = auth.uid()) \nWITH CHECK (id = auth.uid());\n\n-- POLÍTICA 3: Apenas service_role pode INSERIR\n-- (Via Edge Function create-professional)\nCREATE POLICY \\"Service role insere\\" \nON profissionais FOR INSERT \nTO service_role \nWITH CHECK (true);\n\n-- POLÍTICA 4: Apenas service_role pode DELETAR\nCREATE POLICY \\"Service role deleta\\" \nON profissionais FOR DELETE \nTO service_role \nUSING (true);"}	enable_rls_profissionais_safe	redestvgmulti@gmail.com	\N	\N
20251217172541	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FIX FINAL: RLS INFINITE RECURSION\n-- Uses SECURITY DEFINER function to bypass RLS for admin checks\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- 1. Create a secure function to check admin status\n-- SECURITY DEFINER means this function runs with the privileges of the creator\n-- This bypasses RLS on the table lookup inside it, preventing recursion.\nCREATE OR REPLACE FUNCTION public.check_is_admin()\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  -- Check if the current user has 'admin' role in profissionais table\n  -- This query will NOT trigger RLS because of SECURITY DEFINER\n  RETURN EXISTS (\n    SELECT 1 \n    FROM profissionais \n    WHERE id = auth.uid() \n    AND role = 'admin'\n  );\nEND;\n$$;\n\n-- 2. Drop existing problematic policies\nDROP POLICY IF EXISTS \\"Profissionais veem próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais atualizam próprio perfil\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin vê todos perfis\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin insere profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin atualiza profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Admin deleta profissionais\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais view policy\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais insert policy\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais update policy\\" ON profissionais;\nDROP POLICY IF EXISTS \\"Profissionais delete policy\\" ON profissionais;\n\n-- 3. Recreate policies utilizing the secure function\n\n-- SELECT: Users see themselves OR Admins see everyone\nCREATE POLICY \\"Profissionais view policy\\"\nON profissionais FOR SELECT\nTO authenticated\nUSING (\n  id = auth.uid() \n  OR \n  check_is_admin()\n);\n\n-- INSERT: Only Admins (or service role) can insert\nCREATE POLICY \\"Profissionais insert policy\\"\nON profissionais FOR INSERT\nTO authenticated\nWITH CHECK (\n  check_is_admin()\n);\n\n-- UPDATE: Users can update themselves OR Admins can update anyone\nCREATE POLICY \\"Profissionais update policy\\"\nON profissionais FOR UPDATE\nTO authenticated\nUSING (\n  id = auth.uid() \n  OR \n  check_is_admin()\n)\nWITH CHECK (\n  id = auth.uid() \n  OR \n  check_is_admin()\n);\n\n-- DELETE: Only Admins can delete\nCREATE POLICY \\"Profissionais delete policy\\"\nON profissionais FOR DELETE\nTO authenticated\nUSING (\n  check_is_admin()\n);"}	011_fix_rls_recursion_final	redestvgmulti@gmail.com	\N	\N
20251217174113	{"-- Migration script to fix RLS recursion on 'profissionais' table\n\n-- 1. Drop existing policies to ensure a clean slate and remove recursion\nDROP POLICY IF EXISTS \\"Admin acesso total profissionais\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Profissionais veem a si mesmos\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Admin pode gerenciar profissionais\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Read professionals safely\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Admin manages professionals\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Enable read access for authenticated users\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Enable insert for authenticated users\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"Enable update for users based on email\\" ON \\"public\\".\\"profissionais\\";\n\n-- 2. Create new secure, non-recursive policies\n\n-- SELECT: Admin sees all, Professional sees self\nCREATE POLICY \\"select_profissionais_secure\\"\nON \\"public\\".\\"profissionais\\"\nFOR SELECT\nUSING (\n  (auth.jwt() ->> 'role'::text) = 'admin'::text\n  OR id = auth.uid()\n);\n\n-- INSERT: Only Admin can create professionals\nCREATE POLICY \\"insert_profissionais_admin_only\\"\nON \\"public\\".\\"profissionais\\"\nFOR INSERT\nWITH CHECK (\n  (auth.jwt() ->> 'role'::text) = 'admin'::text\n);\n\n-- UPDATE: Admin can update all, Professional can update self\nCREATE POLICY \\"update_profissionais_secure\\"\nON \\"public\\".\\"profissionais\\"\nFOR UPDATE\nUSING (\n  (auth.jwt() ->> 'role'::text) = 'admin'::text\n  OR id = auth.uid()\n)\nWITH CHECK (\n  (auth.jwt() ->> 'role'::text) = 'admin'::text\n  OR id = auth.uid()\n);\n\n-- DELETE: Only Admin can delete professionals\nCREATE POLICY \\"delete_profissionais_admin_only\\"\nON \\"public\\".\\"profissionais\\"\nFOR DELETE\nUSING (\n  (auth.jwt() ->> 'role'::text) = 'admin'::text\n);"}	fix_rls_recursion_final	redestvgmulti@gmail.com	\N	\N
20251218000908	{"-- Fix RLS policies for profissionais table\n-- The issue: auth.jwt() ->> 'role' doesn't exist in the JWT\n-- We need to check the role from the profissionais table itself\n\n-- Drop existing policies\nDROP POLICY IF EXISTS \\"select_profissionais_secure\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"insert_profissionais_admin_only\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"update_profissionais_secure\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"delete_profissionais_admin_only\\" ON \\"public\\".\\"profissionais\\";\n\n-- SELECT: Admins see all, professionals see all (for collaboration)\n-- This allows the professionals list page to work for all authenticated users\nCREATE POLICY \\"select_profissionais_all_authenticated\\"\nON \\"public\\".\\"profissionais\\"\nFOR SELECT\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais\n    WHERE id = auth.uid()\n    AND ativo = true\n  )\n);\n\n-- INSERT: Only service role (Edge Functions) can insert\nCREATE POLICY \\"insert_profissionais_service_role\\"\nON \\"public\\".\\"profissionais\\"\nFOR INSERT\nTO service_role\nWITH CHECK (true);\n\n-- UPDATE: Admins can update all, professionals can update self\nCREATE POLICY \\"update_profissionais_by_role\\"\nON \\"public\\".\\"profissionais\\"\nFOR UPDATE\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais p\n    WHERE p.id = auth.uid()\n    AND p.ativo = true\n    AND (\n      p.role = 'admin'\n      OR profissionais.id = auth.uid()\n    )\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais p\n    WHERE p.id = auth.uid()\n    AND p.ativo = true\n    AND (\n      p.role = 'admin'\n      OR profissionais.id = auth.uid()\n    )\n  )\n);\n\n-- DELETE: Only admins can delete\nCREATE POLICY \\"delete_profissionais_admin_only\\"\nON \\"public\\".\\"profissionais\\"\nFOR DELETE\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais\n    WHERE id = auth.uid()\n    AND role = 'admin'\n    AND ativo = true\n  )\n);"}	fix_profissionais_rls	redestvgmulti@gmail.com	\N	\N
20260107101301	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Update tarefas SELECT Policy (Etapa 2)\n-- Data: 2026-01-07\n-- Descrição: Unificação de Solicitação e OS - Atualizar policy para:\n--   1. Usar is_admin_safe() ao invés de subquery direta\n--   2. Incluir created_by (staff vê OS que criou)\n--   3. Incluir assigned_to (OS simples visíveis ao atribuído)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Drop policy antiga (migration 029)\nDROP POLICY IF EXISTS \\"Professionals see only assigned tasks via micro-tasks\\" ON tarefas;\n\n-- Criar policy unificada para Etapa 2\nCREATE POLICY \\"Ver OS atribuídas ou criadas\\"\nON tarefas FOR SELECT\nTO authenticated\nUSING (\n    -- Admin vê todas (usando função safe - evita recursão)\n    is_admin_safe()\n    OR\n    -- Criador vê suas OS (incluído na Etapa 1, agora na policy)\n    created_by = auth.uid()\n    OR\n    -- Atribuído direto vê (OS simples)\n    assigned_to = auth.uid()\n    OR\n    -- Atribuído via micro-task vê a macro-task (OS complexa)\n    EXISTS (\n        SELECT 1\n        FROM tarefas_micro tm\n        WHERE tm.tarefa_id = tarefas.id\n        AND tm.profissional_id = auth.uid()\n    )\n);\n\n-- Comentário\nCOMMENT ON POLICY \\"Ver OS atribuídas ou criadas\\" ON tarefas IS \n'ETAPA 2: Unificação de OS. Policy consolida visibilidade para OS simples (created_by, assigned_to) e complexa (micro-tasks). Usa is_admin_safe() para evitar recursão.';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1006: Policy SELECT de tarefas atualizada para Etapa 2 - Unificação de OS';\nEND $$;\n\nCOMMIT;"}	1006_update_tarefas_select_policy	redestvgmulti@gmail.com	\N	\N
20251218001025	{"-- Fix RLS infinite recursion for profissionais table\n-- The issue: Previous policy queried profissionais within profissionais SELECT policy\n-- Solution: Use simple auth.uid() check without subqueries\n\n-- Drop existing policies\nDROP POLICY IF EXISTS \\"select_profissionais_all_authenticated\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"insert_profissionais_service_role\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"update_profissionais_by_role\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"delete_profissionais_admin_only\\" ON \\"public\\".\\"profissionais\\";\n\n-- SELECT: All authenticated users can see all professionals\n-- This is safe because only authenticated users who are in the system can access\nCREATE POLICY \\"select_profissionais_authenticated\\"\nON \\"public\\".\\"profissionais\\"\nFOR SELECT\nTO authenticated\nUSING (true);\n\n-- INSERT: Only service role can insert (via Edge Functions)\nCREATE POLICY \\"insert_profissionais_service_role\\"\nON \\"public\\".\\"profissionais\\"\nFOR INSERT\nTO service_role\nWITH CHECK (true);\n\n-- UPDATE: Users can only update their own record\nCREATE POLICY \\"update_profissionais_own\\"\nON \\"public\\".\\"profissionais\\"\nFOR UPDATE\nTO authenticated\nUSING (id = auth.uid())\nWITH CHECK (id = auth.uid());\n\n-- DELETE: No one can delete via client (only service role if needed)\n-- Admins should deactivate instead of delete\nCREATE POLICY \\"delete_profissionais_none\\"\nON \\"public\\".\\"profissionais\\"\nFOR DELETE\nTO authenticated\nUSING (false);"}	fix_profissionais_rls_no_recursion	redestvgmulti@gmail.com	\N	\N
20251218093511	{"-- Add drive_link column to store Google Drive links directly in tasks\nALTER TABLE tarefas \nADD COLUMN IF NOT EXISTS drive_link TEXT;\n\n-- Migrate final_drive_link from arquivos_tarefas to tarefas.drive_link\n-- This prioritizes final_drive_link, falls back to research_drive_link if final is null\nUPDATE tarefas t\nSET drive_link = COALESCE(\n    (SELECT final_drive_link FROM arquivos_tarefas WHERE tarefa_id = t.id LIMIT 1),\n    (SELECT research_drive_link FROM arquivos_tarefas WHERE tarefa_id = t.id LIMIT 1)\n)\nWHERE EXISTS (\n    SELECT 1 FROM arquivos_tarefas WHERE tarefa_id = t.id\n)\nAND drive_link IS NULL;\n\nCOMMENT ON COLUMN tarefas.drive_link IS 'Google Drive link for task files and resources';"}	013_add_drive_link_to_tasks	redestvgmulti@gmail.com	\N	\N
20251218105604	{"-- TABLE: notifications\nCREATE TABLE IF NOT EXISTS notifications (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  profissional_id UUID NOT NULL REFERENCES profissionais(id) ON DELETE CASCADE,\n  type TEXT NOT NULL,\n  title TEXT NOT NULL,\n  message TEXT NOT NULL,\n  entity_type TEXT,\n  entity_id UUID,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  read_at TIMESTAMPTZ,\n  cleared_at TIMESTAMPTZ\n);\n\n-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_notifications_profissional ON notifications(profissional_id);\nCREATE INDEX IF NOT EXISTS idx_notifications_read ON notifications(read_at) WHERE read_at IS NULL;\nCREATE INDEX IF NOT EXISTS idx_notifications_cleared ON notifications(cleared_at) WHERE cleared_at IS NULL;\nCREATE INDEX IF NOT EXISTS idx_notifications_created ON notifications(created_at DESC);\n\n-- RLS POLICIES\nALTER TABLE notifications ENABLE ROW LEVEL SECURITY;\n\nDO $$ \nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'notifications' AND policyname = 'Professionals view own notifications') THEN\n        CREATE POLICY \\"Professionals view own notifications\\" ON notifications FOR SELECT TO authenticated USING (profissional_id = auth.uid());\n    END IF;\n    \n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'notifications' AND policyname = 'Professionals update own notifications') THEN\n        CREATE POLICY \\"Professionals update own notifications\\" ON notifications FOR UPDATE TO authenticated USING (profissional_id = auth.uid()) WITH CHECK (profissional_id = auth.uid());\n    END IF;\n    \n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'notifications' AND policyname = 'Admins view all notifications') THEN\n        CREATE POLICY \\"Admins view all notifications\\" ON notifications FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM profissionais WHERE profissionais.id = auth.uid() AND profissionais.role = 'admin' AND profissionais.ativo = true));\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'notifications' AND policyname = 'Admins insert notifications') THEN\n        CREATE POLICY \\"Admins insert notifications\\" ON notifications FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM profissionais WHERE profissionais.id = auth.uid() AND profissionais.role = 'admin' AND profissionais.ativo = true));\n    END IF;\n    \n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'notifications' AND policyname = 'System insert notifications') THEN\n        CREATE POLICY \\"System insert notifications\\" ON notifications FOR INSERT TO authenticated WITH CHECK (true);\n    END IF;\nEND $$;\n\n-- TRIGGER: Task Assigned/Reassigned\nCREATE OR REPLACE FUNCTION notify_task_assignment()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Only if assigned_to changed and new assignee exists and is active\n  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL THEN\n    IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n      INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n      VALUES (NEW.assigned_to, 'task_assigned', 'New task assigned', 'You have been assigned: ' || NEW.titulo, 'task', NEW.id);\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS trigger_notify_task_assignment ON tarefas;\nCREATE TRIGGER trigger_notify_task_assignment AFTER UPDATE ON tarefas FOR EACH ROW EXECUTE FUNCTION notify_task_assignment();\n\n-- TRIGGER: Task Completed\nCREATE OR REPLACE FUNCTION notify_task_completion()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Only if status changed to completed\n  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN\n    INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n    SELECT id, 'task_completed', 'Task completed', NEW.titulo || ' has been completed', 'task', NEW.id\n    FROM profissionais WHERE role = 'admin' AND ativo = true;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS trigger_notify_task_completion ON tarefas;\nCREATE TRIGGER trigger_notify_task_completion AFTER UPDATE ON tarefas FOR EACH ROW EXECUTE FUNCTION notify_task_completion();\n\nCOMMENT ON TABLE notifications IS 'Persistent notification center with audit trail';"}	005_notifications	redestvgmulti@gmail.com	\N	\N
20251218105625	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Fix: Add trigger for INSERT on tasks to notify assignments\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nDROP TRIGGER IF EXISTS trigger_notify_task_assignment_insert ON tarefas;\n\nCREATE TRIGGER trigger_notify_task_assignment_insert\nAFTER INSERT ON tarefas\nFOR EACH ROW\nEXECUTE FUNCTION notify_task_assignment();"}	014_fix_notification_trigger	redestvgmulti@gmail.com	\N	\N
20251219123841	{"UPDATE public.tarefas\nSET departamento_id = NULL\nWHERE departamento_id IS NOT NULL \n  AND departamento_id NOT IN (SELECT id FROM public.areas);\n\nALTER TABLE public.tarefas\nDROP CONSTRAINT IF EXISTS tarefas_departamento_id_fkey;\n\nALTER TABLE public.tarefas\nADD CONSTRAINT tarefas_departamento_id_fkey\nFOREIGN KEY (departamento_id)\nREFERENCES public.areas(id)\nON DELETE SET NULL;"}	fix_tarefas_fk_areas	redestvgmulti@gmail.com	\N	\N
20251219124113	{"CREATE OR REPLACE FUNCTION notify_task_details_change()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Check if assigned professional exists and is active\n  IF NEW.assigned_to IS NOT NULL AND EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n    \n    -- Check if the update was made by someone else (avoid self-notification)\n    IF auth.uid() IS DISTINCT FROM NEW.assigned_to THEN\n      \n      -- Detect meaningful changes\n      IF (NEW.titulo IS DISTINCT FROM OLD.titulo) OR\n         (NEW.descricao IS DISTINCT FROM OLD.descricao) OR\n         (NEW.deadline IS DISTINCT FROM OLD.deadline) OR\n         (NEW.priority IS DISTINCT FROM OLD.priority) OR\n         (NEW.status IS DISTINCT FROM OLD.status) OR\n         (NEW.drive_link IS DISTINCT FROM OLD.drive_link) THEN\n         \n         INSERT INTO notifications (\n           profissional_id,\n           type,\n           title,\n           message,\n           entity_type,\n           entity_id\n         )\n         VALUES (\n           NEW.assigned_to,\n           'task_updated',\n           'Tarefa Atualizada',\n           'A tarefa \\"' || NEW.titulo || '\\" foi atualizada.',\n           'task',\n           NEW.id\n         );\n      END IF;\n    END IF;\n  END IF;\n  \n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS trigger_notify_task_details_change ON tarefas;\n\nCREATE TRIGGER trigger_notify_task_details_change\nAFTER UPDATE ON tarefas\nFOR EACH ROW\nEXECUTE FUNCTION notify_task_details_change();"}	notify_task_updates	redestvgmulti@gmail.com	\N	\N
20251225184451	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Enable Realtime for notifications table\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Enable realtime publication for notifications table\nALTER PUBLICATION supabase_realtime ADD TABLE notifications;\n\n-- Ensure RLS is enabled (should already be, but confirming)\nALTER TABLE notifications ENABLE ROW LEVEL SECURITY;\n\n-- Verify that users can SELECT their own notifications (required for realtime)\n-- This policy should already exist, but we'll recreate it to be sure\nDROP POLICY IF EXISTS \\"Professionals view own notifications\\" ON notifications;\n\nCREATE POLICY \\"Professionals view own notifications\\"\nON notifications FOR SELECT\nTO authenticated\nUSING (profissional_id = auth.uid());"}	enable_realtime_notifications	redestvgmulti@gmail.com	\N	\N
20251221190559	{"-- 1. Create task_comments table\ncreate table if not exists public.task_comments (\n  id uuid primary key default gen_random_uuid(),\n  task_id uuid not null references public.tarefas(id) on delete cascade,\n  author_id uuid not null references public.profissionais(id),\n  content text not null,\n  created_at timestamptz default now()\n);\n\n-- 2. Create task_history table\ncreate table if not exists public.task_history (\n  id uuid primary key default gen_random_uuid(),\n  task_id uuid not null references public.tarefas(id) on delete cascade,\n  event text not null,\n  created_at timestamptz default now()\n);\n\n-- 3. Enable RLS\nalter table public.task_comments enable row level security;\nalter table public.task_history enable row level security;\n\n-- 4. RLS for task_comments\n-- Select: If you can see the task, you can see the comments\ncreate policy \\"View comments of accessible tasks\\"\n  on public.task_comments for select\n  using (task_id in (select id from public.tarefas));\n\n-- Insert: If you can see (access) the task, you can comment\ncreate policy \\"Comment on accessible tasks\\"\n  on public.task_comments for insert\n  with check (task_id in (select id from public.tarefas));\n\n-- Update: Only author can update their own comments\ncreate policy \\"Update own comments\\"\n  on public.task_comments for update\n  using (author_id = auth.uid());\n\n-- Delete: Only admin can delete (or author?) - Restriction to Admin for safety as per prompt\n-- Assuming 'admin' check involves strict logic or simply deny for now for staff.\n-- Let's allow admins.\ncreate policy \\"Admins can delete comments\\"\n  on public.task_comments for delete\n  using (exists (select 1 from public.profissionais where id = auth.uid() and role = 'admin'));\n\n\n-- 5. RLS for task_history\n-- Select: If you can see the task, you can see the history\ncreate policy \\"View history of accessible tasks\\"\n  on public.task_history for select\n  using (task_id in (select id from public.tarefas));\n\n-- Insert: BLOCKED for everyone via Frontend (only Trigger/Service Role)\n-- No INSERT policy = implicit deny for anon/authenticated roles.\n\n\n-- 6. Trigger Function for History\ncreate or replace function public.log_task_history()\nreturns trigger as $$\ndeclare\n  history_event text;\nbegin\n  -- Status Change\n  if (old.status is distinct from new.status) then\n    history_event := 'Status alterado para ' || \n      case \n        when new.status = 'pending' then 'Pendente'\n        when new.status = 'in_progress' then 'Em andamento'\n        when new.status = 'completed' then 'Concluído'\n        else new.status\n      end;\n      \n    insert into public.task_history (task_id, event)\n    values (new.id, history_event);\n  end if;\n\n  -- Priority Change\n  if (old.priority is distinct from new.priority) then\n    insert into public.task_history (task_id, event)\n    values (new.id, 'Prioridade alterada para ' || new.priority);\n  end if;\n\n  -- Deadline Change\n  if (old.deadline is distinct from new.deadline) then\n    insert into public.task_history (task_id, event)\n    values (new.id, 'Prazo atualizado');\n  end if;\n\n  -- Assignment Change\n  if (old.assigned_to is distinct from new.assigned_to) then\n    insert into public.task_history (task_id, event)\n    values (new.id, 'Tarefa reatribuída');\n  end if;\n\n  return new;\nend;\n$$ language plpgsql security definer;\n\n-- 7. Apply Trigger\ndrop trigger if exists on_task_change on public.tarefas;\ncreate trigger on_task_change\nafter update on public.tarefas\nfor each row execute function public.log_task_history();\n\n-- Grant permissions (if needed for authenticated)\ngrant select, insert, update on public.task_comments to authenticated;\ngrant select on public.task_history to authenticated;\n"}	create_comments_and_history	redestvgmulti@gmail.com	\N	\N
20251221235700	{"CREATE OR REPLACE FUNCTION notify_task_assignment()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL THEN\n    IF EXISTS (\n      SELECT 1 FROM profissionais \n      WHERE id = NEW.assigned_to AND ativo = true\n    ) THEN\n      INSERT INTO notifications (\n        profissional_id,\n        type,\n        title,\n        message,\n        entity_type,\n        entity_id\n      )\n      VALUES (\n        NEW.assigned_to,\n        'task_assigned',\n        'Nova tarefa atribuída',\n        'Você foi designado para: ' || NEW.titulo,\n        'task',\n        NEW.id\n      );\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE OR REPLACE FUNCTION notify_task_completion()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN\n    INSERT INTO notifications (\n      profissional_id,\n      type,\n      title,\n      message,\n      entity_type,\n      entity_id\n    )\n    SELECT\n      id,\n      'task_completed',\n      'Tarefa concluída',\n      NEW.titulo || ' foi concluída',\n      'task',\n      NEW.id\n    FROM profissionais\n    WHERE role = 'admin' AND ativo = true;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;"}	update_notifications_to_pt	redestvgmulti@gmail.com	\N	\N
20251221235714	{"UPDATE notifications \nSET \n  title = 'Nova tarefa atribuída', \n  message = REPLACE(message, 'You have been assigned: ', 'Você foi designado para: ')\nWHERE type = 'task_assigned' AND title = 'New task assigned';\n\nUPDATE notifications \nSET \n  title = 'Tarefa concluída', \n  message = REPLACE(message, ' has been completed', ' foi concluída')\nWHERE type = 'task_completed' AND title = 'Task completed';"}	translate_existing_notifications	redestvgmulti@gmail.com	\N	\N
20251222002356	{"-- Table to store Web Push subscriptions\nCREATE TABLE IF NOT EXISTS push_subscriptions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  profissional_id UUID NOT NULL REFERENCES profissionais(id) ON DELETE CASCADE,\n  endpoint TEXT NOT NULL,\n  p256dh_key TEXT NOT NULL,\n  auth_key TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(profissional_id, endpoint)\n);\n\n-- Index for faster lookups\nCREATE INDEX IF NOT EXISTS idx_push_subscriptions_profissional ON push_subscriptions(profissional_id);\n\n-- Enable RLS\nALTER TABLE push_subscriptions ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nDO $$ \nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'push_subscriptions' AND policyname = 'Users view own subscriptions') THEN\n        CREATE POLICY \\"Users view own subscriptions\\" ON push_subscriptions FOR SELECT TO authenticated USING (profissional_id = auth.uid());\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'push_subscriptions' AND policyname = 'Users insert own subscriptions') THEN\n        CREATE POLICY \\"Users insert own subscriptions\\" ON push_subscriptions FOR INSERT TO authenticated WITH CHECK (profissional_id = auth.uid());\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'push_subscriptions' AND policyname = 'Users delete own subscriptions') THEN\n        CREATE POLICY \\"Users delete own subscriptions\\" ON push_subscriptions FOR DELETE TO authenticated USING (profissional_id = auth.uid());\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'push_subscriptions' AND policyname = 'Service role read all') THEN\n        CREATE POLICY \\"Service role read all\\" ON push_subscriptions FOR SELECT TO service_role USING (true);\n    END IF;\nEND $$;"}	create_push_subscriptions_table	redestvgmulti@gmail.com	\N	\N
20251222002441	{"-- Enable pg_net extension for HTTP requests\nCREATE EXTENSION IF NOT EXISTS \\"pg_net\\";\n\n-- Function to call Edge Function\nCREATE OR REPLACE FUNCTION trigger_send_push_notification()\nRETURNS TRIGGER AS $$\nDECLARE\n  url TEXT := 'https://gyooxmpyxncrezjiljrj.supabase.co/functions/v1/send-push-notification';\n  api_key TEXT := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imd5b294bXB5eG5jcmV6amlsanJqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjU4MDE2MzUsImV4cCI6MjA4MTM3NzYzNX0.mn0Y66MZ6DHxdyMg2Oh6bSIi2CC5h8RmN5N4hlyqhog';\n  payload JSONB;\n  request_id BIGINT;\nBEGIN\n  payload := jsonb_build_object('notificationId', NEW.id);\n  \n  -- Call Edge Function asynchronously\n  SELECT net.http_post(\n    url := url,\n    body := payload,\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer ' || api_key\n    )\n  ) INTO request_id;\n  \n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Create Trigger\nDROP TRIGGER IF EXISTS trigger_push_notification_on_insert ON notifications;\n\nCREATE TRIGGER trigger_push_notification_on_insert\nAFTER INSERT ON notifications\nFOR EACH ROW\nEXECUTE FUNCTION trigger_send_push_notification();"}	setup_push_trigger	redestvgmulti@gmail.com	\N	\N
20251226000432	{"ALTER TABLE tarefas_micro DROP CONSTRAINT IF EXISTS tarefas_micro_status_check;\nALTER TABLE tarefas_micro DROP CONSTRAINT IF EXISTS micro_status_check;\nALTER TABLE tarefas_micro ADD CONSTRAINT tarefas_micro_status_check CHECK (status IN ('pendente', 'em_progresso', 'concluida', 'bloqueada'));\nUPDATE tarefas_micro SET status = 'pendente' WHERE status NOT IN ('pendente', 'em_progresso', 'concluida', 'bloqueada');"}	fix_micro_constraint_final_20251226	redestvgmulti@gmail.com	\N	\N
20251222004403	{"CREATE OR REPLACE FUNCTION notify_task_assignment()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Handle INSERT: If new task has assignee\n  IF (TG_OP = 'INSERT') THEN\n    IF NEW.assigned_to IS NOT NULL THEN\n       -- Check if assignee exists and is active\n       IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n          INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n          VALUES (\n            NEW.assigned_to, \n            'task_assigned', \n            'Nova Tarefa', \n            'Uma nova tarefa foi atribuída a você: ' || NEW.titulo, \n            'task', \n            NEW.id\n          );\n       END IF;\n    END IF;\n\n  -- Handle UPDATE: If assignee changed\n  ELSIF (TG_OP = 'UPDATE') THEN\n    IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL THEN\n       IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n          INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n          VALUES (\n            NEW.assigned_to, \n            'task_assigned', \n            'Nova Atribuição', \n            'Tarefa atribuída a você: ' || NEW.titulo, \n            'task', \n            NEW.id\n          );\n       END IF;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS trigger_notify_task_assignment ON tarefas;\n\nCREATE TRIGGER trigger_notify_task_assignment\nAFTER INSERT OR UPDATE ON tarefas\nFOR EACH ROW\nEXECUTE FUNCTION notify_task_assignment();"}	fix_notifications_on_insert	redestvgmulti@gmail.com	\N	\N
