20251222115802	{"-- Ensure columns exist (in case table was created with old schema)\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'push_subscriptions' AND column_name = 'auth_key') THEN\n        ALTER TABLE push_subscriptions ADD COLUMN auth_key TEXT;\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'push_subscriptions' AND column_name = 'p256dh_key') THEN\n        ALTER TABLE push_subscriptions ADD COLUMN p256dh_key TEXT;\n    END IF;\nEND $$;\n\n-- Force PostgREST schema cache reload\nNOTIFY pgrst, 'reload schema';"}	fix_push_schema_and_reload	redestvgmulti@gmail.com	\N	\N
20251222120312	{"-- Drop existing table if it exists (cleanup)\nDROP TABLE IF EXISTS push_subscriptions CASCADE;\n\n-- Create push_subscriptions table with ALL required columns\nCREATE TABLE push_subscriptions (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    profissional_id UUID NOT NULL REFERENCES profissionais(id) ON DELETE CASCADE,\n    endpoint TEXT NOT NULL,\n    auth_key TEXT NOT NULL,\n    p256dh_key TEXT NOT NULL,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    UNIQUE(profissional_id, endpoint)\n);\n\n-- Enable RLS\nALTER TABLE push_subscriptions ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\nCREATE POLICY \\"Users view own subscriptions\\"\nON push_subscriptions FOR SELECT\nTO authenticated\nUSING (profissional_id = auth.uid());\n\nCREATE POLICY \\"Users insert own subscriptions\\"\nON push_subscriptions FOR INSERT\nTO authenticated\nWITH CHECK (profissional_id = auth.uid());\n\nCREATE POLICY \\"Users update own subscriptions\\"\nON push_subscriptions FOR UPDATE\nTO authenticated\nUSING (profissional_id = auth.uid())\nWITH CHECK (profissional_id = auth.uid());\n\nCREATE POLICY \\"Users delete own subscriptions\\"\nON push_subscriptions FOR DELETE\nTO authenticated\nUSING (profissional_id = auth.uid());\n\n-- Index for performance\nCREATE INDEX idx_push_subscriptions_profissional ON push_subscriptions(profissional_id);\n\n-- Comment for documentation\nCOMMENT ON TABLE push_subscriptions IS 'Web Push notification subscriptions for users';\n\n-- Force PostgREST to reload schema\nNOTIFY pgrst, 'reload schema';"}	recreate_push_subscriptions_complete	redestvgmulti@gmail.com	\N	\N
20251223153546	{"\n-- 1. Create empresa_profissionais table (Mapping Empresas concept to Clientes table)\nCREATE TABLE IF NOT EXISTS public.empresa_profissionais (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    empresa_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,\n    profissional_id UUID NOT NULL REFERENCES public.profissionais(id) ON DELETE CASCADE,\n    funcao TEXT NOT NULL,\n    ativo BOOLEAN DEFAULT true,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    UNIQUE(empresa_id, profissional_id, funcao)\n);\n\n-- Enable RLS\nALTER TABLE public.empresa_profissionais ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY \\"Admins can do everything on empresa_profissionais\\"\n    ON public.empresa_profissionais\n    FOR ALL\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.profissionais\n            WHERE id = auth.uid() AND role = 'admin'\n        )\n    );\n\nCREATE POLICY \\"Professionals can view their own links\\"\n    ON public.empresa_profissionais\n    FOR SELECT\n    USING (\n        profissional_id = auth.uid()\n    );\n\n-- 2. Create tarefas_itens table\nCREATE TABLE IF NOT EXISTS public.tarefas_itens (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    tarefa_id UUID NOT NULL REFERENCES public.tarefas(id) ON DELETE CASCADE,\n    profissional_id UUID NOT NULL REFERENCES public.profissionais(id),\n    funcao_snapshot TEXT NOT NULL,\n    status TEXT DEFAULT 'pendente' CHECK (status IN ('pendente', 'em_progresso', 'concluida')),\n    entrega_link TEXT,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Enable RLS\nALTER TABLE public.tarefas_itens ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY \\"Admins can do everything on tarefas_itens\\"\n    ON public.tarefas_itens\n    FOR ALL\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.profissionais\n            WHERE id = auth.uid() AND role = 'admin'\n        )\n    );\n\nCREATE POLICY \\"Professionals can view and update their own items\\"\n    ON public.tarefas_itens\n    FOR ALL\n    USING (\n        profissional_id = auth.uid()\n    );\n\n-- 3. Ensure tarefas has empresa_id linked to Clientes\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'tarefas' AND column_name = 'empresa_id') THEN\n        ALTER TABLE public.tarefas ADD COLUMN empresa_id UUID REFERENCES public.clientes(id);\n    END IF;\nEND $$;\n"}	create_architecture_tables_v2	redestvgmulti@gmail.com	\N	\N
