20251228202551	{"-- Add tenant_id and empresa_tipo fields to distinguish tenant vs operational companies\nALTER TABLE empresas \nADD COLUMN IF NOT EXISTS tenant_id UUID REFERENCES empresas(id),\nADD COLUMN IF NOT EXISTS empresa_tipo text NOT NULL DEFAULT 'operacional' \nCHECK (empresa_tipo IN ('tenant', 'operacional'));\n\n-- Update existing companies based on context\n-- Companies without tenant_id or where tenant_id = id are tenants\nUPDATE empresas \nSET empresa_tipo = 'tenant' \nWHERE tenant_id IS NULL OR tenant_id = id;\n\n-- Drop and recreate RLS policies for empresas table\n\n-- Super Admin: full access to tenant companies only\nDROP POLICY IF EXISTS \\"super_admin_empresas_select\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_select\\" ON empresas\nFOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n);\n\nDROP POLICY IF EXISTS \\"super_admin_empresas_insert\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_insert\\" ON empresas\nFOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n);\n\nDROP POLICY IF EXISTS \\"super_admin_empresas_update\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_update\\" ON empresas\nFOR UPDATE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n);\n\nDROP POLICY IF EXISTS \\"super_admin_empresas_delete\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_delete\\" ON empresas\nFOR DELETE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n);\n\n-- Admin: access to operational companies within their tenant only\nDROP POLICY IF EXISTS \\"admin_empresas_select\\" ON empresas;\nCREATE POLICY \\"admin_empresas_select\\" ON empresas\nFOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'admin'\n    AND EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = profissionais.id\n      AND ep.empresa_id = empresas.tenant_id\n    )\n  )\n  AND empresa_tipo = 'operacional'\n);\n\nDROP POLICY IF EXISTS \\"admin_empresas_insert\\" ON empresas;\nCREATE POLICY \\"admin_empresas_insert\\" ON empresas\nFOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'admin'\n    AND EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = profissionais.id\n      AND ep.empresa_id = empresas.tenant_id\n    )\n  )\n  AND empresa_tipo = 'operacional'\n);\n\nDROP POLICY IF EXISTS \\"admin_empresas_update\\" ON empresas;\nCREATE POLICY \\"admin_empresas_update\\" ON empresas\nFOR UPDATE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'admin'\n    AND EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = profissionais.id\n      AND ep.empresa_id = empresas.tenant_id\n    )\n  )\n  AND empresa_tipo = 'operacional'\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'admin'\n    AND EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = profissionais.id\n      AND ep.empresa_id = empresas.tenant_id\n    )\n  )\n  AND empresa_tipo = 'operacional'\n);\n\nDROP POLICY IF EXISTS \\"admin_empresas_delete\\" ON empresas;\nCREATE POLICY \\"admin_empresas_delete\\" ON empresas\nFOR DELETE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'admin'\n    AND EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = profissionais.id\n      AND ep.empresa_id = empresas.tenant_id\n    )\n  )\n  AND empresa_tipo = 'operacional'\n);\n"}	add_empresa_tipo	redestvgmulti@gmail.com	\N	\N
20251224110415	{"-- HARDENING FINAL: Restrict Manual Updates on Macro Tasks\n-- Description: \n-- 1. Revoke UPDATE permission on 'tarefas' for professionals (Admins only).\n-- 2. Expand SELECT permission to allow visibility if user has a micro-task.\n\n-- 1. Drop existing policies regarding Professionals (including the one we want to create to be idempotent)\nDROP POLICY IF EXISTS \\"Profissional pode atualizar tarefas atribuídas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissional pode ver tarefas atribuídas\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Profissional pode visualizar tarefas\\" ON tarefas;\n\n-- 2. Re-create SELECT Policy (Enhanced)\n-- Allows viewing if:\n-- a) Assigned to task\n-- b) Created the task\n-- c) Has a micro-task in this task\nCREATE POLICY \\"Profissional pode visualizar tarefas\\"\nON tarefas FOR SELECT\nTO authenticated\nUSING (\n    (\n        -- Must be active professional\n        EXISTS (SELECT 1 FROM profissionais WHERE id = auth.uid() AND ativo = true)\n    )\n    AND \n    (\n        assigned_to = auth.uid() \n        OR \n        created_by = auth.uid()\n        OR\n        EXISTS (\n            SELECT 1 FROM tarefas_itens \n            WHERE tarefas_itens.tarefa_id = tarefas.id \n            AND tarefas_itens.profissional_id = auth.uid()\n        )\n    )\n);\n\n-- 3. Ensure Admin Policy still covers everything (Idempotent check)\n-- (Assuming \\"Admin tem acesso total a tarefas\\" exists from 002_rls_policies.sql)\n-- If we need to be sure, we can recreate it, but usually standard admin policy is stable.\n-- We will just make sure no other UPDATE policy allows professionals.\n\n-- 4. Verify no loose UPDATE policies exist\n-- The default is DENY. So by deleting the ONLY professional update policy, we default to blocking them.\n-- Admin policy 'FOR ALL' will still allow admins.\n\n-- Comment\nCOMMENT ON TABLE tarefas IS 'Tarefas macro. Updates restricted to Admins or via Triggers.';"}	20251224140000_harden_tarefas_rls_retry	redestvgmulti@gmail.com	\N	\N
20251224110420	{"-- FIX: Re-create Report RPCs (Fix for PGRST202 error)\n-- Description: \n-- The frontend is calling 'get_client_stats', 'get_role_stats', etc. \n-- This migration ensures these functions exist in the public schema.\n\n-- 1. Get Client/Company Stats\nCREATE OR REPLACE FUNCTION get_client_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    client_id UUID,\n    client_name TEXT,\n    total_tasks BIGINT,\n    completed_tasks BIGINT,\n    overdue_tasks BIGINT,\n    avg_resolution_time_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.id,\n        e.nome,\n        COUNT(t.id) as total_tasks,\n        COUNT(t.id) FILTER (WHERE t.status IN ('completed', 'concluida')) as completed_tasks,\n        COUNT(t.id) FILTER (\n            WHERE t.status NOT IN ('completed', 'concluida') \n            AND t.deadline < now()\n        ) as overdue_tasks,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(t.completed_at, now()) - t.created_at))/3600\n            ) FILTER (WHERE t.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_resolution_time_hours\n    FROM empresas e\n    LEFT JOIN tarefas t ON t.empresa_id = e.id\n    WHERE (start_date IS NULL OR t.created_at >= start_date)\n      AND (end_date IS NULL OR t.created_at <= end_date)\n    GROUP BY e.id, e.nome\n    ORDER BY total_tasks DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Get Role Stats (Funcão)\nCREATE OR REPLACE FUNCTION get_role_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    role_name TEXT,\n    total_items BIGINT,\n    completed_items BIGINT,\n    avg_completion_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        ti.funcao_snapshot as role_name,\n        COUNT(ti.id) as total_items,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_items,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(ti.concluida_at, now()) - ti.created_at))/3600\n            ) FILTER (WHERE ti.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_completion_hours\n    FROM tarefas_itens ti\n    WHERE ti.funcao_snapshot IS NOT NULL\n      AND (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY ti.funcao_snapshot\n    ORDER BY total_items DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 3. Get Staff Stats (Colaborador)\nCREATE OR REPLACE FUNCTION get_staff_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    staff_id UUID,\n    staff_name TEXT,\n    total_assigned BIGINT,\n    completed_count BIGINT,\n    overdue_count BIGINT,\n    efficiency_score NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id,\n        p.nome,\n        COUNT(ti.id) as total_assigned,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_count,\n        -- Overdue micro-tasks (if parent task is overdue and micro-task is not done)\n        COUNT(ti.id) FILTER (\n            WHERE ti.status NOT IN ('completed', 'concluida')\n            AND EXISTS (\n                SELECT 1 FROM tarefas t \n                WHERE t.id = ti.tarefa_id \n                AND t.deadline < now()\n            )\n        ) as overdue_count,\n        -- Simple efficiency score: (Completed / Total) * 100\n        CASE \n            WHEN COUNT(ti.id) > 0 THEN \n                (COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida'))::NUMERIC / COUNT(ti.id)::NUMERIC) * 100\n            ELSE 0 \n        END::NUMERIC(5,2) as efficiency_score\n    FROM profissionais p\n    JOIN tarefas_itens ti ON ti.profissional_id = p.id\n    WHERE (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY p.id, p.nome\n    ORDER BY completed_count DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Grant permissions again just in case\nGRANT EXECUTE ON FUNCTION get_client_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_role_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_staff_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;"}	20251224153000_fix_reports_rpc	redestvgmulti@gmail.com	\N	\N
20251224110422	{"-- FIX CLIENTES SCHEMA AND RLS\n-- Description:\n-- 1. Companies.jsx uses 'clientes' table but expects 'ativo' and 'cnpj' columns which were missing in 001_initial_schema.\n-- 2. RLS policy for 'clientes' needs to be re-asserted to ensure Admins can manage them.\n\n-- 1. Schema Updates\nALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS ativo BOOLEAN DEFAULT true;\nALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS cnpj TEXT;\n\n-- 2. RLS Fixes\nALTER TABLE public.clientes ENABLE ROW LEVEL SECURITY;\n\n-- Drop potentially conflicting or broken policies\nDROP POLICY IF EXISTS \\"Admin tem acesso total a clientes\\" ON public.clientes;\nDROP POLICY IF EXISTS \\"Profissional pode visualizar clientes\\" ON public.clientes;\n\n-- Re-create Admin Policy (Full Access)\nCREATE POLICY \\"Admin tem acesso total a clientes\\"\n    ON public.clientes\n    FOR ALL\n    TO authenticated\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.profissionais\n            WHERE id = auth.uid()\n            AND role = 'admin'\n        )\n    );\n\n-- Re-create Professional Policy (Read Only)\nCREATE POLICY \\"Profissional pode visualizar clientes\\"\n    ON public.clientes\n    FOR SELECT\n    TO authenticated\n    USING (\n        EXISTS (\n            SELECT 1 FROM public.profissionais\n            WHERE id = auth.uid()\n            AND ativo = true\n        )\n    );\n\n-- Comment\nCOMMENT ON TABLE public.clientes IS 'Tabela principal de Empresas/Clientes';"}	20251224160000_fix_clientes_schema_and_rls	redestvgmulti@gmail.com	\N	\N
20251224110553	{"-- FIX: Re-create Report RPCs (Fix for PGRST202 error & Missing Table)\n-- Description: \n-- 1. Updates get_client_stats to query 'clientes' table (not 'empresas').\n-- 2. Ensures logic handles potential nulls correctly.\n\n-- 1. Get Client/Company Stats\nCREATE OR REPLACE FUNCTION get_client_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    client_id UUID,\n    client_name TEXT,\n    total_tasks BIGINT,\n    completed_tasks BIGINT,\n    overdue_tasks BIGINT,\n    avg_resolution_time_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        c.id as client_id,\n        c.nome as client_name,\n        COUNT(t.id) as total_tasks,\n        COUNT(t.id) FILTER (WHERE t.status IN ('completed', 'concluida')) as completed_tasks,\n        COUNT(t.id) FILTER (\n            WHERE t.status NOT IN ('completed', 'concluida') \n            AND t.deadline < now()\n        ) as overdue_tasks,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(t.completed_at, now()) - t.created_at))/3600\n            ) FILTER (WHERE t.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_resolution_time_hours\n    FROM clientes c\n    LEFT JOIN tarefas t ON t.cliente_id = c.id\n    WHERE (start_date IS NULL OR t.created_at >= start_date)\n      AND (end_date IS NULL OR t.created_at <= end_date)\n    GROUP BY c.id, c.nome\n    ORDER BY total_tasks DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Get Role Stats (Funcão)\nCREATE OR REPLACE FUNCTION get_role_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    role_name TEXT,\n    total_items BIGINT,\n    completed_items BIGINT,\n    avg_completion_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        ti.funcao_snapshot as role_name,\n        COUNT(ti.id) as total_items,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_items,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(ti.concluida_at, now()) - ti.created_at))/3600\n            ) FILTER (WHERE ti.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_completion_hours\n    FROM tarefas_itens ti\n    WHERE ti.funcao_snapshot IS NOT NULL\n      AND (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY ti.funcao_snapshot\n    ORDER BY total_items DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 3. Get Staff Stats (Colaborador)\nCREATE OR REPLACE FUNCTION get_staff_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    staff_id UUID,\n    staff_name TEXT,\n    total_assigned BIGINT,\n    completed_count BIGINT,\n    overdue_count BIGINT,\n    efficiency_score NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id,\n        p.nome,\n        COUNT(ti.id) as total_assigned,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_count,\n        -- Overdue micro-tasks (if parent task is overdue and micro-task is not done)\n        COUNT(ti.id) FILTER (\n            WHERE ti.status NOT IN ('completed', 'concluida')\n            AND EXISTS (\n                SELECT 1 FROM tarefas t \n                WHERE t.id = ti.tarefa_id \n                AND t.deadline < now()\n            )\n        ) as overdue_count,\n        -- Simple efficiency score: (Completed / Total) * 100\n        CASE \n            WHEN COUNT(ti.id) > 0 THEN \n                (COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida'))::NUMERIC / COUNT(ti.id)::NUMERIC) * 100\n            ELSE 0 \n        END::NUMERIC(5,2) as efficiency_score\n    FROM profissionais p\n    JOIN tarefas_itens ti ON ti.profissional_id = p.id\n    WHERE (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY p.id, p.nome\n    ORDER BY completed_count DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Grant permissions again just in case\nGRANT EXECUTE ON FUNCTION get_client_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_role_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_staff_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;"}	20251224153000_fix_reports_rpc_v2	redestvgmulti@gmail.com	\N	\N
20260107103120	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1007: Ajustar task_comments para ETAPA 3\n-- Data: 2026-01-07\n-- Descrição: Adicionar campos necessários para funcionalidades de edição,\n--            soft delete e auditoria em comentários\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Adicionar colunas faltantes\nALTER TABLE task_comments\nADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW(),\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ,\nADD COLUMN IF NOT EXISTS editado BOOLEAN DEFAULT false;\n\n-- Constraint de limite de caracteres (5000)\nALTER TABLE task_comments\nDROP CONSTRAINT IF EXISTS content_length_limit;\n\nALTER TABLE task_comments\nADD CONSTRAINT content_length_limit CHECK (char_length(content) > 0 AND char_length(content) <= 5000);\n\n-- Constraint de conteúdo não vazio\nALTER TABLE task_comments\nDROP CONSTRAINT IF EXISTS content_not_empty;\n\nALTER TABLE task_comments\nADD CONSTRAINT content_not_empty CHECK (trim(content) != '');\n\n-- Trigger para updated_at\nCREATE OR REPLACE FUNCTION update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS update_task_comments_updated_at ON task_comments;\n\nCREATE TRIGGER update_task_comments_updated_at\n    BEFORE UPDATE ON task_comments\n    FOR EACH ROW\n    EXECUTE FUNCTION update_updated_at_column();\n\n-- Comentários\nCOMMENT ON COLUMN task_comments.updated_at IS 'Última atualização do comentário (edição)';\nCOMMENT ON COLUMN task_comments.deleted_at IS 'Soft delete timestamp. NULL = ativo, NOT NULL = deletado';\nCOMMENT ON COLUMN task_comments.editado IS 'Indica se comentário foi editado após criação';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1007: task_comments ajustada para ETAPA 3 (updated_at, deleted_at, editado)';\nEND $$;\n\nCOMMIT;"}	1007_ajustar_task_comments	redestvgmulti@gmail.com	\N	\N
20251224111115	{"-- FIX: Re-create Report RPCs (Fix for PGRST202 error & Missing Table & Missing Column)\n-- Description: \n-- 1. Updates get_client_stats to query 'clientes' table.\n-- 2. Updates get_role_stats to use 'profissionais.role' instead of missing 'funcao_snapshot'.\n\n-- 1. Get Client/Company Stats\nCREATE OR REPLACE FUNCTION get_client_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    client_id UUID,\n    client_name TEXT,\n    total_tasks BIGINT,\n    completed_tasks BIGINT,\n    overdue_tasks BIGINT,\n    avg_resolution_time_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        c.id as client_id,\n        c.nome as client_name,\n        COUNT(t.id) as total_tasks,\n        COUNT(t.id) FILTER (WHERE t.status IN ('completed', 'concluida')) as completed_tasks,\n        COUNT(t.id) FILTER (\n            WHERE t.status NOT IN ('completed', 'concluida') \n            AND t.deadline < now()\n        ) as overdue_tasks,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(t.completed_at, now()) - t.created_at))/3600\n            ) FILTER (WHERE t.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_resolution_time_hours\n    FROM clientes c\n    LEFT JOIN tarefas t ON t.cliente_id = c.id\n    WHERE (start_date IS NULL OR t.created_at >= start_date)\n      AND (end_date IS NULL OR t.created_at <= end_date)\n    GROUP BY c.id, c.nome\n    ORDER BY total_tasks DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Get Role/Department Stats (Replacing missing funcao_snapshot)\nCREATE OR REPLACE FUNCTION get_role_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    role_name TEXT,\n    total_items BIGINT,\n    completed_items BIGINT,\n    avg_completion_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        COALESCE(p.role, 'N/A') as role_name,\n        COUNT(ti.id) as total_items,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_items,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(ti.concluida_at, now()) - ti.created_at))/3600\n            ) FILTER (WHERE ti.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_completion_hours\n    FROM tarefas_itens ti\n    JOIN profissionais p ON p.id = ti.profissional_id\n    WHERE (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY p.role\n    ORDER BY total_items DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 3. Get Staff Stats (Colaborador)\nCREATE OR REPLACE FUNCTION get_staff_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    staff_id UUID,\n    staff_name TEXT,\n    total_assigned BIGINT,\n    completed_count BIGINT,\n    overdue_count BIGINT,\n    efficiency_score NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id,\n        p.nome,\n        COUNT(ti.id) as total_assigned,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_count,\n        -- Overdue micro-tasks (if parent task is overdue and micro-task is not done)\n        COUNT(ti.id) FILTER (\n            WHERE ti.status NOT IN ('completed', 'concluida')\n            AND EXISTS (\n                SELECT 1 FROM tarefas t \n                WHERE t.id = ti.tarefa_id \n                AND t.deadline < now()\n            )\n        ) as overdue_count,\n        -- Simple efficiency score: (Completed / Total) * 100\n        CASE \n            WHEN COUNT(ti.id) > 0 THEN \n                (COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida'))::NUMERIC / COUNT(ti.id)::NUMERIC) * 100\n            ELSE 0 \n        END::NUMERIC(5,2) as efficiency_score\n    FROM profissionais p\n    JOIN tarefas_itens ti ON ti.profissional_id = p.id\n    WHERE (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY p.id, p.nome\n    ORDER BY completed_count DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Grant permissions again just in case\nGRANT EXECUTE ON FUNCTION get_client_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_role_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_staff_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;"}	20251224153000_fix_reports_rpc_v3	redestvgmulti@gmail.com	\N	\N
20251224111257	{"-- FIX: Re-create Report RPCs (Fix for PGRST202 error & Missing Table & Missing Column)\n-- Description: \n-- 1. Updates get_client_stats to query 'clientes' table.\n-- 2. Updates get_role_stats to use 'departamentos.nome' (Department) as the \\"Role\\" proxy.\n\n-- 1. Get Client/Company Stats\nCREATE OR REPLACE FUNCTION get_client_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    client_id UUID,\n    client_name TEXT,\n    total_tasks BIGINT,\n    completed_tasks BIGINT,\n    overdue_tasks BIGINT,\n    avg_resolution_time_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        c.id as client_id,\n        c.nome as client_name,\n        COUNT(t.id) as total_tasks,\n        COUNT(t.id) FILTER (WHERE t.status IN ('completed', 'concluida')) as completed_tasks,\n        COUNT(t.id) FILTER (\n            WHERE t.status NOT IN ('completed', 'concluida') \n            AND t.deadline < now()\n        ) as overdue_tasks,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(t.completed_at, now()) - t.created_at))/3600\n            ) FILTER (WHERE t.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_resolution_time_hours\n    FROM clientes c\n    LEFT JOIN tarefas t ON t.cliente_id = c.id\n    WHERE (start_date IS NULL OR t.created_at >= start_date)\n      AND (end_date IS NULL OR t.created_at <= end_date)\n    GROUP BY c.id, c.nome\n    ORDER BY total_tasks DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Get Role/Department Stats (Replacing missing funcao_snapshot)\n-- We use Department Name as the grouping key.\nCREATE OR REPLACE FUNCTION get_role_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    role_name TEXT,\n    total_items BIGINT,\n    completed_items BIGINT,\n    avg_completion_hours NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        COALESCE(d.nome, 'Sem Departamento') as role_name,\n        COUNT(ti.id) as total_items,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_items,\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (COALESCE(ti.concluida_at, now()) - ti.created_at))/3600\n            ) FILTER (WHERE ti.status IN ('completed', 'concluida')), \n            0\n        )::NUMERIC(10,2) as avg_completion_hours\n    FROM tarefas_itens ti\n    JOIN profissionais p ON p.id = ti.profissional_id\n    LEFT JOIN departamentos d ON d.id = p.departamento_id\n    WHERE (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY d.nome\n    ORDER BY total_items DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 3. Get Staff Stats (Colaborador)\nCREATE OR REPLACE FUNCTION get_staff_stats(\n    start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,\n    end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL\n)\nRETURNS TABLE (\n    staff_id UUID,\n    staff_name TEXT,\n    total_assigned BIGINT,\n    completed_count BIGINT,\n    overdue_count BIGINT,\n    efficiency_score NUMERIC\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        p.id,\n        p.nome,\n        COUNT(ti.id) as total_assigned,\n        COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida')) as completed_count,\n        -- Overdue micro-tasks (if parent task is overdue and micro-task is not done)\n        COUNT(ti.id) FILTER (\n            WHERE ti.status NOT IN ('completed', 'concluida')\n            AND EXISTS (\n                SELECT 1 FROM tarefas t \n                WHERE t.id = ti.tarefa_id \n                AND t.deadline < now()\n            )\n        ) as overdue_count,\n        -- Simple efficiency score: (Completed / Total) * 100\n        CASE \n            WHEN COUNT(ti.id) > 0 THEN \n                (COUNT(ti.id) FILTER (WHERE ti.status IN ('completed', 'concluida'))::NUMERIC / COUNT(ti.id)::NUMERIC) * 100\n            ELSE 0 \n        END::NUMERIC(5,2) as efficiency_score\n    FROM profissionais p\n    JOIN tarefas_itens ti ON ti.profissional_id = p.id\n    WHERE (start_date IS NULL OR ti.created_at >= start_date)\n      AND (end_date IS NULL OR ti.created_at <= end_date)\n    GROUP BY p.id, p.nome\n    ORDER BY completed_count DESC;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Grant permissions again just in case\nGRANT EXECUTE ON FUNCTION get_client_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_role_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;\nGRANT EXECUTE ON FUNCTION get_staff_stats(TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) TO authenticated;"}	20251224153000_fix_reports_rpc_v4_dept	redestvgmulti@gmail.com	\N	\N
20251224114044	{"create policy \\"Allow insert for authenticated users\\"\non \\"public\\".\\"departamentos\\"\nas permissive\nfor insert\nto authenticated\nwith check (true);\n\ncreate policy \\"Allow update for authenticated users\\"\non \\"public\\".\\"departamentos\\"\nas permissive\nfor update\nto authenticated\nusing (true)\nwith check (true);\n\ncreate policy \\"Allow delete for authenticated users\\"\non \\"public\\".\\"departamentos\\"\nas permissive\nfor delete\nto authenticated\nusing (true);"}	fix_departamentos_rls	redestvgmulti@gmail.com	\N	\N
20251225174906	{"-- Drop legacy triggers from Migration 003 to prevent duplicates\nDROP TRIGGER IF EXISTS trigger_notify_task_assigned ON tarefas;\nDROP TRIGGER IF EXISTS trigger_notify_task_reassigned ON tarefas;\n\n-- Note: trigger_notify_task_completed uses the same name in 003/005/006 so likely overwrite each other, causing no duplication.\n"}	cleanup_duplicates	redestvgmulti@gmail.com	\N	\N
20251225181057	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- MIGRATION: CLEANUP TRIGGERS & FIX NOTIFICATIONS\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- 1. Drop ALL potential conflicting triggers on 'tarefas'\nDROP TRIGGER IF EXISTS trigger_notify_task_assigned ON tarefas;\nDROP TRIGGER IF EXISTS trigger_notify_task_reassigned ON tarefas;\nDROP TRIGGER IF EXISTS trigger_notify_task_completed ON tarefas;\nDROP TRIGGER IF EXISTS trigger_notify_task_assignment ON tarefas;\nDROP TRIGGER IF EXISTS trigger_notify_task_details_change ON tarefas; -- From 015\nDROP TRIGGER IF EXISTS trigger_task_notifications ON tarefas; -- Hypothetical name\n\n-- 2. Clean up 'notifications' table triggers\nDROP TRIGGER IF EXISTS trigger_push_notification_on_insert ON notifications;\n\n-- 3. Re-create the SINGLE authoritative Task Assignment Trigger (Logic from 018)\nCREATE OR REPLACE FUNCTION notify_task_assignment()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Handle INSERT: If new task has assignee\n  IF (TG_OP = 'INSERT') THEN\n    IF NEW.assigned_to IS NOT NULL THEN\n       -- Check if assignee exists and is active\n       IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n          INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n          VALUES (\n            NEW.assigned_to, \n            'task_assigned', \n            'Nova Tarefa', \n            'Uma nova tarefa foi atribuída a você: ' || NEW.titulo, \n            'task', \n            NEW.id\n          );\n       END IF;\n    END IF;\n\n  -- Handle UPDATE: If assignee changed\n  ELSIF (TG_OP = 'UPDATE') THEN\n    IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL THEN\n       IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n          INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n          VALUES (\n            NEW.assigned_to, \n            'task_assigned', \n            'Nova Atribuição', \n            'Tarefa atribuída a você: ' || NEW.titulo, \n            'task', \n            NEW.id\n          );\n       END IF;\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- 4. Create the Trigger\nCREATE TRIGGER trigger_notify_task_assignment\nAFTER INSERT OR UPDATE ON tarefas\nFOR EACH ROW\nEXECUTE FUNCTION notify_task_assignment();\n\n\n-- 5. Re-create the Push Notification Trigger on 'notifications'\nCREATE OR REPLACE FUNCTION trigger_send_push_notification()\nRETURNS TRIGGER AS $$\nDECLARE\n  url TEXT := 'https://gyooxmpyxncrezjiljrj.supabase.co/functions/v1/send-push-notification';\n  api_key TEXT := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imd5b294bXB5eG5jcmV6amlsanJqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjU4MDE2MzUsImV4cCI6MjA4MTM3NzYzNX0.mn0Y66MZ6DHxdyMg2Oh6bSIi2CC5h8RmN5N4hlyqhog';\n  payload JSONB;\n  request_id BIGINT;\nBEGIN\n  payload := jsonb_build_object('notificationId', NEW.id);\n  SELECT net.http_post(\n    url := url,\n    body := payload,\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'Authorization', 'Bearer ' || api_key\n    )\n  ) INTO request_id;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE TRIGGER trigger_push_notification_on_insert\nAFTER INSERT ON notifications\nFOR EACH ROW\nEXECUTE FUNCTION trigger_send_push_notification();"}	nuclear_cleanup	redestvgmulti@gmail.com	\N	\N
20251225182012	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FINAL FIX: Complete Trigger Reset\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- 1. Drop ALL triggers on tarefas table (comprehensive)\nDO $$ \nDECLARE\n    r RECORD;\nBEGIN\n    FOR r IN (SELECT tgname FROM pg_trigger WHERE tgrelid = 'tarefas'::regclass)\n    LOOP\n        EXECUTE 'DROP TRIGGER IF EXISTS ' || r.tgname || ' ON tarefas CASCADE';\n    END LOOP;\nEND $$;\n\n-- 2. Drop ALL triggers on notifications table\nDO $$ \nDECLARE\n    r RECORD;\nBEGIN\n    FOR r IN (SELECT tgname FROM pg_trigger WHERE tgrelid = 'notifications'::regclass)\n    LOOP\n        EXECUTE 'DROP TRIGGER IF EXISTS ' || r.tgname || ' ON notifications CASCADE';\n    END LOOP;\nEND $$;\n\n-- 3. Create SINGLE task notification trigger\nCREATE OR REPLACE FUNCTION notify_task_assignment()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- Only on INSERT with assigned_to\n  IF (TG_OP = 'INSERT' AND NEW.assigned_to IS NOT NULL) THEN\n    IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n      INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n      VALUES (\n        NEW.assigned_to, \n        'task_assigned', \n        'Nova Tarefa', \n        'Uma nova tarefa foi atribuída a você: ' || NEW.titulo, \n        'task', \n        NEW.id\n      );\n    END IF;\n  -- Only on UPDATE when assignee changes\n  ELSIF (TG_OP = 'UPDATE' AND NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NEW.assigned_to IS NOT NULL) THEN\n    IF EXISTS (SELECT 1 FROM profissionais WHERE id = NEW.assigned_to AND ativo = true) THEN\n      INSERT INTO notifications (profissional_id, type, title, message, entity_type, entity_id)\n      VALUES (\n        NEW.assigned_to, \n        'task_assigned', \n        'Nova Atribuição', \n        'Tarefa atribuída a você: ' || NEW.titulo, \n        'task', \n        NEW.id\n      );\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE TRIGGER trigger_notify_task_assignment\nAFTER INSERT OR UPDATE ON tarefas\nFOR EACH ROW\nEXECUTE FUNCTION notify_task_assignment();"}	final_trigger_reset	redestvgmulti@gmail.com	\N	\N
20251226000246	{"ALTER TABLE tarefas_micro \nDROP CONSTRAINT IF EXISTS micro_status_check;\n\nALTER TABLE tarefas_micro \nADD CONSTRAINT micro_status_check \nCHECK (status IN ('pendente', 'em_progresso', 'concluida', 'bloqueada'));\n\nUPDATE tarefas_micro \nSET status = 'pendente' \nWHERE status NOT IN ('pendente', 'em_progresso', 'concluida', 'bloqueada');"}	fix_micro_status_constraint_20251226	redestvgmulti@gmail.com	\N	\N
20251226005116	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Notification Triggers for Admin/Managers\n-- Migration 028: Add triggers for Macro Completion, Micro Completion, and Devolution\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- 1. Helper Function to Notify Admins and Managers\nCREATE OR REPLACE FUNCTION notify_admins_and_managers(\n    p_title TEXT,\n    p_message TEXT,\n    p_link TEXT,\n    p_type TEXT,\n    p_entity_id UUID\n)\nRETURNS VOID AS $$\nBEGIN\n    -- Insert notification for all active admins and managers\n    INSERT INTO notifications (profissional_id, type, title, message, link, entity_id, entity_type, read)\n    SELECT \n        id,\n        p_type,\n        p_title,\n        p_message,\n        p_link,\n        p_entity_id,\n        'task',\n        false\n    FROM profissionais\n    WHERE role IN ('admin', 'manager', 'master') -- inclusive list\n    AND ativo = true;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- 2. Trigger: Macro Task Completion\nCREATE OR REPLACE FUNCTION trigger_notify_macro_completion()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN\n        PERFORM notify_admins_and_managers(\n            'Tarefa Concluída',\n            'A tarefa macro \\"' || NEW.titulo || '\\" foi concluída.',\n            '/admin/tasks', -- Link to admin tasks\n            'macro_task_completed',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_macro_completion ON tarefas;\nCREATE TRIGGER trg_notify_macro_completion\n    AFTER UPDATE ON tarefas\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_macro_completion();\n\n-- 3. Trigger: Micro Task Completion (Notify Admin)\nCREATE OR REPLACE FUNCTION trigger_notify_micro_completion_admin()\nRETURNS TRIGGER AS $$\nDECLARE\n    task_title TEXT;\n    professional_name TEXT;\nBEGIN\n    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN\n        -- Get Task Title\n        SELECT titulo INTO task_title FROM tarefas WHERE id = NEW.tarefa_id;\n        -- Get Professional Name\n        SELECT nome INTO professional_name FROM profissionais WHERE id = NEW.profissional_id;\n\n        PERFORM notify_admins_and_managers(\n            'Etapa Concluída',\n            'A etapa \\"' || NEW.funcao || '\\" foi concluída por ' || professional_name || ' na tarefa \\"' || task_title || '\\".',\n            '/admin/tasks',\n            'micro_task_completed',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_micro_completion_admin ON tarefas_micro;\nCREATE TRIGGER trg_notify_micro_completion_admin\n    AFTER UPDATE ON tarefas_micro\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_micro_completion_admin();\n\n-- 4. Trigger: Micro Task Devolution (Notify Admin)\nCREATE OR REPLACE FUNCTION trigger_notify_micro_devolution_admin()\nRETURNS TRIGGER AS $$\nDECLARE\n    task_title TEXT;\n    reason TEXT;\nBEGIN\n    IF NEW.status = 'devolvida' AND (OLD IS NULL OR OLD.status != 'devolvida') THEN\n        -- Get Task Title\n        SELECT titulo INTO task_title FROM tarefas WHERE id = NEW.tarefa_id;\n        \n        -- Get Reason from logs (most recent returned log for this micro_task)\n        SELECT motivo INTO reason \n        FROM tarefas_micro_logs \n        WHERE tarefa_micro_id = NEW.id \n        AND acao = 'returned' \n        ORDER BY created_at DESC \n        LIMIT 1;\n\n        PERFORM notify_admins_and_managers(\n            'Etapa Devolvida',\n            'A etapa \\"' || NEW.funcao || '\\" foi devolvida na tarefa \\"' || task_title || '\\". Motivo: ' || COALESCE(reason, 'Não informado'),\n            '/admin/tasks',\n            'micro_task_returned',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_micro_devolution_admin ON tarefas_micro;\nCREATE TRIGGER trg_notify_micro_devolution_admin\n    AFTER UPDATE ON tarefas_micro\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_micro_devolution_admin();"}	028_notification_triggers	redestvgmulti@gmail.com	\N	\N
20251226005336	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Notification Triggers for Admin/Managers\n-- Migration 028: Add triggers for Macro Completion, Micro Completion, and Devolution\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Ensure link column exists\nALTER TABLE notifications ADD COLUMN IF NOT EXISTS link TEXT;\n\n-- 1. Helper Function to Notify Admins and Managers\nCREATE OR REPLACE FUNCTION notify_admins_and_managers(\n    p_title TEXT,\n    p_message TEXT,\n    p_link TEXT,\n    p_type TEXT,\n    p_entity_id UUID\n)\nRETURNS VOID AS $$\nBEGIN\n    -- Insert notification for all active admins and managers\n    INSERT INTO notifications (profissional_id, type, title, message, link, entity_id, entity_type, read)\n    SELECT \n        id,\n        p_type,\n        p_title,\n        p_message,\n        p_link,\n        p_entity_id,\n        'task',\n        false\n    FROM profissionais\n    WHERE role IN ('admin', 'manager', 'master') -- inclusive list\n    AND ativo = true;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- 2. Trigger: Macro Task Completion\nCREATE OR REPLACE FUNCTION trigger_notify_macro_completion()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN\n        PERFORM notify_admins_and_managers(\n            'Tarefa Concluída',\n            'A tarefa macro \\"' || NEW.titulo || '\\" foi concluída.',\n            '/admin/tasks', -- Link to admin tasks\n            'macro_task_completed',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_macro_completion ON tarefas;\nCREATE TRIGGER trg_notify_macro_completion\n    AFTER UPDATE ON tarefas\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_macro_completion();\n\n-- 3. Trigger: Micro Task Completion (Notify Admin)\nCREATE OR REPLACE FUNCTION trigger_notify_micro_completion_admin()\nRETURNS TRIGGER AS $$\nDECLARE\n    task_title TEXT;\n    professional_name TEXT;\nBEGIN\n    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN\n        -- Get Task Title\n        SELECT titulo INTO task_title FROM tarefas WHERE id = NEW.tarefa_id;\n        -- Get Professional Name\n        SELECT nome INTO professional_name FROM profissionais WHERE id = NEW.profissional_id;\n\n        PERFORM notify_admins_and_managers(\n            'Etapa Concluída',\n            'A etapa \\"' || NEW.funcao || '\\" foi concluída por ' || professional_name || ' na tarefa \\"' || task_title || '\\".',\n            '/admin/tasks',\n            'micro_task_completed',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_micro_completion_admin ON tarefas_micro;\nCREATE TRIGGER trg_notify_micro_completion_admin\n    AFTER UPDATE ON tarefas_micro\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_micro_completion_admin();\n\n-- 4. Trigger: Micro Task Devolution (Notify Admin)\nCREATE OR REPLACE FUNCTION trigger_notify_micro_devolution_admin()\nRETURNS TRIGGER AS $$\nDECLARE\n    task_title TEXT;\n    reason TEXT;\nBEGIN\n    IF NEW.status = 'devolvida' AND (OLD IS NULL OR OLD.status != 'devolvida') THEN\n        -- Get Task Title\n        SELECT titulo INTO task_title FROM tarefas WHERE id = NEW.tarefa_id;\n        \n        -- Get Reason from logs (most recent returned log for this micro_task)\n        SELECT motivo INTO reason \n        FROM tarefas_micro_logs \n        WHERE tarefa_micro_id = NEW.id \n        AND acao = 'returned' \n        ORDER BY created_at DESC \n        LIMIT 1;\n\n        PERFORM notify_admins_and_managers(\n            'Etapa Devolvida',\n            'A etapa \\"' || NEW.funcao || '\\" foi devolvida na tarefa \\"' || task_title || '\\". Motivo: ' || COALESCE(reason, 'Não informado'),\n            '/admin/tasks',\n            'micro_task_returned',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_micro_devolution_admin ON tarefas_micro;\nCREATE TRIGGER trg_notify_micro_devolution_admin\n    AFTER UPDATE ON tarefas_micro\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_micro_devolution_admin();"}	028_notification_triggers_fix	redestvgmulti@gmail.com	\N	\N
20251226005356	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Notification Triggers for Admin/Managers\n-- Migration 028: Add triggers for Macro Completion, Micro Completion, and Devolution\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Ensure link column exists\nALTER TABLE notifications ADD COLUMN IF NOT EXISTS link TEXT;\n-- Ensure read column exists (it's called 'read' based on earlier edge function usage)\nALTER TABLE notifications ADD COLUMN IF NOT EXISTS read BOOLEAN DEFAULT FALSE;\n\n-- 1. Helper Function to Notify Admins and Managers\nCREATE OR REPLACE FUNCTION notify_admins_and_managers(\n    p_title TEXT,\n    p_message TEXT,\n    p_link TEXT,\n    p_type TEXT,\n    p_entity_id UUID\n)\nRETURNS VOID AS $$\nBEGIN\n    -- Insert notification for all active admins and managers\n    INSERT INTO notifications (profissional_id, type, title, message, link, entity_id, entity_type, read)\n    SELECT \n        id,\n        p_type,\n        p_title,\n        p_message,\n        p_link,\n        p_entity_id,\n        'task',\n        false\n    FROM profissionais\n    WHERE role IN ('admin', 'manager', 'master') -- inclusive list\n    AND ativo = true;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- 2. Trigger: Macro Task Completion\nCREATE OR REPLACE FUNCTION trigger_notify_macro_completion()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN\n        PERFORM notify_admins_and_managers(\n            'Tarefa Concluída',\n            'A tarefa macro \\"' || NEW.titulo || '\\" foi concluída.',\n            '/admin/tasks', -- Link to admin tasks\n            'macro_task_completed',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_macro_completion ON tarefas;\nCREATE TRIGGER trg_notify_macro_completion\n    AFTER UPDATE ON tarefas\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_macro_completion();\n\n-- 3. Trigger: Micro Task Completion (Notify Admin)\nCREATE OR REPLACE FUNCTION trigger_notify_micro_completion_admin()\nRETURNS TRIGGER AS $$\nDECLARE\n    task_title TEXT;\n    professional_name TEXT;\nBEGIN\n    IF NEW.status = 'concluida' AND (OLD IS NULL OR OLD.status != 'concluida') THEN\n        -- Get Task Title\n        SELECT titulo INTO task_title FROM tarefas WHERE id = NEW.tarefa_id;\n        -- Get Professional Name\n        SELECT nome INTO professional_name FROM profissionais WHERE id = NEW.profissional_id;\n\n        PERFORM notify_admins_and_managers(\n            'Etapa Concluída',\n            'A etapa \\"' || NEW.funcao || '\\" foi concluída por ' || professional_name || ' na tarefa \\"' || task_title || '\\".',\n            '/admin/tasks',\n            'micro_task_completed',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_micro_completion_admin ON tarefas_micro;\nCREATE TRIGGER trg_notify_micro_completion_admin\n    AFTER UPDATE ON tarefas_micro\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_micro_completion_admin();\n\n-- 4. Trigger: Micro Task Devolution (Notify Admin)\nCREATE OR REPLACE FUNCTION trigger_notify_micro_devolution_admin()\nRETURNS TRIGGER AS $$\nDECLARE\n    task_title TEXT;\n    reason TEXT;\nBEGIN\n    IF NEW.status = 'devolvida' AND (OLD IS NULL OR OLD.status != 'devolvida') THEN\n        -- Get Task Title\n        SELECT titulo INTO task_title FROM tarefas WHERE id = NEW.tarefa_id;\n        \n        -- Get Reason from logs (most recent returned log for this micro_task)\n        SELECT motivo INTO reason \n        FROM tarefas_micro_logs \n        WHERE tarefa_micro_id = NEW.id \n        AND acao = 'returned' \n        ORDER BY created_at DESC \n        LIMIT 1;\n\n        PERFORM notify_admins_and_managers(\n            'Etapa Devolvida',\n            'A etapa \\"' || NEW.funcao || '\\" foi devolvida na tarefa \\"' || task_title || '\\". Motivo: ' || COALESCE(reason, 'Não informado'),\n            '/admin/tasks',\n            'micro_task_returned',\n            NEW.id\n        );\n    END IF;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_notify_micro_devolution_admin ON tarefas_micro;\nCREATE TRIGGER trg_notify_micro_devolution_admin\n    AFTER UPDATE ON tarefas_micro\n    FOR EACH ROW\n    EXECUTE FUNCTION trigger_notify_micro_devolution_admin();"}	028_notification_triggers_robust	redestvgmulti@gmail.com	\N	\N
20251226005453	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Fix Micro Task Status Constraint\n-- Migration 029: Ensure 'devolvida' is in the allowed status list\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nDO $$\nBEGIN\n    -- Drop the constraint if it exists\n    IF EXISTS (\n        SELECT 1 FROM pg_constraint WHERE conname = 'tarefas_micro_status_check'\n    ) THEN\n        ALTER TABLE tarefas_micro DROP CONSTRAINT tarefas_micro_status_check;\n    END IF;\n\n    -- Add the correct constraint\n    ALTER TABLE tarefas_micro\n    ADD CONSTRAINT tarefas_micro_status_check \n    CHECK (status IN ('pendente', 'bloqueada', 'em_execucao', 'concluida', 'devolvida'));\n\nEND $$;"}	029_fix_micro_task_status_constraint	redestvgmulti@gmail.com	\N	\N
20251226151833	{"-- Migration: Super Admin Setup\n-- Description: Adds super_admin role, creates empresas table with governance fields, and sets up RLS.\n\n-- 1. Update 'profissionais' role constraint to include 'super_admin'\nDO $$ BEGIN\n    ALTER TABLE profissionais DROP CONSTRAINT IF EXISTS profissionais_role_check;\n    ALTER TABLE profissionais ADD CONSTRAINT profissionais_role_check \n        CHECK (role IN ('admin', 'profissional', 'super_admin'));\nEXCEPTION\n    WHEN undefined_object THEN\n        -- Handle case where constraint name might be different\n        NULL;\nEND $$;\n\n-- 2. Create or Update 'empresas' table\nCREATE TABLE IF NOT EXISTS empresas (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    nome TEXT NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\n-- Add new governance columns if they don't exist\nDO $$ BEGIN\n    ALTER TABLE empresas ADD COLUMN IF NOT EXISTS status_conta TEXT DEFAULT 'active' CHECK (status_conta IN ('trial', 'active', 'suspended'));\n    ALTER TABLE empresas ADD COLUMN IF NOT EXISTS icp_status TEXT DEFAULT 'doubtful' CHECK (icp_status IN ('correct', 'doubtful', 'wrong'));\n    ALTER TABLE empresas ADD COLUMN IF NOT EXISTS internal_notes TEXT;\n    ALTER TABLE empresas ADD COLUMN IF NOT EXISTS tipo_negocio TEXT CHECK (tipo_negocio IN ('agency', 'studio', 'producer', 'other'));\n    ALTER TABLE empresas ADD COLUMN IF NOT EXISTS last_activity_at TIMESTAMP WITH TIME ZONE DEFAULT NOW();\nEXCEPTION\n    WHEN duplicate_column THEN NULL;\nEND $$;\n\n-- 3. Enable RLS on empresas\nALTER TABLE empresas ENABLE ROW LEVEL SECURITY;\n\n-- 4. RLS Policies\n\n-- Super Admin: Full Access\nCREATE POLICY \\"Super Admin Full Access\\" ON empresas\n    FOR ALL\n    TO authenticated\n    USING (\n        EXISTS (\n            SELECT 1 FROM profissionais\n            WHERE profissionais.id = auth.uid()\n            AND profissionais.role = 'super_admin'\n        )\n    );\n\n-- 5. RPC: Get Companies Dashboard Stats\nCREATE OR REPLACE FUNCTION get_companies_stats()\nRETURNS TABLE (\n    empresa_id UUID,\n    nome TEXT,\n    status_conta TEXT,\n    icp_status TEXT,\n    tipo_negocio TEXT,\n    users_count BIGINT,\n    active_tasks_count BIGINT,\n    last_activity_at TIMESTAMP WITH TIME ZONE,\n    health_status TEXT\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        e.id,\n        e.nome,\n        e.status_conta,\n        e.icp_status,\n        e.tipo_negocio,\n        (SELECT COUNT(*) FROM empresa_profissionais ep WHERE ep.empresa_id = e.id) as users_count,\n        (SELECT COUNT(*) FROM tarefas t WHERE t.empresa_id = e.id AND t.status IN ('pending', 'in_progress')) as active_tasks_count,\n        e.last_activity_at,\n        CASE\n            WHEN e.last_activity_at > NOW() - INTERVAL '7 days' THEN 'healthy'\n            WHEN e.last_activity_at > NOW() - INTERVAL '14 days' THEN 'low_activity'\n            ELSE 'inactive'\n        END as health_status\n    FROM empresas e;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n"}	super_admin_setup	redestvgmulti@gmail.com	\N	\N
20251228203049	{"-- Definitive migration for Company Scope Correction (V1)\n-- STRICT enforcement of Tenant vs Operational separation\n\n-- 1. Ensure columns exist (idempotent)\nALTER TABLE empresas \nADD COLUMN IF NOT EXISTS tenant_id UUID REFERENCES empresas(id),\nADD COLUMN IF NOT EXISTS empresa_tipo text NOT NULL DEFAULT 'operacional';\n\n-- 2. Add Constraint for empresa_tipo values\nDO $$ BEGIN\n    ALTER TABLE empresas ADD CONSTRAINT empresas_empresa_tipo_check \n    CHECK (empresa_tipo IN ('tenant', 'operacional'));\nEXCEPTION\n    WHEN duplicate_object THEN NULL;\nEND $$;\n\n-- 3. [STRICT] Add Constraint: Tenants MUST have NULL tenant_id\n-- Operational companies MUST have tenant_id (enforced by application logic mostly, but let's check)\n-- \\"Tenant nunca pode ter tenant_id preenchido\\"\nDO $$ BEGIN\n    ALTER TABLE empresas ADD CONSTRAINT check_tenant_rules \n    CHECK (\n        (empresa_tipo = 'tenant' AND tenant_id IS NULL) OR \n        (empresa_tipo = 'operacional') \n    );\nEXCEPTION\n    WHEN duplicate_object THEN NULL;\nEND $$;\n\n-- 4. Clean up existing data to satisfy constraints if needed (Self-Correction)\n-- If a tenant has tenant_id, clear it.\nUPDATE empresas SET tenant_id = NULL WHERE empresa_tipo = 'tenant';\n\n-- 5. RLS Policies (STRICT)\n\n-- Disable RLS temporarily to ensure clean slate if needed, or just replace policies\nALTER TABLE empresas ENABLE ROW LEVEL SECURITY;\n\n-- 5.1 Super Admin: Only 'tenant' companies\nDROP POLICY IF EXISTS \\"super_admin_empresas_select\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_select\\" ON empresas\nFOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n);\n\nDROP POLICY IF EXISTS \\"super_admin_empresas_insert\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_insert\\" ON empresas\nFOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n  AND tenant_id IS NULL\n);\n\nDROP POLICY IF EXISTS \\"super_admin_empresas_update\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_update\\" ON empresas\nFOR UPDATE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n  AND tenant_id IS NULL\n);\n\nDROP POLICY IF EXISTS \\"super_admin_empresas_delete\\" ON empresas;\nCREATE POLICY \\"super_admin_empresas_delete\\" ON empresas\nFOR DELETE TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM profissionais \n    WHERE profissionais.id = auth.uid() \n    AND profissionais.role = 'super_admin'\n  )\n  AND empresa_tipo = 'tenant'\n);\n\n-- 5.2 Admin: Only 'operacional' companies LINKED to their Tenant\nDROP POLICY IF EXISTS \\"admin_empresas_select\\" ON empresas;\nCREATE POLICY \\"admin_empresas_select\\" ON empresas\nFOR SELECT TO authenticated\nUSING (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND (p.role = 'admin')\n  )\n);\n\nDROP POLICY IF EXISTS \\"admin_empresas_insert\\" ON empresas;\nCREATE POLICY \\"admin_empresas_insert\\" ON empresas\nFOR INSERT TO authenticated\nWITH CHECK (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND (p.role = 'admin')\n  )\n);\n\nDROP POLICY IF EXISTS \\"admin_empresas_update\\" ON empresas;\nCREATE POLICY \\"admin_empresas_update\\" ON empresas\nFOR UPDATE TO authenticated\nUSING (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND (p.role = 'admin')\n  )\n)\nWITH CHECK (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND (p.role = 'admin')\n  )\n);\n\nDROP POLICY IF EXISTS \\"admin_empresas_delete\\" ON empresas;\nCREATE POLICY \\"admin_empresas_delete\\" ON empresas\nFOR DELETE TO authenticated\nUSING (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND (p.role = 'admin')\n  )\n);\n"}	definitive_company_scope	redestvgmulti@gmail.com	\N	\N
20251228203526	{"-- Migration: Fix Orphan Companies (Data Repair)\n-- Description: Reclassifies incorrectly marked tenants and links operational companies to their parents.\n\nDO $$\nDECLARE\n    r RECORD;\n    parent_tenant_id UUID;\n    updated_count INT := 0;\nBEGIN\n    -- 1. CORRECTION: Reclassify \\"Fake Tenants\\" to \\"Operacional\\"\n    -- \\"Fake Tenant\\" = empresa_tipo 'tenant' but NO LINKED SUPER_ADMIN\n    -- Only do this if we are sure. A safer bet is:\n    -- If created by non-super-admin... referencing `owner_id` would be nice but we lack it.\n    -- Logic: If a company has NO super_admin linked in `empresa_profissionais`, it CANNOT be a Platform Tenant managed by Super Admin.\n    \n    UPDATE empresas e\n    SET empresa_tipo = 'operacional', tenant_id = NULL\n    WHERE e.empresa_tipo = 'tenant'\n    AND NOT EXISTS (\n        SELECT 1 \n        FROM empresa_profissionais ep\n        JOIN profissionais p ON ep.profissional_id = p.id\n        WHERE ep.empresa_id = e.id\n        AND p.role = 'super_admin'\n    );\n\n    -- 2. LINKING: Connect Orphan Operational Companies to Parents\n    -- For each operational company without a tenant_id\n    FOR r IN \n        SELECT id, nome \n        FROM empresas \n        WHERE empresa_tipo = 'operacional' \n        AND tenant_id IS NULL \n    LOOP\n        -- Find a parent tenant via linked admins\n        SELECT t.id INTO parent_tenant_id\n        FROM empresas t\n        JOIN empresa_profissionais ep_tenant ON t.id = ep_tenant.empresa_id\n        JOIN profissionais p ON ep_tenant.profissional_id = p.id\n        -- Link to the orphan\n        JOIN empresa_profissionais ep_orphan ON p.id = ep_orphan.profissional_id\n        WHERE ep_orphan.empresa_id = r.id\n        -- Ensure T is a Tenant\n        AND t.empresa_tipo = 'tenant'\n        -- Ensure P is an Admin (who would manage the orphan)\n        -- AND (p.role = 'admin' OR ep_tenant.role = 'admin') -- Optional strictness\n        LIMIT 1;\n\n        -- Update if found\n        IF parent_tenant_id IS NOT NULL THEN\n            UPDATE empresas \n            SET tenant_id = parent_tenant_id \n            WHERE id = r.id;\n            \n            updated_count := updated_count + 1;\n        END IF;\n    END LOOP;\n\n    RAISE NOTICE 'Restored % companies.', updated_count;\nEND $$;\n"}	fix_orphan_companies	redestvgmulti@gmail.com	\N	\N
20251228203728	{"-- Migration: Fix Wrongly Demoted Tenants\n-- Description: Re-promotes \\"Operacional\\" companies to \\"Tenant\\" if they have Admins and no Parent.\n-- This fixes the issue where valid SaaS Tenants were demoted because they lacked a Super Admin link.\n\nDO $$\nDECLARE\n    promoted_count INT := 0;\nBEGIN\n    -- Update logic:\n    -- Find Operational companies that exist as \\"Roots\\" (no tenant_id)\n    -- AND have an Admin user linked. These are effectively Tenants.\n    \n    WITH rows_to_update AS (\n        SELECT e.id\n        FROM empresas e\n        WHERE e.empresa_tipo = 'operacional'\n        AND e.tenant_id IS NULL\n        AND EXISTS (\n            SELECT 1 \n            FROM empresa_profissionais ep\n            JOIN profissionais p ON ep.profissional_id = p.id\n            WHERE ep.empresa_id = e.id\n            AND (p.role = 'admin' OR ep.funcao = 'admin') \n            -- Check for 'admin' role in either table to be robust\n        )\n    )\n    UPDATE empresas\n    SET empresa_tipo = 'tenant'\n    WHERE id IN (SELECT id FROM rows_to_update);\n    \n    GET DIAGNOSTICS promoted_count = ROW_COUNT;\n    \n    RAISE NOTICE 'Repromoted % companies to Tenant status.', promoted_count;\n\n    -- Optional: After promoting Tenants, we might want to re-run the \\"Link Orphans\\" logic?\n    -- Because now we have valid Tenants, orphans might find their parents.\n    -- Let's include a small linking pass just in case.\n\n    UPDATE empresas e\n    SET tenant_id = (\n        SELECT t.id\n        FROM empresas t\n        JOIN empresa_profissionais ep_tenant ON t.id = ep_tenant.empresa_id\n        JOIN profissionais p ON ep_tenant.profissional_id = p.id\n        JOIN empresa_profissionais ep_orphan ON p.id = ep_orphan.profissional_id\n        WHERE ep_orphan.empresa_id = e.id\n        AND t.empresa_tipo = 'tenant'\n        AND t.id != e.id -- Don't link key to itself\n        LIMIT 1\n    )\n    WHERE e.empresa_tipo = 'operacional'\n    AND e.tenant_id IS NULL;\n\nEND $$;\n"}	fix_demoted_tenants	redestvgmulti@gmail.com	\N	\N
20251228203920	{"-- Migration: Robust Fix for Demoted Tenants (Broad Scope)\n-- Description: Promotes ANY Operational company that has NULL tenant_id and has linked professionals.\n-- Assumption: If it has no tenant_id, it is a Root company. If it has professionals, it's a Tenant.\n-- We relax the 'admin' role check because data might be messy (e.g. 'Admin', 'ADMIN', or just 'responsavel').\n\nDO $$\nDECLARE\n    promoted_count INT := 0;\nBEGIN\n    -- 1. Promote all Root Operational Companies to Tenant\n    UPDATE empresas\n    SET empresa_tipo = 'tenant'\n    WHERE empresa_tipo = 'operacional'\n    AND tenant_id IS NULL\n    AND EXISTS (\n        SELECT 1 \n        FROM empresa_profissionais ep \n        WHERE ep.empresa_id = empresas.id\n    );\n    \n    GET DIAGNOSTICS promoted_count = ROW_COUNT;\n    RAISE NOTICE 'Force-promoted % root operational companies to Tenant.', promoted_count;\n\n    -- 2. Clean up: If any operational company has tenant_id but that tenant_id DOES NOT exist or is invalid?\n    -- (Skipping for now, focus on the visibility issue)\n\n    -- 3. Re-link orphans (Pass 2)\n    -- Just in case some orphans didn't match before because the parent wasn't a tenant yet.\n    UPDATE empresas e\n    SET tenant_id = (\n        SELECT t.id\n        FROM empresas t\n        JOIN empresa_profissionais ep_tenant ON t.id = ep_tenant.empresa_id\n        JOIN profissionais p ON ep_tenant.profissional_id = p.id\n        JOIN empresa_profissionais ep_orphan ON p.id = ep_orphan.profissional_id\n        WHERE ep_orphan.empresa_id = e.id\n        AND t.empresa_tipo = 'tenant'\n        AND t.id != e.id\n        LIMIT 1\n    )\n    WHERE e.empresa_tipo = 'operacional'\n    AND e.tenant_id IS NULL;\n\nEND $$;\n"}	robust_fix_tenants	redestvgmulti@gmail.com	\N	\N
20251228203954	{"-- Migration: Add Missing Columns to Empresas\n-- Description: Adds columns required by the frontend that were missing in the base table.\n\nALTER TABLE empresas \nADD COLUMN IF NOT EXISTS drive_link text,\nADD COLUMN IF NOT EXISTS cnpj text,\nADD COLUMN IF NOT EXISTS ativo boolean DEFAULT true;\n"}	add_missing_columns	redestvgmulti@gmail.com	\N	\N
20251228204206	{"-- Migration: Fix Admin RLS to allow Tenant Visibility\n-- Description: Updates RLS policy so Admins can see their own Tenant company data.\n\nDROP POLICY IF EXISTS \\"admin_empresas_select\\" ON empresas;\n\nCREATE POLICY \\"admin_empresas_select\\" ON empresas\nFOR SELECT TO authenticated\nUSING (\n  -- 1. View Operational companies managed by my tenant\n  (\n    empresa_tipo = 'operacional' \n    AND tenant_id IN (\n      SELECT ep.empresa_id \n      FROM empresa_profissionais ep\n      WHERE ep.profissional_id = auth.uid()\n    )\n  )\n  OR\n  -- 2. View MY OWN linked companies (allows seeing the Tenant I belong to)\n  (\n    id IN (\n      SELECT ep.empresa_id \n      FROM empresa_profissionais ep\n      WHERE ep.profissional_id = auth.uid()\n    )\n  )\n);\n"}	fix_admin_rls	redestvgmulti@gmail.com	\N	\N
20251228204254	{"-- Migration: Fix Admin RLS for Insert/Update/Delete\n-- Description: Updates Write policies so Admins can manage companies linked to their Tenant.\n\n-- INSERT\nDROP POLICY IF EXISTS \\"admin_empresas_insert\\" ON empresas;\nCREATE POLICY \\"admin_empresas_insert\\" ON empresas\nFOR INSERT TO authenticated\nWITH CHECK (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    WHERE ep.profissional_id = auth.uid()\n    -- We trust that if they are linked to the Tenant, they can create ops companies for it.\n    -- This matches the context logic used in the frontend.\n  )\n);\n\n-- UPDATE\nDROP POLICY IF EXISTS \\"admin_empresas_update\\" ON empresas;\nCREATE POLICY \\"admin_empresas_update\\" ON empresas\nFOR UPDATE TO authenticated\nUSING (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    WHERE ep.profissional_id = auth.uid()\n  )\n)\nWITH CHECK (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    WHERE ep.profissional_id = auth.uid()\n  )\n);\n\n-- DELETE\nDROP POLICY IF EXISTS \\"admin_empresas_delete\\" ON empresas;\nCREATE POLICY \\"admin_empresas_delete\\" ON empresas\nFOR DELETE TO authenticated\nUSING (\n  empresa_tipo = 'operacional'\n  AND tenant_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep\n    WHERE ep.profissional_id = auth.uid()\n  )\n);\n"}	fix_admin_insert_rls	redestvgmulti@gmail.com	\N	\N
20251228215245	{"CREATE EXTENSION IF NOT EXISTS pgcrypto;\n\n-- Update auth.users password\nUPDATE auth.users\nSET encrypted_password = crypt('G1eovane23*', gen_salt('bf')),\n    email_confirmed_at = COALESCE(email_confirmed_at, now()),\n    raw_app_meta_data = jsonb_build_object('provider', 'email', 'providers', ARRAY['email'])\nWHERE email = 'geovanepanini@agencyflow.com';\n\n-- Update public.profissionais role\nUPDATE public.profissionais\nSET role = 'super_admin',\n    ativo = true\nWHERE email = 'geovanepanini@agencyflow.com';"}	fix_super_admin_credentials_v2	redestvgmulti@gmail.com	\N	\N
20251228215509	{"CREATE EXTENSION IF NOT EXISTS pgcrypto;\n\n-- 1. Update auth.users password for the specific ID found\n-- EXCLUDING confirmed_at this time to avoid the generated column error\nUPDATE auth.users\nSET encrypted_password = crypt('G1eovane23*', gen_salt('bf')),\n    email_confirmed_at = COALESCE(email_confirmed_at, now()),\n    raw_app_meta_data = jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),\n    updated_at = now()\nWHERE id = '1f4b90ba-9527-4d80-953c-3584aae50868';\n\n-- 2. Update public.profissionais role/status for the same ID\nUPDATE public.profissionais\nSET role = 'super_admin',\n    ativo = true\nWHERE id = '1f4b90ba-9527-4d80-953c-3584aae50868';"}	targeted_password_fix_v4	redestvgmulti@gmail.com	\N	\N
20260105093050	{"-- Migration: Fix RLS Infinite Recursion in Profissionais\n-- Date: 2026-01-05\n-- Description: Creates a Security Definer function to safely check user status without triggering RLS loops.\n\n-- 1. Create Helper Function (Bypasses RLS)\nCREATE OR REPLACE FUNCTION public.is_active_professional()\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nSTABLE\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.profissionais\n    WHERE id = auth.uid()\n    AND ativo = true\n  );\n$$;\n\n-- 2. Drop Problematic Policies\nDROP POLICY IF EXISTS \\"select_profissionais_all_authenticated\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"select_profissionais_secure\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"update_profissionais_by_role\\" ON \\"public\\".\\"profissionais\\";\nDROP POLICY IF EXISTS \\"delete_profissionais_admin_only\\" ON \\"public\\".\\"profissionais\\";\n\n-- 3. Re-create Policies using the Safe Function\n\n-- SELECT: Allow if reading self OR if active (using safe function)\nCREATE POLICY \\"select_profissionais_no_recursion\\"\nON \\"public\\".\\"profissionais\\"\nFOR SELECT\nTO authenticated\nUSING (\n  (id = auth.uid()) -- Always allow reading own raw profile to bootstrap\n  OR\n  is_active_professional() -- Safely check status for broad access\n);\n\n-- UPDATE: Must be active to update. Admin updates all, users update self.\nCREATE POLICY \\"update_profissionais_secure_definitive\\"\nON \\"public\\".\\"profissionais\\"\nFOR UPDATE\nTO authenticated\nUSING (\n  is_active_professional()\n  AND (\n    (role = 'admin')\n    OR\n    (id = auth.uid())\n  )\n)\nWITH CHECK (\n  is_active_professional()\n  AND (\n    (role = 'admin')\n    OR\n    (id = auth.uid())\n  )\n);\n\n-- DELETE: Admin only (must be active)\nCREATE POLICY \\"delete_profissionais_admin_secure\\"\nON \\"public\\".\\"profissionais\\"\nFOR DELETE\nTO authenticated\nUSING (\n  is_active_professional()\n  AND role = 'admin'\n);\n"}	fix_rls_recursion_definitive	redestvgmulti@gmail.com	\N	\N
20260106134632	{"-- Migration: Fix null roles for existing users\n-- This migration sets a default 'staff' role for any professional without a role assigned\n\n-- Update all users with NULL role to 'staff' (safest default)\n-- Admins should be manually promoted after this migration\nUPDATE profissionais\nSET role = 'staff'\nWHERE role IS NULL;"}	fix_null_roles	redestvgmulti@gmail.com	\N	\N
20260107093205	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Normalizar status para português\n-- Data: 2026-01-07\n-- Descrição: Padronizar valores de status de inglês para português\n-- Etapa: 1 - Correção da Base\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Passo 1: Atualizar valores existentes\nUPDATE tarefas \nSET status = CASE \n    WHEN status = 'pending' THEN 'pendente'\n    WHEN status = 'in_progress' THEN 'em_execucao'\n    WHEN status = 'completed' THEN 'concluida'\n    WHEN status = 'overdue' THEN 'atrasada'\n    ELSE status  -- Mantém valores já em português ou desconhecidos\nEND\nWHERE status IN ('pending', 'in_progress', 'completed', 'overdue');\n\n-- Passo 1.1: Limpeza de segurança (Fallback)\n-- Garante que qualquer status desconhecido/lixo seja movido para 'pendente'\n-- Isso evita erro de constraint violation se houverem status antigos esquecidos\nUPDATE tarefas\nSET status = 'pendente'\nWHERE status NOT IN ('pendente', 'em_execucao', 'concluida', 'atrasada');\n\n-- Passo 2: Atualizar constraint\nALTER TABLE tarefas DROP CONSTRAINT IF EXISTS tarefas_status_check;\n\nALTER TABLE tarefas ADD CONSTRAINT tarefas_status_check\n    CHECK (status IN ('pendente', 'em_execucao', 'concluida', 'atrasada'));\n\n-- Passo 3: Atualizar default\nALTER TABLE tarefas ALTER COLUMN status SET DEFAULT 'pendente';\n\n-- Log de execução\nDO $$\nDECLARE\n    updated_count INTEGER;\nBEGIN\n    SELECT COUNT(*) INTO updated_count FROM tarefas WHERE status IN ('pendente', 'em_execucao', 'concluida', 'atrasada');\n    RAISE NOTICE 'Migration completed. Total tarefas with normalized status: %', updated_count;\nEND $$;\n\nCOMMIT;"}	1000_normalize_task_status	redestvgmulti@gmail.com	\N	\N
20260107095219	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Allow Task Creators to Delete Their Tasks\n-- Data: 2026-01-07\n-- Descrição: Permite que quem criou a tarefa também possa excluí-la, além dos admins\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Drop existing restrictive DELETE policy\nDROP POLICY IF EXISTS \\"Only admins delete tasks\\" ON tarefas;\n\n-- Create new policy allowing both admins AND task creators to delete\nCREATE POLICY \\"Admins and creators can delete tasks\\"\nON tarefas FOR DELETE\nTO authenticated\nUSING (\n  -- Admin can delete all tasks\n  EXISTS (\n    SELECT 1 FROM profissionais\n    WHERE id = auth.uid()\n      AND role = 'admin'\n      AND ativo = true\n  )\n  OR\n  -- Task creator can delete their own tasks\n  created_by = auth.uid()\n);\n\n-- Update comment\nCOMMENT ON POLICY \\"Admins and creators can delete tasks\\" ON tarefas IS \n'Admins can delete all tasks. Task creators can delete only the tasks they created.';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE 'DELETE permission granted to task creators.';\nEND $$;\n\nCOMMIT;"}	1005_allow_creator_delete	redestvgmulti@gmail.com	\N	\N
20260107093218	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Backfill CONSERVADOR de empresa_id\n-- Data: 2026-01-07\n-- Descrição: Preencher APENAS empresa_id onde houver evidência confiável\n-- AJUSTE OBRIGATÓRIO: NÃO presumir assigned_to = created_by\n-- Apenas preencher empresa_id para dados legados\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Backfill empresa_id: pegar primeira empresa do assigned_to\n-- Estratégia conservadora: apenas onde assigned_to existe\nUPDATE tarefas t\nSET empresa_id = (\n    SELECT ep.empresa_id\n    FROM empresa_profissionais ep\n    WHERE ep.profissional_id = t.assigned_to\n    AND ep.ativo = true\n    ORDER BY ep.created_at ASC  -- Pega a mais antiga (presumivelmente a principal)\n    LIMIT 1\n)\nWHERE t.empresa_id IS NULL\nAND t.assigned_to IS NOT NULL;\n\n-- Log\nDO $$\nDECLARE\n    updated_count INTEGER;\n    still_null INTEGER;\nBEGIN\n    SELECT COUNT(*) INTO updated_count FROM tarefas WHERE empresa_id IS NOT NULL;\n    SELECT COUNT(*) INTO still_null FROM tarefas WHERE empresa_id IS NULL;\n    \n    RAISE NOTICE 'Backfill completed.';\n    RAISE NOTICE 'Tarefas with empresa_id: %', updated_count;\n    RAISE NOTICE 'Tarefas still NULL (acceptable for legacy): %', still_null;\nEND $$;\n\n-- ❌ NÃO fazer backfill de created_by (decisão aprovada)\n-- Dados legados permanecem com created_by = NULL\n-- Apenas tarefas NOVAS terão created_by preenchido\n\nCOMMIT;"}	1001_safe_backfill	redestvgmulti@gmail.com	\N	\N
20260107093715	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Fix RLS for Staff Access (Visibility of Colleagues)\n-- Data: 2026-01-07\n-- Descrição: Permitir que colaboradores vejam outros membros da MESMA empresa\n-- Necessário para o dropdown \\"Selecione um colaborador\\" funcionar\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Habilitar RLS em empresa_profissionais (segurança extra, caso não esteja)\nALTER TABLE empresa_profissionais ENABLE ROW LEVEL SECURITY;\n\n-- 2. Política: Ver membros da minha empresa em empresa_profissionais\n-- \\"Eu posso ver registros em empresa_profissionais SE esses registros pertencerem \n-- a uma empresa que EU também faço parte (e estou ativo)\\"\nDROP POLICY IF EXISTS \\"Ver membros da mesma empresa\\" ON empresa_profissionais;\n\nCREATE POLICY \\"Ver membros da mesma empresa\\"\nON empresa_profissionais FOR SELECT\nUSING (\n  empresa_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep \n    WHERE ep.profissional_id = auth.uid()\n    AND ep.ativo = true\n  )\n);\n\n-- 3. Política: Ver detalhes de profissionais da minha empresa\n-- \\"Eu posso ver dados básicos (nome, id) de profissionais que estão em\n-- empresas que eu também estou\\"\nDROP POLICY IF EXISTS \\"Ver colegas da mesma empresa\\" ON profissionais;\n\nCREATE POLICY \\"Ver colegas da mesma empresa\\"\nON profissionais FOR SELECT\nUSING (\n  id IN (\n    SELECT ep_colleague.profissional_id\n    FROM empresa_profissionais ep_colleague\n    WHERE ep_colleague.empresa_id IN (\n        -- Minhas empresas\n        SELECT ep_me.empresa_id \n        FROM empresa_profissionais ep_me \n        WHERE ep_me.profissional_id = auth.uid() \n        AND ep_me.ativo = true\n    )\n  )\n);\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE 'Policies for staff visibility applied successfully.';\nEND $$;\n\nCOMMIT;"}	1002_fix_rls_staff_access	redestvgmulti@gmail.com	\N	\N
20260107093814	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Fix RLS for Staff Access (Visibility of Colleagues)\n-- Data: 2026-01-07\n-- Descrição: Permitir que colaboradores vejam outros membros da MESMA empresa\n-- Necessário para o dropdown \\"Selecione um colaborador\\" funcionar\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Habilitar RLS em empresa_profissionais (segurança extra, caso não esteja)\nALTER TABLE empresa_profissionais ENABLE ROW LEVEL SECURITY;\n\n-- 2. Política: Ver membros da minha empresa em empresa_profissionais\n-- \\"Eu posso ver registros em empresa_profissionais SE esses registros pertencerem \n-- a uma empresa que EU também faço parte (e estou ativo)\\"\nDROP POLICY IF EXISTS \\"Ver membros da mesma empresa\\" ON empresa_profissionais;\n\nCREATE POLICY \\"Ver membros da mesma empresa\\"\nON empresa_profissionais FOR SELECT\nUSING (\n  empresa_id IN (\n    SELECT ep.empresa_id \n    FROM empresa_profissionais ep \n    WHERE ep.profissional_id = auth.uid()\n    AND ep.ativo = true\n  )\n);\n\n-- 3. Política: Ver detalhes de profissionais da minha empresa\n-- \\"Eu posso ver dados básicos (nome, id) de profissionais que estão em\n-- empresas que eu também estou\\"\nDROP POLICY IF EXISTS \\"Ver colegas da mesma empresa\\" ON profissionais;\n\nCREATE POLICY \\"Ver colegas da mesma empresa\\"\nON profissionais FOR SELECT\nUSING (\n  id IN (\n    SELECT ep_colleague.profissional_id\n    FROM empresa_profissionais ep_colleague\n    WHERE ep_colleague.empresa_id IN (\n        -- Minhas empresas\n        SELECT ep_me.empresa_id \n        FROM empresa_profissionais ep_me \n        WHERE ep_me.profissional_id = auth.uid() \n        AND ep_me.ativo = true\n    )\n  )\n);\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE 'Policies for staff visibility applied successfully.';\nEND $$;\n\nCOMMIT;"}	1002_fix_rls_staff_access	redestvgmulti@gmail.com	\N	\N
20260107093928	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Fix RLS Recursion (Infinite Loop)\n-- Data: 2026-01-07\n-- Descrição: Corrigir erro 500 causado por recursão infinita nas policies\n-- Solução: Usar função SECURITY DEFINER para buscar empresas do usuário\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Helper Function SECURITY DEFINER (Bypassa RLS)\n-- Retorna os IDs das empresas onde o usuário atual é membro ativo\nCREATE OR REPLACE FUNCTION get_my_company_ids()\nRETURNS SETOF uuid\nSECURITY DEFINER\nSET search_path = public -- Segurança: sempre definir search_path\nAS $$\nBEGIN\n  RETURN QUERY \n  SELECT ep.empresa_id \n  FROM empresa_profissionais ep \n  WHERE ep.profissional_id = auth.uid() \n  AND ep.ativo = true;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Corrigir Política de empresa_profissionais\nDROP POLICY IF EXISTS \\"Ver membros da mesma empresa\\" ON empresa_profissionais;\n\nCREATE POLICY \\"Ver membros da mesma empresa\\"\nON empresa_profissionais FOR SELECT\nUSING (\n  empresa_id IN ( SELECT get_my_company_ids() )\n);\n\n-- 3. Corrigir Política de profissionais\nDROP POLICY IF EXISTS \\"Ver colegas da mesma empresa\\" ON profissionais;\n\nCREATE POLICY \\"Ver colegas da mesma empresa\\"\nON profissionais FOR SELECT\nUSING (\n  id IN (\n    SELECT ep.profissional_id\n    FROM empresa_profissionais ep\n    WHERE ep.empresa_id IN ( SELECT get_my_company_ids() )\n  )\n);\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE 'RLS recursion fixed using SECURITY DEFINER function.';\nEND $$;\n\nCOMMIT;"}	1003_fix_rls_recursion	redestvgmulti@gmail.com	\N	\N
20260107094224	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration: Definitively Break RLS Recursion\n-- Data: 2026-01-07\n-- Descrição: Substituir a lógica de subquery RLS por uma função SECURITY DEFINER\n-- completa, evitando qualquer verificação de policy durante o filtro de colegas.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Helper Function: Obter IDs de colegas visíveis (SECURITY DEFINER)\n-- Retorna IDs de todos os profissionais que estão nas mesmas empresas que o usuário\nCREATE OR REPLACE FUNCTION get_visible_colleagues()\nRETURNS SETOF uuid\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  RETURN QUERY\n  SELECT DISTINCT ep_target.profissional_id\n  FROM empresa_profissionais ep_target\n  WHERE ep_target.empresa_id IN (\n    SELECT ep_me.empresa_id\n    FROM empresa_profissionais ep_me\n    WHERE ep_me.profissional_id = auth.uid()\n    AND ep_me.ativo = true\n  )\n  AND ep_target.ativo = true;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 1.1 Helper Function: Check Admin Safe (SECURITY DEFINER)\n-- Evita recursão ao verificar se é admin\nCREATE OR REPLACE FUNCTION is_admin_safe()\nRETURNS BOOLEAN\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  RETURN EXISTS (\n    SELECT 1 FROM profissionais\n    WHERE id = auth.uid()\n    AND role = 'admin'\n    AND ativo = true\n  );\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Atualizar Policy em 'profissionais'\nDROP POLICY IF EXISTS \\"Ver colegas da mesma empresa\\" ON profissionais;\n\nCREATE POLICY \\"Ver colegas da mesma empresa\\"\nON profissionais FOR SELECT\nUSING (\n  id IN ( SELECT get_visible_colleagues() )\n);\n\n-- 3. Limpar e Recriar Policies de 'empresa_profissionais'\nDO $$ \nDECLARE \n  r RECORD; \nBEGIN \n  FOR r IN (SELECT policyname FROM pg_policies WHERE tablename = 'empresa_profissionais') LOOP \n    EXECUTE 'DROP POLICY IF EXISTS \\"' || r.policyname || '\\" ON empresa_profissionais'; \n  END LOOP; \nEND $$;\n\n-- 3.1 Admin: Acesso total (usando função SAFE)\nCREATE POLICY \\"Admin Total Access\\"\nON empresa_profissionais FOR ALL\nUSING (is_admin_safe());\n\n-- 3.2 Staff: Ver membros das minhas empresas\nCREATE POLICY \\"Staff Ver Membros Mesma Empresa\\"\nON empresa_profissionais FOR SELECT\nUSING (\n   empresa_id IN ( SELECT get_my_company_ids() )\n);\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE 'Recursion loop broken via Function encapsulation + Safe Admin check.';\nEND $$;\n\nCOMMIT;"}	1004_break_recursion_final	redestvgmulti@gmail.com	\N	\N
20260107103154	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1008: Criar tabela os_eventos e enum\n-- Data: 2026-01-07\n-- Descrição: Criar estrutura de eventos para timeline da OS,\n--            com tipos de evento definidos e metadata JSON flexível\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Criar enum de tipos de evento\nCREATE TYPE os_evento_tipo AS ENUM (\n    -- CORE (Obrigatórios ETAPA 3)\n    'os_criada',\n    'comentario_adicionado',\n    'status_alterado',\n    \n    -- OPCIONAL (ETAPA 3 ou 4)\n    'prioridade_alterada',\n    'deadline_alterada',\n    'profissional_atribuido',\n    'profissional_removido',\n    \n    -- FUTURO (ETAPA 4+)\n    'microtask_criada',\n    'microtask_concluida',\n    'microtask_devolvida',\n    'os_excluida'\n);\n\nCOMMENT ON TYPE os_evento_tipo IS 'Tipos de eventos da OS. Core (ETAPA 3): os_criada, comentario_adicionado, status_alterado';\n\n-- Criar tabela de eventos\nCREATE TABLE os_eventos (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    os_id UUID NOT NULL REFERENCES tarefas(id) ON DELETE CASCADE,\n    tipo os_evento_tipo NOT NULL,\n    autor_id UUID REFERENCES profissionais(id) ON DELETE SET NULL, -- NULL = sistema\n    metadata JSONB, -- Dados contextuais do evento\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    \n    -- Constraint: metadata deve ser objeto JSON válido ou NULL\n    CONSTRAINT metadata_valido CHECK (metadata IS NULL OR jsonb_typeof(metadata) = 'object')\n);\n\n-- Índices para performance\nCREATE INDEX idx_os_eventos_os_id ON os_eventos(os_id);\nCREATE INDEX idx_os_eventos_tipo ON os_eventos(tipo);\nCREATE INDEX idx_os_eventos_created_at ON os_eventos(created_at DESC);\nCREATE INDEX idx_os_eventos_autor_id ON os_eventos(autor_id) WHERE autor_id IS NOT NULL;\n\n-- Enable RLS\nALTER TABLE os_eventos ENABLE ROW LEVEL SECURITY;\n\n-- Comentários\nCOMMENT ON TABLE os_eventos IS 'Timeline de eventos da OS. Eventos são IMUTÁVEIS (sem UPDATE/DELETE policies).';\nCOMMENT ON COLUMN os_eventos.os_id IS 'Referência à OS (tarefa)';\nCOMMENT ON COLUMN os_eventos.tipo IS 'Tipo do evento (enum)';\nCOMMENT ON COLUMN os_eventos.autor_id IS 'Profissional que causou o evento. NULL = sistema/automático';\nCOMMENT ON COLUMN os_eventos.metadata IS 'Dados contextuais em JSON. Estrutura varia por tipo de evento';\nCOMMENT ON COLUMN os_eventos.created_at IS 'Timestamp de criação do evento (imutável)';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1008: Tabela os_eventos e enum os_evento_tipo criados';\nEND $$;\n\nCOMMIT;"}	1008_criar_os_eventos	redestvgmulti@gmail.com	\N	\N
20260107103220	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1009: Criar função is_os_participant()\n-- Data: 2026-01-07\n-- Descrição: Função helper SECURITY DEFINER para verificar se usuário\n--            é participante de uma OS. Centraliza lógica de RLS.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Criar função helper para verificar participação em OS\nCREATE OR REPLACE FUNCTION is_os_participant(p_os_id UUID)\nRETURNS BOOLEAN\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n    RETURN EXISTS (\n        SELECT 1 FROM tarefas t\n        WHERE t.id = p_os_id\n        AND (\n            -- Admin vê tudo (usando função safe)\n            is_admin_safe()\n            OR\n            -- Criador da OS\n            t.created_by = auth.uid()\n            OR\n            -- Atribuído direto (OS simples)\n            t.assigned_to = auth.uid()\n            OR\n            -- Atribuído via micro-task (OS complexa)\n            EXISTS (\n                SELECT 1 FROM tarefas_micro tm\n                WHERE tm.tarefa_id = t.id\n                AND tm.profissional_id = auth.uid()\n            )\n        )\n    );\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Comentários\nCOMMENT ON FUNCTION is_os_participant IS 'ETAPA 3: Verifica se usuário autenticado é participante da OS (criador, atribuído direto, ou micro-task). Usa SECURITY DEFINER para evitar recursão RLS.';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1009: Função is_os_participant() criada (SECURITY DEFINER)';\nEND $$;\n\nCOMMIT;"}	1009_criar_is_os_participant	redestvgmulti@gmail.com	\N	\N
20260107103302	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1010: RLS Policies para comentários e eventos\n-- Data: 2026-01-07\n-- Descrição: Atualizar policies de task_comments e criar policies de os_eventos\n--            usando função is_os_participant() para DRY e segurança\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 1. ATUALIZAR POLICIES: task_comments\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Drop policies antigas\nDROP POLICY IF EXISTS \\"Professionals view comments on accessible tasks\\" ON task_comments;\nDROP POLICY IF EXISTS \\"Professionals insert comments on accessible tasks\\" ON task_comments;\nDROP POLICY IF EXISTS \\"Admins manage all comments\\" ON task_comments;\nDROP POLICY IF EXISTS \\"Service role manages all comments\\" ON task_comments;\n\n-- SELECT: Participantes veem comentários não deletados\nCREATE POLICY \\"Ver comentários da OS\\"\nON task_comments FOR SELECT\nTO authenticated\nUSING (\n    deleted_at IS NULL\n    AND is_os_participant(task_id)\n);\n\n-- INSERT: Participantes criam comentários\nCREATE POLICY \\"Criar comentário na OS\\"\nON task_comments FOR INSERT\nTO authenticated\nWITH CHECK (\n    author_id = auth.uid()\n    AND is_os_participant(task_id)\n);\n\n-- UPDATE: Autor edita nos primeiros 15min OU admin sempre\nCREATE POLICY \\"Editar próprio comentário\\"\nON task_comments FOR UPDATE\nTO authenticated\nUSING (\n    deleted_at IS NULL\n    AND (\n        (\n            author_id = auth.uid()\n            AND created_at > NOW() - INTERVAL '15 minutes'\n        )\n        OR is_admin_safe()\n    )\n)\nWITH CHECK (\n    -- Não pode mudar autor ou task_id\n    author_id = (SELECT author_id FROM task_comments WHERE id = task_comments.id)\n    AND task_id = (SELECT task_id FROM task_comments WHERE id = task_comments.id)\n);\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 2. CRIAR POLICIES: os_eventos\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- SELECT: Participantes veem eventos\nCREATE POLICY \\"Ver eventos da OS\\"\nON os_eventos FOR SELECT\nTO authenticated\nUSING (is_os_participant(os_id));\n\n-- INSERT: Participantes ou sistema criam eventos\nCREATE POLICY \\"Criar evento na OS\\"\nON os_eventos FOR INSERT\nTO authenticated\nWITH CHECK (\n    (autor_id IS NULL OR autor_id = auth.uid())\n    AND is_os_participant(os_id)\n);\n\n-- UPDATE/DELETE: Não há policies = eventos são IMUTÁVEIS\n\n-- Comentários\nCOMMENT ON POLICY \\"Ver comentários da OS\\" ON task_comments IS 'ETAPA 3: Participantes veem comentários não deletados da OS';\nCOMMENT ON POLICY \\"Criar comentário na OS\\" ON task_comments IS 'ETAPA 3: Participantes criam comentários em OSs que participam';\nCOMMENT ON POLICY \\"Editar próprio comentário\\" ON task_comments IS 'ETAPA 3: Autor edita nos primeiros 15min OU admin sempre';\nCOMMENT ON POLICY \\"Ver eventos da OS\\" ON os_eventos IS 'ETAPA 3: Participantes veem eventos da OS';\nCOMMENT ON POLICY \\"Criar evento na OS\\" ON os_eventos IS 'ETAPA 3: Participantes criam eventos (autor_id validado)';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1010: RLS policies atualizadas para task_comments e os_eventos';\nEND $$;\n\nCOMMIT;"}	1010_rls_comentarios_eventos	redestvgmulti@gmail.com	\N	\N
20260107103336	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1011: Criar tabela notificacoes\n-- Data: 2026-01-07\n-- Descrição: Criar estrutura de notificações in-app baseadas em eventos\n--            para manter participantes informados sobre novidades na OS\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Criar tabela de notificações\nCREATE TABLE notificacoes (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    profissional_id UUID NOT NULL REFERENCES profissionais(id) ON DELETE CASCADE,\n    os_id UUID REFERENCES tarefas(id) ON DELETE CASCADE,\n    evento_id UUID REFERENCES os_eventos(id) ON DELETE CASCADE,\n    tipo VARCHAR(50) NOT NULL,\n    titulo TEXT NOT NULL,\n    mensagem TEXT,\n    lida BOOLEAN DEFAULT false,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    \n    -- Constraint: deve ter referência a OS ou evento\n    CONSTRAINT tem_referencia CHECK (os_id IS NOT NULL OR evento_id IS NOT NULL)\n);\n\n-- Índices para performance\nCREATE INDEX idx_notificacoes_profissional ON notificacoes(profissional_id);\nCREATE INDEX idx_notificacoes_lida ON notificacoes(lida) WHERE lida = false;\nCREATE INDEX idx_notificacoes_created_at ON notificacoes(created_at DESC);\nCREATE INDEX idx_notificacoes_os_id ON notificacoes(os_id) WHERE os_id IS NOT NULL;\n\n-- Enable RLS\nALTER TABLE notificacoes ENABLE ROW LEVEL SECURITY;\n\n-- Policy: Ver próprias notificações\nCREATE POLICY \\"Ver próprias notificações\\"\nON notificacoes FOR SELECT\nTO authenticated\nUSING (profissional_id = auth.uid());\n\n-- Policy: Marcar como lida\nCREATE POLICY \\"Marcar como lida\\"\nON notificacoes FOR UPDATE\nTO authenticated\nUSING (profissional_id = auth.uid())\nWITH CHECK (\n    profissional_id = auth.uid()\n    -- Apenas permite UPDATE em 'lida'\n    AND lida IN (true, false)\n);\n\n-- Policy: Criar notificação (apenas sistema/triggers)\nCREATE POLICY \\"Sistema cria notificações\\"\nON notificacoes FOR INSERT\nTO authenticated\nWITH CHECK (profissional_id IS NOT NULL);\n\n-- Comentários\nCOMMENT ON TABLE notificacoes IS 'Notificações in-app para profissionais sobre eventos em OSs';\nCOMMENT ON COLUMN notificacoes.profissional_id IS 'Destinatário da notificação';\nCOMMENT ON COLUMN notificacoes.os_id IS 'OS relacionada (opcional)';\nCOMMENT ON COLUMN notificacoes.evento_id IS 'Evento que gerou a notificação (opcional)';\nCOMMENT ON COLUMN notificacoes.tipo IS 'Tipo da notificação (corresponde a os_evento_tipo)';\nCOMMENT ON COLUMN notificacoes.titulo IS 'Título curto da notificação';\nCOMMENT ON COLUMN notificacoes.mensagem IS 'Texto completo da notificação';\nCOMMENT ON COLUMN notificacoes.lida IS 'Se notificação foi visualizada';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1011: Tabela notificacoes criada com RLS';\nEND $$;\n\nCOMMIT;"}	1011_criar_notificacoes	redestvgmulti@gmail.com	\N	\N
20260107115854	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1018: Ajustar schema para ETAPA 4\n-- Data: 2026-01-07\n-- Descrição: Adicionar has_micro_tasks e deleted_at ao schema\n--            Preparar schema para governança\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Adicionar campo has_micro_tasks (se não existir)\nALTER TABLE tarefas\nADD COLUMN IF NOT EXISTS has_micro_tasks BOOLEAN DEFAULT false;\n\n-- 2. Atualizar valores existentes baseado na existência de micro-tasks\nUPDATE tarefas t\nSET has_micro_tasks = EXISTS (\n    SELECT 1 FROM tarefas_micro tm\n    WHERE tm.tarefa_id = t.id\n);\n\n-- 3. Definir NOT NULL para has_micro_tasks\nALTER TABLE tarefas\nALTER COLUMN has_micro_tasks SET NOT NULL;\n\n-- 4. Adicionar campo deleted_at para soft delete\nALTER TABLE tarefas\nADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;\n\n-- 5. Índice para performance em queries de OSs não excluídas\nCREATE INDEX IF NOT EXISTS idx_tarefas_deleted_at \nON tarefas(deleted_at) \nWHERE deleted_at IS NOT NULL;\n\n-- 6. Índice para filtrar OSs ativas (não excluídas)\nCREATE INDEX IF NOT EXISTS idx_tarefas_ativas \nON tarefas(empresa_id, status) \nWHERE deleted_at IS NULL;\n\n-- 7. Índice para OSs complexas\nCREATE INDEX IF NOT EXISTS idx_tarefas_has_micro \nON tarefas(has_micro_tasks) \nWHERE has_micro_tasks = true;\n\n-- Comentários\nCOMMENT ON COLUMN tarefas.has_micro_tasks IS 'ETAPA 4: Flag auxiliar. TRUE = OS complexa (workflow). Fonte da verdade: existência de registros em tarefas_micro. Calculado automaticamente na conversão';\nCOMMENT ON COLUMN tarefas.deleted_at IS 'ETAPA 4: Soft delete. NULL = ativa, NOT NULL = excluída. Evento os_excluida registra a exclusão';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1018: Schema ajustado para ETAPA 4 (has_micro_tasks, deleted_at)';\nEND $$;\n\nCOMMIT;"}	1018_ajustar_schema_etapa4	redestvgmulti@gmail.com	\N	\N
20260107103541	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1012: Trigger os_criada\n-- Data: 2026-01-07\n-- Descrição: Registrar evento automático quando uma OS é criada.\n--            CORE da ETAPA 3.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Função trigger: Registrar evento quando OS é criada\nCREATE OR REPLACE FUNCTION registrar_evento_os_criada()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n    -- Inserir evento na timeline\n    INSERT INTO os_eventos (os_id, tipo, autor_id, metadata)\n    VALUES (\n        NEW.id,\n        'os_criada',\n        NEW.created_by, -- ✅ Usa campo persistido, NÃO auth.uid()\n        jsonb_build_object(\n            'titulo', NEW.titulo,\n            'prioridade', NEW.prioridade,\n            'deadline', NEW.deadline\n        )\n    );\n    \n    RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n    -- Log erro mas não bloqueia criação da OS\n    RAISE WARNING 'Falha ao registrar evento os_criada para OS %: %', NEW.id, SQLERRM;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Criar trigger\nDROP TRIGGER IF EXISTS trigger_os_criada ON tarefas;\n\nCREATE TRIGGER trigger_os_criada\n    AFTER INSERT ON tarefas\n    FOR EACH ROW\n    EXECUTE FUNCTION registrar_evento_os_criada();\n\n-- Comentários\nCOMMENT ON FUNCTION registrar_evento_os_criada IS 'ETAPA 3 CORE: Registra evento os_criada automaticamente. Usa NEW.created_by (não auth.uid).';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1012: Trigger os_criada criado (evento automático)';\nEND $$;\n\nCOMMIT;"}	1012_trigger_os_criada	redestvgmulti@gmail.com	\N	\N
20260107103547	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1013: Trigger status_alterado\n-- Data: 2026-01-07\n-- Descrição: Registrar evento automático quando status da OS é alterado.\n--            CORE da ETAPA 3.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Função trigger: Registrar evento quando status muda\nCREATE OR REPLACE FUNCTION registrar_evento_status_alterado()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n    -- Apenas se status mudou de fato\n    IF OLD.status IS DISTINCT FROM NEW.status THEN\n        INSERT INTO os_eventos (os_id, tipo, autor_id, metadata)\n        VALUES (\n            NEW.id,\n            'status_alterado',\n            NULL, -- ✅ Sistema (não sabemos quem alterou específicamente)\n            jsonb_build_object(\n                'de', OLD.status,\n                'para', NEW.status\n            )\n        );\n    END IF;\n    \n    RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n    RAISE WARNING 'Falha ao registrar evento status_alterado para OS %: %', NEW.id, SQLERRM;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Criar trigger\nDROP TRIGGER IF EXISTS trigger_status_alterado ON tarefas;\n\nCREATE TRIGGER trigger_status_alterado\n    AFTER UPDATE ON tarefas\n    FOR EACH ROW\n    EXECUTE FUNCTION registrar_evento_status_alterado();\n\n-- Comentários\nCOMMENT ON FUNCTION registrar_evento_status_alterado IS 'ETAPA 3 CORE: Registra evento status_alterado quando status muda. autor_id = NULL (sistema).';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1013: Trigger status_alterado criado (evento automático)';\nEND $$;\n\nCOMMIT;"}	1013_trigger_status_alterado	redestvgmulti@gmail.com	\N	\N
20260107103627	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1014: Trigger comentario_adicionado\n-- Data: 2026-01-07\n-- Descrição: Registrar evento automático quando comentário é adicionado.\n--            CORE da ETAPA 3.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Função trigger: Registrar evento quando comentário é criado\nCREATE OR REPLACE FUNCTION registrar_evento_comentario()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n    -- Inserir evento na timeline\n    INSERT INTO os_eventos (os_id, tipo, autor_id, metadata)\n    VALUES (\n        NEW.task_id, -- task_comments usa 'task_id' como FK\n        'comentario_adicionado',\n        NEW.author_id, -- ✅ Autor do comentário (campo persistido)\n        jsonb_build_object(\n            'comentario_id', NEW.id,\n            'preview', LEFT(NEW.content, 100) -- Preview de 100 chars\n        )\n    );\n    \n    RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n    RAISE WARNING 'Falha ao registrar evento comentario para task %: %', NEW.task_id, SQLERRM;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Criar trigger\nDROP TRIGGER IF EXISTS trigger_comentario_adicionado ON task_comments;\n\nCREATE TRIGGER trigger_comentario_adicionado\n    AFTER INSERT ON task_comments\n    FOR EACH ROW\n    EXECUTE FUNCTION registrar_evento_comentario();\n\n-- Comentários\nCOMMENT ON FUNCTION registrar_evento_comentario IS 'ETAPA 3 CORE: Registra evento comentario_adicionado automaticamente. Usa NEW.author_id.';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1014: Trigger comentario_adicionado criado (evento automático)';\nEND $$;\n\nCOMMIT;"}	1014_trigger_comentario_adicionado	redestvgmulti@gmail.com	\N	\N
20260107103639	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1015: Trigger criar_notificacoes\n-- Data: 2026-01-07\n-- Descrição: Criar notificações automaticamente quando eventos relevantes\n--            ocorrem, notificando participantes EXCETO o autor do evento.\n--            CORE da ETAPA 3.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Função trigger: Criar notificações para eventos\nCREATE OR REPLACE FUNCTION criar_notificacoes_evento()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    participante RECORD;\n    titulo_notif TEXT;\n    mensagem_notif TEXT;\n    deve_notificar BOOLEAN;\nBEGIN\n    -- Determinar se deve notificar baseado no tipo de evento\n    deve_notificar := CASE NEW.tipo\n        WHEN 'comentario_adicionado' THEN TRUE\n        WHEN 'status_alterado' THEN TRUE\n        WHEN 'profissional_atribuido' THEN TRUE\n        ELSE FALSE\n    END CASE;\n    \n    IF NOT deve_notificar THEN\n        RETURN NEW;\n    END IF;\n    \n    -- Montar texto da notificação baseado no tipo\n    CASE NEW.tipo\n        WHEN 'comentario_adicionado' THEN\n            titulo_notif := 'Novo comentário';\n            mensagem_notif := NEW.metadata->>'preview';\n            \n        WHEN 'status_alterado' THEN\n            titulo_notif := 'Status atualizado';\n            mensagem_notif := format('De \\"%s\\" para \\"%s\\"', \n                NEW.metadata->>'de', \n                NEW.metadata->>'para');\n                \n        WHEN 'profissional_atribuido' THEN\n            titulo_notif := 'Você foi atribuído';\n            mensagem_notif := 'Nova OS atribuída a você';\n            \n        ELSE\n            titulo_notif := 'Atualização na OS';\n            mensagem_notif := NULL;\n    END CASE;\n    \n    -- Notificar participantes (EXCETO o autor do evento)\n    FOR participante IN\n        SELECT DISTINCT p.id\n        FROM profissionais p\n        INNER JOIN tarefas t ON t.id = NEW.os_id\n        WHERE (\n            -- Criador da OS\n            t.created_by = p.id\n            OR\n            -- Atribuído direto\n            t.assigned_to = p.id\n            OR\n            -- Atribuído via micro-task\n            EXISTS (\n                SELECT 1 FROM tarefas_micro tm\n                WHERE tm.tarefa_id = t.id \n                AND tm.profissional_id = p.id\n            )\n        )\n        -- EXCLUIR o autor do evento (não notificar a si mesmo)\n        AND p.id != COALESCE(NEW.autor_id, '00000000-0000-0000-0000-000000000000'::uuid)\n        AND p.ativo = true\n    LOOP\n        INSERT INTO notificacoes (\n            profissional_id, \n            evento_id, \n            os_id, \n            tipo, \n            titulo, \n            mensagem\n        ) VALUES (\n            participante.id, \n            NEW.id, \n            NEW.os_id, \n            NEW.tipo::VARCHAR, \n            titulo_notif, \n            mensagem_notif\n        );\n    END LOOP;\n    \n    RETURN NEW;\nEXCEPTION WHEN OTHERS THEN\n    RAISE WARNING 'Falha ao criar notificações para evento %: %', NEW.id, SQLERRM;\n    RETURN NEW; -- Não bloqueia criação do evento\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Criar trigger\nDROP TRIGGER IF EXISTS trigger_notificacoes_evento ON os_eventos;\n\nCREATE TRIGGER trigger_notificacoes_evento\n    AFTER INSERT ON os_eventos\n    FOR EACH ROW\n    EXECUTE FUNCTION criar_notificacoes_evento();\n\n-- Comentários\nCOMMENT ON FUNCTION criar_notificacoes_evento IS 'ETAPA 3 CORE: Cria notificações automaticamente para participantes da OS (exceto autor do evento).';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1015: Trigger notificacoes criado (cascata automática)';\nEND $$;\n\nCOMMIT;"}	1015_trigger_notificacoes	redestvgmulti@gmail.com	\N	\N
20260107113302	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1016: Criar VIEW os_timeline_view\n-- Data: 2026-01-07\n-- Descrição: VIEW unificada que combina comentários (task_comments) e\n--            eventos (os_eventos) em uma única timeline ordenada\n--            cronologicamente. Aplica RLS inline para blindagem multi-tenant.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Criar VIEW unificada de timeline\nCREATE OR REPLACE VIEW os_timeline_view\nWITH (security_invoker = true) -- Força aplicação de RLS\nAS\n-- COMENTÁRIOS\nSELECT\n    'comentario' AS item_tipo,\n    c.id,\n    c.task_id AS os_id,\n    c.content AS texto,\n    NULL::os_evento_tipo AS evento_tipo,\n    NULL::JSONB AS metadata,\n    c.author_id AS autor_id,\n    p.nome AS autor_nome,\n    c.editado,\n    c.created_at,\n    c.updated_at,\n    \n    -- ✅ BLINDAGEM MULTI-TENANT: Validar empresa_id\n    (SELECT empresa_id FROM tarefas WHERE id = c.task_id) AS empresa_id\n    \nFROM task_comments c\nLEFT JOIN profissionais p ON p.id = c.author_id\nWHERE c.deleted_at IS NULL -- Apenas comentários não deletados\n  AND is_os_participant(c.task_id) -- ✅ RLS inline\n\nUNION ALL\n\n-- EVENTOS\nSELECT\n    'evento' AS item_tipo,\n    e.id,\n    e.os_id,\n    NULL AS texto,\n    e.tipo AS evento_tipo,\n    e.metadata,\n    e.autor_id,\n    p.nome AS autor_nome,\n    NULL AS editado,\n    e.created_at,\n    NULL AS updated_at,\n    \n    -- ✅ BLINDAGEM MULTI-TENANT: Validar empresa_id\n    (SELECT empresa_id FROM tarefas WHERE id = e.os_id) AS empresa_id\n    \nFROM os_eventos e\nLEFT JOIN profissionais p ON p.id = e.autor_id\nWHERE is_os_participant(e.os_id); -- ✅ RLS inline\n\n-- Comentários\nCOMMENT ON VIEW os_timeline_view IS 'ETAPA 3: Timeline unificada de comentários e eventos. Aplica RLS via is_os_participant() inline. security_invoker = true força verificação de permissões.';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1016: VIEW os_timeline_view criada (comentários + eventos)';\nEND $$;\n\nCOMMIT;"}	1016_criar_os_timeline_view	redestvgmulti@gmail.com	\N	\N
20260107115807	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1017: Adicionar eventos de governança ao enum\n-- Data: 2026-01-07\n-- Descrição: Adicionar novos tipos de evento para ETAPA 4 (Governança)\n--            Eventos estruturais e de auditoria\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Adicionar novos valores ao enum os_evento_tipo\n-- NOTA: Postgres não permite ADD IF NOT EXISTS em enum antes de v12\n-- Usamos DO block para evitar erro se já existir\n\nDO $$\nBEGIN\n    -- Eventos de governança\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'os_convertida_complexa';\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'etapa_adicionada';\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'etapa_removida';\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'prazo_alterado';\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'responsavel_reatribuido';\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'titulo_alterado';\n    ALTER TYPE os_evento_tipo ADD VALUE IF NOT EXISTS 'os_excluida';\nEXCEPTION WHEN duplicate_object THEN\n    RAISE NOTICE 'Valores de enum já existem, ignorando';\nEND $$;\n\n-- Comentários\nCOMMENT ON TYPE os_evento_tipo IS 'ETAPA 3+4: Tipos de eventos da OS. Core (ETAPA 3): os_criada, comentario_adicionado, status_alterado. Governança (ETAPA 4): os_convertida_complexa, etapa_adicionada/removida, prazo_alterado, responsavel_reatribuido, titulo_alterado, os_excluida';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1017: Enum os_evento_tipo atualizado com eventos de governança (ETAPA 4)';\nEND $$;\n\nCOMMIT;"}	1017_adicionar_eventos_governanca	redestvgmulti@gmail.com	\N	\N
20260107115957	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1019: Criar funções de permissão (ETAPA 4)\n-- Data: 2026-01-07\n-- Descrição: Funções helper SECURITY DEFINER para validar permissões\n--            Centraliza lógica de governança\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 1. can_change_deadline: Verificar se usuário pode alterar prazo\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION can_change_deadline(\n    p_os_id UUID,\n    p_user_id UUID\n)\nRETURNS BOOLEAN\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    os_record RECORD;\nBEGIN\n    -- Buscar dados da OS\n    SELECT status, created_by, deleted_at\n    INTO os_record\n    FROM tarefas \n    WHERE id = p_os_id;\n    \n    -- OS não encontrada ou excluída\n    IF os_record IS NULL OR os_record.deleted_at IS NOT NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Admin sempre pode (se ativa)\n    IF is_admin_safe() THEN\n        RETURN TRUE;\n    END IF;\n    \n    -- Criador pode se pendente\n    IF os_record.created_by = p_user_id \n       AND os_record.status = 'pendente' THEN\n        RETURN TRUE;\n    END IF;\n    \n    RETURN FALSE;\nEND;\n$$ LANGUAGE plpgsql;\n\nCOMMENT ON FUNCTION can_change_deadline IS 'ETAPA 4: Verifica se p_user_id pode alterar deadline da OS. Admin sempre pode, Criador apenas se pendente';\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 2. can_convert_to_complex: Verificar se pode converter OS → complexa\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION can_convert_to_complex(\n    p_os_id UUID,\n    p_user_id UUID\n)\nRETURNS BOOLEAN\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    os_record RECORD;\nBEGIN\n    -- Apenas admin\n    IF NOT is_admin_safe() THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Buscar dados da OS\n    SELECT status, has_micro_tasks, deleted_at\n    INTO os_record\n    FROM tarefas \n    WHERE id = p_os_id;\n    \n    -- OS não encontrada ou excluída\n    IF os_record IS NULL OR os_record.deleted_at IS NOT NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Não pode estar concluída\n    IF os_record.status IN ('concluida', 'cancelada') THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Não pode já ser complexa\n    IF os_record.has_micro_tasks = TRUE THEN\n        RETURN FALSE;\n    END IF;\n    \n    RETURN TRUE;\nEND;\n$$ LANGUAGE plpgsql;\n\nCOMMENT ON FUNCTION can_convert_to_complex IS 'ETAPA 4: Verifica se p_user_id pode converter OS em complexa. Apenas admin, e OS não pode estar concluída ou já ser complexa';\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 3. can_delete_os: Verificar se pode excluir OS (soft delete)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION can_delete_os(\n    p_os_id UUID,\n    p_user_id UUID\n)\nRETURNS BOOLEAN\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    os_record RECORD;\n    event_count INT;\nBEGIN\n    -- Buscar dados da OS\n    SELECT status, created_by, deleted_at\n    INTO os_record\n    FROM tarefas \n    WHERE id = p_os_id;\n    \n    -- OS não encontrada ou já excluída\n    IF os_record IS NULL OR os_record.deleted_at IS NOT NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Admin sempre pode\n    IF is_admin_safe() THEN\n        RETURN TRUE;\n    END IF;\n    \n    -- Criador pode se pendente E sem atividade além de os_criada\n    IF os_record.created_by = p_user_id \n       AND os_record.status = 'pendente' THEN\n        \n        -- Contar eventos (além de os_criada)\n        SELECT COUNT(*) INTO event_count\n        FROM os_eventos\n        WHERE os_id = p_os_id\n        AND tipo != 'os_criada';\n        \n        -- Permitir apenas se sem atividade\n        IF event_count = 0 THEN\n            RETURN TRUE;\n        END IF;\n    END IF;\n    \n    RETURN FALSE;\nEND;\n$$ LANGUAGE plpgsql;\n\nCOMMENT ON FUNCTION can_delete_os IS 'ETAPA 4: Verifica se p_user_id pode excluir OS. Admin sempre pode, Criador apenas se pendente e sem atividade (eventos além de os_criada)';\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 4. can_add_micro_tasks: Verificar se pode adicionar micro-tasks\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION can_add_micro_tasks(\n    p_os_id UUID,\n    p_user_id UUID\n)\nRETURNS BOOLEAN\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    os_record RECORD;\nBEGIN\n    -- Apenas admin\n    IF NOT is_admin_safe() THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Buscar dados da OS\n    SELECT status, has_micro_tasks, deleted_at\n    INTO os_record\n    FROM tarefas \n    WHERE id = p_os_id;\n    \n    -- OS não encontrada ou excluída\n    IF os_record IS NULL OR os_record.deleted_at IS NOT NULL THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Não pode estar concluída\n    IF os_record.status IN ('concluida', 'cancelada') THEN\n        RETURN FALSE;\n    END IF;\n    \n    -- Deve ser complexa (ou em processo de conversão)\n    IF os_record.has_micro_tasks = FALSE THEN\n        RETURN FALSE;\n    END IF;\n    \n    RETURN TRUE;\nEND;\n$$ LANGUAGE plpgsql;\n\nCOMMENT ON FUNCTION can_add_micro_tasks IS 'ETAPA 4: Verifica se p_user_id pode adicionar micro-tasks. Apenas admin, e OS deve ser complexa e não estar concluída';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1019: Funções de permissão criadas (ETAPA 4)';\nEND $$;\n\nCOMMIT;"}	1019_criar_funcoes_permissao	redestvgmulti@gmail.com	\N	\N
20260107120049	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1020: Criar RPC get_os_permissions (ETAPA 4)\n-- Data: 2026-01-07\n-- Descrição: RPC que retorna JSON com todas permissões calculadas\n--            para uso no frontend (hook useOSPermissions)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- RPC: Calcular todas permissões para uma OS\nCREATE OR REPLACE FUNCTION get_os_permissions(p_os_id UUID)\nRETURNS JSON\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    user_id UUID := auth.uid();\n    os_record RECORD;\n    result JSON;\nBEGIN\n    -- Buscar dados da OS\n    SELECT \n        status, \n        created_by, \n        assigned_to,\n        has_micro_tasks,\n        deleted_at\n    INTO os_record\n    FROM tarefas \n    WHERE id = p_os_id;\n    \n    -- OS não encontrada\n    IF os_record IS NULL THEN\n        RETURN json_build_object(\n            'error', 'OS não encontrada',\n            'can_view', false\n        );\n    END IF;\n    \n    -- OS excluída\n    IF os_record.deleted_at IS NOT NULL THEN\n        RETURN json_build_object(\n            'error', 'OS excluída',\n            'can_view', false,\n            'is_deleted', true\n        );\n    END IF;\n    \n    -- Calcular permissões\n    SELECT json_build_object(\n        -- Identificação\n        'is_admin', is_admin_safe(),\n        'is_creator', os_record.created_by = user_id,\n        'is_assigned', os_record.assigned_to = user_id,\n        'is_participant', is_os_participant(p_os_id),\n        \n        -- Estado da OS\n        'os_status', os_record.status,\n        'is_complex', os_record.has_micro_tasks,\n        'is_deleted', os_record.deleted_at IS NOT NULL,\n        \n        -- Permissões de Visualização\n        'can_view', is_os_participant(p_os_id),\n        'can_view_timeline', is_os_participant(p_os_id),\n        \n        -- Permissões de Colaboração\n        'can_comment', is_os_participant(p_os_id),\n        'can_add_link', (\n            is_admin_safe() OR \n            os_record.created_by = user_id OR\n            os_record.assigned_to = user_id\n        ),\n        \n        -- Permissões de Execução\n        'can_change_status', (\n            is_admin_safe() OR \n            (\n                (os_record.assigned_to = user_id OR os_record.created_by = user_id)\n                AND os_record.status NOT IN ('concluida', 'cancelada')\n            )\n        ),\n        \n        -- Permissões de Alteração Leve\n        'can_change_title', (\n            (is_admin_safe()) OR\n            (os_record.created_by = user_id AND os_record.status = 'pendente')\n        ),\n        'can_change_description', (\n            (is_admin_safe()) OR\n            (os_record.created_by = user_id AND os_record.status = 'pendente')\n        ),\n        'can_change_priority', is_admin_safe(),\n        'can_change_deadline', can_change_deadline(p_os_id, user_id),\n        \n        -- Permissões Estruturais\n        'can_convert_to_complex', can_convert_to_complex(p_os_id, user_id),\n        'can_add_micro_tasks', can_add_micro_tasks(p_os_id, user_id),\n        'can_remove_micro_tasks', is_admin_safe(),\n        'can_reassign', is_admin_safe(),\n        'can_delete', can_delete_os(p_os_id, user_id)\n    ) INTO result;\n    \n    RETURN result;\nEND;\n$$ LANGUAGE plpgsql;\n\nCOMMENT ON FUNCTION get_os_permissions IS 'ETAPA 4: RPC que calcula todas permissões para uma OS. Retorna JSON com flags booleanas para uso no frontend (hooks React). SECURITY DEFINER para usar funções helper';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1020: RPC get_os_permissions criado (ETAPA 4)';\nEND $$;\n\nCOMMIT;"}	1020_criar_rpc_get_permissions	redestvgmulti@gmail.com	\N	\N
20260107120710	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1022: Triggers para Eventos de Governança\n-- Data: 2026-01-07\n-- Descrição: Captura alterações em prazo, título e responsável\n--            Garante auditoria mesmo em updates diretos\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\nCREATE OR REPLACE FUNCTION registrar_alteracoes_tarefa()\nRETURNS TRIGGER\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_user_id UUID;\n    v_dados JSONB;\nBEGIN\n    -- Tentar identificar o usuário (falha graciosa se não houver sessão)\n    BEGIN\n        v_user_id := auth.uid();\n    EXCEPTION WHEN OTHERS THEN\n        v_user_id := NULL;\n    END;\n\n    -- 1. Prazo Alterado\n    IF (OLD.deadline IS DISTINCT FROM NEW.deadline) THEN\n        INSERT INTO os_eventos (os_id, tipo, autor_id, metadata)\n        VALUES (\n            NEW.id, \n            'prazo_alterado', \n            v_user_id,\n            jsonb_build_object(\n                'de', OLD.deadline,\n                'para', NEW.deadline,\n                'origem', 'trigger'\n            )\n        );\n    END IF;\n\n    -- 2. Título Alterado\n    IF (OLD.titulo IS DISTINCT FROM NEW.titulo) THEN\n        INSERT INTO os_eventos (os_id, tipo, autor_id, metadata)\n        VALUES (\n            NEW.id, \n            'titulo_alterado', \n            v_user_id,\n            jsonb_build_object(\n                'de', OLD.titulo,\n                'para', NEW.titulo,\n                'origem', 'trigger'\n            )\n        );\n    END IF;\n\n    -- 3. Responsável Reatribuído\n    IF (OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) THEN\n        INSERT INTO os_eventos (os_id, tipo, autor_id, metadata)\n        VALUES (\n            NEW.id, \n            'responsavel_reatribuido', \n            v_user_id,\n            jsonb_build_object(\n                'de', OLD.assigned_to,\n                'para', NEW.assigned_to,\n                'origem', 'trigger'\n            )\n        );\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Trigger unificado para alterações de dados\nCREATE TRIGGER trigger_dados_alterados\nAFTER UPDATE ON tarefas\nFOR EACH ROW\nWHEN (\n    OLD.deadline IS DISTINCT FROM NEW.deadline OR\n    OLD.titulo IS DISTINCT FROM NEW.titulo OR\n    OLD.assigned_to IS DISTINCT FROM NEW.assigned_to\n)\nEXECUTE FUNCTION registrar_alteracoes_tarefa();\n\n-- Comentário\nCOMMENT ON TRIGGER trigger_dados_alterados ON tarefas IS 'ETAPA 4: Captura alterações de governança (prazo, título, responsável) e registra em os_eventos';\n\n-- Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1022: Triggers de governança criados';\nEND $$;\n\nCOMMIT;"}	1022_triggers_governanca	redestvgmulti@gmail.com	\N	\N
20260107130955	{"-- Migration: Dashboard Executivo (Etapa 5)\n-- Objetivo: Criar View agregadora e RPC segura para o dashboard gerencial\n\n-- 1. View Agregada (os_dashboard_summary)\nCREATE OR REPLACE VIEW os_dashboard_summary AS\nSELECT\n  t.empresa_id,\n  COUNT(*) FILTER (WHERE t.status = 'pendente') AS pendentes,\n  COUNT(*) FILTER (WHERE t.status = 'em_progresso') AS em_execucao, -- Ajustado para enum correto\n  COUNT(*) FILTER (\n    WHERE t.deadline < now()\n    AND t.status NOT IN ('concluida', 'cancelada')\n  ) AS atrasadas,\n  COUNT(*) FILTER (\n    WHERE t.status = 'concluida'\n    AND t.updated_at >= now() - interval '7 days' -- Usando updated_at como proxy de conclusão recente\n  ) AS concluidas_7d\nFROM tarefas t\nWHERE t.deleted_at IS NULL\nGROUP BY t.empresa_id;\n\n-- 2. RPC get_dashboard_data\nCREATE OR REPLACE FUNCTION get_dashboard_data(p_empresa_id UUID)\nRETURNS JSON\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_user_role TEXT;\n    v_user_empresa_id UUID;\n    v_summary JSON;\n    v_atrasadas JSON;\n    v_risco JSON;\n    v_produtividade JSON;\nBEGIN\n    -- 1. Validar Autenticação e Role\n    SELECT ((auth.jwt() ->> 'app_metadata')::jsonb ->> 'role') INTO v_user_role;\n    \n    IF v_user_role = 'staff' THEN\n        RAISE EXCEPTION 'Acesso negado: Perfil Staff não tem acesso ao Dashboard Executivo.';\n    END IF;\n    \n    -- 2. Obter Summary (KPIs) da View\n    SELECT json_build_object(\n        'pendentes', COALESCE(pendentes, 0),\n        'em_execucao', COALESCE(em_execucao, 0),\n        'atrasadas', COALESCE(atrasadas, 0),\n        'concluidas_7d', COALESCE(concluidas_7d, 0)\n    )\n    INTO v_summary\n    FROM os_dashboard_summary\n    WHERE empresa_id = p_empresa_id;\n    \n    IF v_summary IS NULL THEN\n        v_summary := json_build_object(\n            'pendentes', 0,\n            'em_execucao', 0,\n            'atrasadas', 0,\n            'concluidas_7d', 0\n        );\n    END IF;\n\n    -- 3. Lista: Atrasadas (Deadline < Agora)\n    SELECT json_agg(t)\n    INTO v_atrasadas\n    FROM (\n        SELECT \n            id, \n            titulo, \n            responsavel_id,\n            (SELECT nome FROM profiles WHERE id = tarefas.responsavel_id) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline < now()\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY prioridade DESC, deadline ASC\n        LIMIT 20\n    ) t;\n\n    -- 4. Lista: Em Risco (Agora <= Deadline <= Agora + 48h)\n    SELECT json_agg(r)\n    INTO v_risco\n    FROM (\n        SELECT \n            id, \n            titulo, \n            responsavel_id,\n            (SELECT nome FROM profiles WHERE id = tarefas.responsavel_id) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline >= now()\n          AND deadline <= (now() + interval '48 hours')\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY deadline ASC\n        LIMIT 20\n    ) r;\n\n    -- 5. Produtividade (Neutro - Alfabetica)\n    SELECT json_agg(p)\n    INTO v_produtividade\n    FROM (\n        SELECT \n            prof.nome as responsavel,\n            COUNT(*) FILTER (WHERE t.status IN ('pendente', 'em_progresso')) as ativas,\n            COUNT(*) FILTER (WHERE t.status = 'concluida' AND t.updated_at >= now() - interval '7 days') as concluidas_7d\n        FROM profiles prof\n        JOIN tarefas t ON t.responsavel_id = prof.id\n        WHERE t.empresa_id = p_empresa_id\n          AND t.deleted_at IS NULL\n          AND prof.role = 'staff'\n        GROUP BY prof.id, prof.nome\n        ORDER BY prof.nome ASC\n    ) p;\n\n    RETURN json_build_object(\n        'summary', v_summary,\n        'lists', json_build_object(\n            'atrasadas', COALESCE(v_atrasadas, '[]'::json),\n            'risco', COALESCE(v_risco, '[]'::json)\n        ),\n        'productivity', COALESCE(v_produtividade, '[]'::json)\n    );\nEND;\n$$;"}	dashboard_executivo	redestvgmulti@gmail.com	\N	\N
20260107131602	{"-- Migration: Dashboard Executivo (Etapa 5) - FIX\n-- Objetivo: Criar View agregadora e RPC segura para o dashboard gerencial\n-- CORREÇÃO: Usar tabela 'profissionais' ao invés de 'profiles'\n\n-- 1. View Agregada (os_dashboard_summary)\nCREATE OR REPLACE VIEW os_dashboard_summary AS\nSELECT\n  t.empresa_id,\n  COUNT(*) FILTER (WHERE t.status = 'pendente') AS pendentes,\n  COUNT(*) FILTER (WHERE t.status = 'em_progresso') AS em_execucao,\n  COUNT(*) FILTER (\n    WHERE t.deadline < now()\n    AND t.status NOT IN ('concluida', 'cancelada')\n  ) AS atrasadas,\n  COUNT(*) FILTER (\n    WHERE t.status = 'concluida'\n    AND t.updated_at >= now() - interval '7 days'\n  ) AS concluidas_7d\nFROM tarefas t\nWHERE t.deleted_at IS NULL\nGROUP BY t.empresa_id;\n\n-- 2. RPC get_dashboard_data\nCREATE OR REPLACE FUNCTION get_dashboard_data(p_empresa_id UUID)\nRETURNS JSON\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_user_role TEXT;\n    v_user_empresa_id UUID;\n    v_summary JSON;\n    v_atrasadas JSON;\n    v_risco JSON;\n    v_produtividade JSON;\nBEGIN\n    -- 1. Validar Autenticação e Role\n    SELECT ((auth.jwt() ->> 'app_metadata')::jsonb ->> 'role') INTO v_user_role;\n    \n    IF v_user_role = 'staff' THEN\n        RAISE EXCEPTION 'Acesso negado: Perfil Staff não tem acesso ao Dashboard Executivo.';\n    END IF;\n    \n    -- 2. Obter Summary (KPIs) da View\n    SELECT json_build_object(\n        'pendentes', COALESCE(pendentes, 0),\n        'em_execucao', COALESCE(em_execucao, 0),\n        'atrasadas', COALESCE(atrasadas, 0),\n        'concluidas_7d', COALESCE(concluidas_7d, 0)\n    )\n    INTO v_summary\n    FROM os_dashboard_summary\n    WHERE empresa_id = p_empresa_id;\n    \n    IF v_summary IS NULL THEN\n        v_summary := json_build_object(\n            'pendentes', 0,\n            'em_execucao', 0,\n            'atrasadas', 0,\n            'concluidas_7d', 0\n        );\n    END IF;\n\n    -- 3. Lista: Atrasadas (Deadline < Agora)\n    SELECT json_agg(t)\n    INTO v_atrasadas\n    FROM (\n        SELECT \n            id, \n            titulo, \n            responsavel_id,\n            (SELECT nome FROM profissionais WHERE id = tarefas.responsavel_id) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline < now()\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY prioridade DESC, deadline ASC\n        LIMIT 20\n    ) t;\n\n    -- 4. Lista: Em Risco (Agora <= Deadline <= Agora + 48h)\n    SELECT json_agg(r)\n    INTO v_risco\n    FROM (\n        SELECT \n            id, \n            titulo, \n            responsavel_id,\n            (SELECT nome FROM profissionais WHERE id = tarefas.responsavel_id) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline >= now()\n          AND deadline <= (now() + interval '48 hours')\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY deadline ASC\n        LIMIT 20\n    ) r;\n\n    -- 5. Produtividade (Neutro - Alfabetica)\n    SELECT json_agg(p)\n    INTO v_produtividade\n    FROM (\n        SELECT \n            prof.nome as responsavel,\n            COUNT(*) FILTER (WHERE t.status IN ('pendente', 'em_progresso')) as ativas,\n            COUNT(*) FILTER (WHERE t.status = 'concluida' AND t.updated_at >= now() - interval '7 days') as concluidas_7d\n        FROM profissionais prof\n        JOIN tarefas t ON t.responsavel_id = prof.id\n        WHERE t.empresa_id = p_empresa_id\n          AND t.deleted_at IS NULL\n          AND prof.role = 'profissional'\n        GROUP BY prof.id, prof.nome\n        ORDER BY prof.nome ASC\n    ) p;\n\n    RETURN json_build_object(\n        'summary', v_summary,\n        'lists', json_build_object(\n            'atrasadas', COALESCE(v_atrasadas, '[]'::json),\n            'risco', COALESCE(v_risco, '[]'::json)\n        ),\n        'productivity', COALESCE(v_produtividade, '[]'::json)\n    );\nEND;\n$$;"}	dashboard_executivo_fix_profissionais	redestvgmulti@gmail.com	\N	\N
