_id\n          AND deadline < now()\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY prioridade DESC, deadline ASC\n        LIMIT 20\n    ) t;\n\n    -- 4. Lista: Em Risco (Agora <= Deadline <= Agora + 48h)\n    SELECT json_agg(r)\n    INTO v_risco\n    FROM (\n        SELECT \n            id, \n            titulo, \n            responsavel_id,\n            (SELECT nome FROM profissionais WHERE id = tarefas.responsavel_id) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline >= now()\n          AND deadline <= (now() + interval '48 hours')\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY deadline ASC\n        LIMIT 20\n    ) r;\n\n    -- 5. Produtividade (Neutro - Alfabetica)\n    SELECT json_agg(p)\n    INTO v_produtividade\n    FROM (\n        SELECT \n            prof.nome as responsavel,\n            COUNT(*) FILTER (WHERE t.status IN ('pendente', 'em_progresso')) as ativas,\n            COUNT(*) FILTER (WHERE t.status = 'concluida' AND t.updated_at >= now() - interval '7 days') as concluidas_7d\n        FROM profissionais prof\n        JOIN tarefas t ON t.responsavel_id = prof.id\n        WHERE t.empresa_id = p_empresa_id\n          AND t.deleted_at IS NULL\n          AND prof.role = 'profissional'\n        GROUP BY prof.id, prof.nome\n        ORDER BY prof.nome ASC\n    ) p;\n\n    RETURN json_build_object(\n        'summary', v_summary,\n        'lists', json_build_object(\n            'atrasadas', COALESCE(v_atrasadas, '[]'::json),\n            'risco', COALESCE(v_risco, '[]'::json)\n        ),\n        'productivity', COALESCE(v_produtividade, '[]'::json)\n    );\nEND;\n$$;"}	dashboard_executivo_security_fix	redestvgmulti@gmail.com	\N	\N
20260107132458	{"-- Migration: Dashboard Executivo Column Fixes\n-- Corrigindo responsavel_id -> assigned_to\n\nCREATE OR REPLACE FUNCTION get_dashboard_data(p_empresa_id UUID)\nRETURNS JSON\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_user_role TEXT;\n    v_summary JSON;\n    v_atrasadas JSON;\n    v_risco JSON;\n    v_produtividade JSON;\nBEGIN\n    -- 1. Validar Autenticação e Role\n    SELECT ((auth.jwt() ->> 'app_metadata')::jsonb ->> 'role') INTO v_user_role;\n    \n    IF v_user_role = 'staff' THEN\n        RAISE EXCEPTION 'Acesso negado: Perfil Staff não tem acesso ao Dashboard Executivo.';\n    END IF;\n\n    -- 1.1 Validar Vínculo com a Empresa (Multi-Tenant Security)\n    IF NOT EXISTS (\n        SELECT 1 \n        FROM empresa_profissionais \n        WHERE profissional_id = auth.uid() \n          AND empresa_id = p_empresa_id\n    ) THEN\n        RAISE EXCEPTION 'Acesso negado: Usuário não vinculado a esta empresa.';\n    END IF;\n    \n    -- 2. Obter Summary (KPIs) da View\n    SELECT json_build_object(\n        'pendentes', COALESCE(pendentes, 0),\n        'em_execucao', COALESCE(em_execucao, 0),\n        'atrasadas', COALESCE(atrasadas, 0),\n        'concluidas_7d', COALESCE(concluidas_7d, 0)\n    )\n    INTO v_summary\n    FROM os_dashboard_summary\n    WHERE empresa_id = p_empresa_id;\n    \n    IF v_summary IS NULL THEN\n        v_summary := json_build_object(\n            'pendentes', 0,\n            'em_execucao', 0,\n            'atrasadas', 0,\n            'concluidas_7d', 0\n        );\n    END IF;\n\n    -- 3. Lista: Atrasadas (Deadline < Agora)\n    SELECT json_agg(t)\n    INTO v_atrasadas\n    FROM (\n        SELECT \n            id, \n            titulo, \n            assigned_to as responsavel_id,\n            (SELECT nome FROM profissionais WHERE id = tarefas.assigned_to) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline < now()\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY prioridade DESC, deadline ASC\n        LIMIT 20\n    ) t;\n\n    -- 4. Lista: Em Risco (Agora <= Deadline <= Agora + 48h)\n    SELECT json_agg(r)\n    INTO v_risco\n    FROM (\n        SELECT \n            id, \n            titulo, \n            assigned_to as responsavel_id,\n            (SELECT nome FROM profissionais WHERE id = tarefas.assigned_to) as responsavel_nome,\n            deadline,\n            prioridade,\n            status\n        FROM tarefas\n        WHERE empresa_id = p_empresa_id\n          AND deadline >= now()\n          AND deadline <= (now() + interval '48 hours')\n          AND status NOT IN ('concluida', 'cancelada')\n          AND deleted_at IS NULL\n        ORDER BY deadline ASC\n        LIMIT 20\n    ) r;\n\n    -- 5. Produtividade (Neutro - Alfabetica)\n    SELECT json_agg(p)\n    INTO v_produtividade\n    FROM (\n        SELECT \n            prof.nome as responsavel,\n            COUNT(*) FILTER (WHERE t.status IN ('pendente', 'em_progresso')) as ativas,\n            COUNT(*) FILTER (WHERE t.status = 'concluida' AND t.updated_at >= now() - interval '7 days') as concluidas_7d\n        FROM profissionais prof\n        JOIN tarefas t ON t.assigned_to = prof.id\n        WHERE t.empresa_id = p_empresa_id\n          AND t.deleted_at IS NULL\n          AND prof.role = 'profissional'\n        GROUP BY prof.id, prof.nome\n        ORDER BY prof.nome ASC\n    ) p;\n\n    RETURN json_build_object(\n        'summary', v_summary,\n        'lists', json_build_object(\n            'atrasadas', COALESCE(v_atrasadas, '[]'::json),\n            'risco', COALESCE(v_risco, '[]'::json)\n        ),\n        'productivity', COALESCE(v_produtividade, '[]'::json)\n    );\nEND;\n$$;"}	dashboard_executivo_column_fixes	redestvgmulti@gmail.com	\N	\N
20260107140949	{"-- 1. View for Operational Summary\nCREATE OR REPLACE VIEW os_dashboard_summary AS\nSELECT\n    t.id,\n    t.empresa_id,\n    t.titulo,\n    t.status,\n    t.priority,\n    t.deadline,\n    t.assigned_to,\n    t.created_at,\n    CASE \n        WHEN t.deadline < NOW() AND t.status NOT IN ('completed', 'concluida', 'concluído', 'done') THEN true \n        ELSE false \n    END as is_overdue\nFROM\n    tarefas t;\n\n-- 2. RPC for Consolidated Dashboard Data\nCREATE OR REPLACE FUNCTION get_dashboard_data(p_empresa_id UUID)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_user_id UUID := auth.uid();\n    v_result JSONB;\nBEGIN\n    -- 1. Security Check: Validate User-Company Link\n    IF NOT EXISTS (\n        SELECT 1 FROM empresa_profissionais\n        WHERE profissional_id = v_user_id AND empresa_id = p_empresa_id\n    ) THEN\n        RAISE EXCEPTION 'Acesso negado: Usuário não vinculado a esta empresa.';\n    END IF;\n\n    -- 2. Build Response\n    SELECT jsonb_build_object(\n        'summary', (\n            SELECT jsonb_build_object(\n                'total', COUNT(*),\n                'active', COUNT(*) FILTER (WHERE status IN ('pending', 'in_progress', 'pendente', 'em_andamento', 'todo', 'doing')),\n                'completed', COUNT(*) FILTER (WHERE status IN ('completed', 'concluida', 'concluído', 'done')),\n                'overdue', COUNT(*) FILTER (WHERE deadline < NOW() AND status NOT IN ('completed', 'concluida', 'concluído', 'done'))\n            )\n            FROM tarefas t\n            WHERE t.empresa_id = p_empresa_id\n        ),\n        'recent_tasks', COALESCE((\n            SELECT jsonb_agg(sub)\n            FROM (\n                SELECT id, titulo, status, priority, deadline, assigned_to, created_at\n                FROM tarefas\n                WHERE empresa_id = p_empresa_id\n                ORDER BY created_at DESC\n                LIMIT 5\n            ) sub\n        ), '[]'::jsonb),\n        'tasks_by_status', (\n             SELECT jsonb_agg(stats)\n             FROM (\n                SELECT status, COUNT(*) as count\n                FROM tarefas\n                WHERE empresa_id = p_empresa_id\n                GROUP BY status\n             ) stats\n        ),\n        'productivity', COALESCE((\n            SELECT jsonb_agg(prod)\n             FROM (\n                SELECT \n                    p.id,\n                    p.nome,\n                    COUNT(t.id) FILTER (WHERE t.status IN ('in_progress', 'em_andamento', 'doing')) as active_count,\n                    COUNT(t.id) FILTER (WHERE t.status IN ('completed', 'concluida', 'done')) as completed_count\n                FROM profissionais p\n                JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n                LEFT JOIN tarefas t ON t.assigned_to = p.id AND t.empresa_id = p_empresa_id\n                WHERE ep.empresa_id = p_empresa_id\n                GROUP BY p.id, p.nome\n                ORDER BY p.nome ASC\n             ) prod\n        ), '[]'::jsonb)\n    ) INTO v_result;\n\n    RETURN v_result;\nEND;\n$$;"}	dashboard_executivo_rpc_view	redestvgmulti@gmail.com	\N	\N
20260107195820	{"ALTER TABLE empresa_profissionais \nADD COLUMN IF NOT EXISTS ativo BOOLEAN DEFAULT true;\n\nUPDATE empresa_profissionais SET ativo = true WHERE ativo IS NULL;\n\nCREATE INDEX IF NOT EXISTS idx_empresa_profissionais_ativo ON empresa_profissionais(ativo);\n"}	fix_empresa_profissionais_ativo	redestvgmulti@gmail.com	\N	\N
20260107200101	{"ALTER TABLE empresas \nADD COLUMN IF NOT EXISTS slug VARCHAR(255);\n\nALTER TABLE empresas \nADD COLUMN IF NOT EXISTS logo_url TEXT;\n\nUPDATE empresas \nSET slug = lower(regexp_replace(nome, '[^a-zA-Z0-9]+', '-', 'g'))\nWHERE slug IS NULL;\n\nWITH numbered_empresas AS (\n  SELECT \n    id, \n    slug,\n    ROW_NUMBER() OVER (PARTITION BY slug ORDER BY created_at) as rn\n  FROM empresas\n  WHERE slug IS NOT NULL\n)\nUPDATE empresas e\nSET slug = CASE \n  WHEN ne.rn > 1 THEN e.slug || '-' || ne.rn::text\n  ELSE e.slug\nEND\nFROM numbered_empresas ne\nWHERE e.id = ne.id AND ne.rn > 1;\n\nALTER TABLE empresas \nALTER COLUMN slug SET NOT NULL;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_constraint \n    WHERE conname = 'empresas_slug_unique'\n  ) THEN\n    ALTER TABLE empresas ADD CONSTRAINT empresas_slug_unique UNIQUE (slug);\n  END IF;\nEND $$;\n\nCREATE INDEX IF NOT EXISTS idx_empresas_slug ON empresas(slug);\n"}	fix_empresas_missing_columns_v2	redestvgmulti@gmail.com	\N	\N
20260110143235	{"-- Migration: Task Attachments System\n-- Description: Add support for file uploads to tasks with secure multi-tenant access\n-- Author: System\n-- Date: 2026-01-10\n\n-- Enable UUID extension if not already enabled\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\";\n\n-- Create task_attachments table\nCREATE TABLE IF NOT EXISTS task_attachments (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  tarefa_id UUID NOT NULL REFERENCES tarefas(id) ON DELETE CASCADE,\n  empresa_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE,\n  uploaded_by UUID NOT NULL REFERENCES profissionais(id),\n  \n  -- File metadata\n  filename TEXT NOT NULL, -- UUID-based filename in storage\n  original_filename TEXT NOT NULL, -- User's original filename\n  file_size INTEGER NOT NULL, -- Size in bytes\n  mime_type TEXT NOT NULL,\n  storage_path TEXT NOT NULL, -- Full path: {empresa_id}/{tarefa_id}/{uuid}_{filename}\n  \n  -- Timestamps\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  \n  -- Constraints\n  CONSTRAINT task_attachments_file_size_check CHECK (file_size > 0 AND file_size <= 10485760), -- Max 10MB\n  CONSTRAINT task_attachments_filename_not_empty CHECK (length(filename) > 0),\n  CONSTRAINT task_attachments_original_filename_not_empty CHECK (length(original_filename) > 0)\n);\n\n-- Indexes for performance\nCREATE INDEX idx_task_attachments_tarefa ON task_attachments(tarefa_id);\nCREATE INDEX idx_task_attachments_empresa ON task_attachments(empresa_id);\nCREATE INDEX idx_task_attachments_uploaded_by ON task_attachments(uploaded_by);\nCREATE INDEX idx_task_attachments_created_at ON task_attachments(created_at DESC);\n\n-- Comments\nCOMMENT ON TABLE task_attachments IS 'Stores metadata for files attached to tasks';\nCOMMENT ON COLUMN task_attachments.filename IS 'UUID-based filename stored in Supabase Storage';\nCOMMENT ON COLUMN task_attachments.original_filename IS 'Original filename uploaded by user';\nCOMMENT ON COLUMN task_attachments.storage_path IS 'Full path in storage bucket: {empresa_id}/{tarefa_id}/{uuid}_{filename}';\nCOMMENT ON COLUMN task_attachments.file_size IS 'File size in bytes (max 10MB)';\n\n-- Enable RLS\nALTER TABLE task_attachments ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\n\n-- SELECT: Staff can view attachments from their company's tasks\nCREATE POLICY \\"Staff can view company task attachments\\"\nON task_attachments FOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM empresa_profissionais ep\n    WHERE ep.profissional_id = auth.uid()\n    AND ep.empresa_id = task_attachments.empresa_id\n    AND ep.ativo = true\n  )\n);\n\n-- INSERT: Users can upload to their company's tasks\nCREATE POLICY \\"Users can upload to company tasks\\"\nON task_attachments FOR INSERT\nWITH CHECK (\n  uploaded_by = auth.uid() AND\n  EXISTS (\n    SELECT 1 FROM empresa_profissionais ep\n    WHERE ep.profissional_id = auth.uid()\n    AND ep.empresa_id = task_attachments.empresa_id\n    AND ep.ativo = true\n  )\n);\n\n-- DELETE: Users can delete their own uploads OR admins can delete any from their company\nCREATE POLICY \\"Users can delete own uploads or admins can delete company uploads\\"\nON task_attachments FOR DELETE\nUSING (\n  uploaded_by = auth.uid() OR\n  EXISTS (\n    SELECT 1 FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND ep.empresa_id = task_attachments.empresa_id\n    AND ep.ativo = true\n    AND p.role = 'admin'\n  )\n);\n\n-- Grant permissions\nGRANT SELECT, INSERT, DELETE ON task_attachments TO authenticated;\n"}	033_task_attachments	redestvgmulti@gmail.com	\N	\N
20260110143237	{"-- Migration: Create Storage Bucket for Task Attachments\n-- Description: Creates the 'task-attachments' bucket and sets up RLS policies\n-- Author: System\n-- Date: 2026-01-10\n\n-- Create the storage bucket if it doesn't exist\nINSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nVALUES (\n  'task-attachments',\n  'task-attachments',\n  false,\n  10485760, -- 10MB limit\n  ARRAY[\n    'application/pdf',\n    'image/jpeg',\n    'image/png',\n    'application/msword',\n    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',\n    'application/vnd.ms-excel',\n    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',\n    'application/zip',\n    'application/x-zip-compressed'\n  ]\n) ON CONFLICT (id) DO UPDATE SET\n  file_size_limit = EXCLUDED.file_size_limit,\n  allowed_mime_types = EXCLUDED.allowed_mime_types;\n\n-- RLS Policies for Storage\n\n-- Remove existing policies to avoid conflicts if re-running\nDROP POLICY IF EXISTS \\"Company members can view attachments\\" ON storage.objects;\nDROP POLICY IF EXISTS \\"Users can upload to company folder\\" ON storage.objects;\nDROP POLICY IF EXISTS \\"Users can delete own uploads\\" ON storage.objects;\nDROP POLICY IF EXISTS \\"Admins can delete company uploads\\" ON storage.objects;\n\n-- Policy: Authenticated users can read files from their company's folder or own uploads\n-- Folder structure: {empresa_id}/{tarefa_id}/{filename}\nCREATE POLICY \\"Company members can view attachments\\"\nON storage.objects FOR SELECT\nUSING (\n  bucket_id = 'task-attachments' AND\n  auth.role() = 'authenticated' AND\n  (\n    -- Check if user belongs to the company in the path\n    EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = auth.uid()\n      AND ep.empresa_id::text = (storage.foldername(name))[1]\n      AND ep.ativo = true\n    )\n  )\n);\n\n-- Policy: Users can upload to their company's folder in the bucket\nCREATE POLICY \\"Users can upload to company folder\\"\nON storage.objects FOR INSERT\nWITH CHECK (\n  bucket_id = 'task-attachments' AND\n  auth.role() = 'authenticated' AND\n  (\n    -- Check if user belongs to the company in the path\n    EXISTS (\n      SELECT 1 FROM empresa_profissionais ep\n      WHERE ep.profissional_id = auth.uid()\n      AND ep.empresa_id::text = (storage.foldername(name))[1]\n      AND ep.ativo = true\n    )\n  )\n);\n\n-- Policy: Users can delete their own uploads\nCREATE POLICY \\"Users can delete own uploads\\"\nON storage.objects FOR DELETE\nUSING (\n  bucket_id = 'task-attachments' AND\n  auth.uid() = owner\n);\n\n-- Policy: Admins can delete uploads in their company\nCREATE POLICY \\"Admins can delete company uploads\\"\nON storage.objects FOR DELETE\nUSING (\n  bucket_id = 'task-attachments' AND\n  auth.role() = 'authenticated' AND\n  EXISTS (\n    SELECT 1 FROM empresa_profissionais ep\n    JOIN profissionais p ON p.id = ep.profissional_id\n    WHERE ep.profissional_id = auth.uid()\n    AND ep.empresa_id::text = (storage.foldername(name))[1]\n    AND p.role = 'admin'\n  )\n);\n"}	034_storage_bucket	redestvgmulti@gmail.com	\N	\N
20260112105408	{"-- HOTFIX PRODUÇÃO: Adicionar colunas SLA (PRODUCTION-SAFE)\n-- CRÍTICO: NÃO altera dados existentes, NÃO usa NOT NULL\n\nDO $$\nBEGIN\n  -- 1. Adicionar deadline_at SE NÃO EXISTIR\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns\n    WHERE table_schema = 'public'\n    AND table_name = 'tarefas_itens'\n    AND column_name = 'deadline_at'\n  ) THEN\n    ALTER TABLE tarefas_itens\n    ADD COLUMN deadline_at TIMESTAMPTZ NULL;\n    \n    RAISE NOTICE 'Coluna deadline_at adicionada (NULL, sem default)';\n  ELSE\n    RAISE NOTICE 'Coluna deadline_at já existe';\n  END IF;\n\n  -- 2. Adicionar started_at SE NÃO EXISTIR\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns\n    WHERE table_schema = 'public'\n    AND table_name = 'tarefas_itens'\n    AND column_name = 'started_at'\n  ) THEN\n    ALTER TABLE tarefas_itens\n    ADD COLUMN started_at TIMESTAMPTZ NULL;\n    \n    RAISE NOTICE 'Coluna started_at adicionada';\n  ELSE\n    RAISE NOTICE 'Coluna started_at já existe';\n  END IF;\n\n  -- 3. Adicionar finished_at SE NÃO EXISTIR\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns\n    WHERE table_schema = 'public'\n    AND table_name = 'tarefas_itens'\n    AND column_name = 'finished_at'\n  ) THEN\n    ALTER TABLE tarefas_itens\n    ADD COLUMN finished_at TIMESTAMPTZ NULL;\n    \n    RAISE NOTICE 'Coluna finished_at adicionada';\n  ELSE\n    RAISE NOTICE 'Coluna finished_at já existe';\n  END IF;\n\n  -- 4. Criar índice SE NÃO EXISTIR\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_indexes\n    WHERE schemaname = 'public'\n    AND tablename = 'tarefas_itens'\n    AND indexname = 'idx_tarefas_itens_deadline'\n  ) THEN\n    CREATE INDEX idx_tarefas_itens_deadline \n    ON tarefas_itens(deadline_at)\n    WHERE deadline_at IS NOT NULL;\n    \n    RAISE NOTICE 'Índice idx_tarefas_itens_deadline criado';\n  ELSE\n    RAISE NOTICE 'Índice idx_tarefas_itens_deadline já existe';\n  END IF;\n\n  RAISE NOTICE 'HOTFIX PRODUCTION-SAFE CONCLUÍDO - Colunas adicionadas como NULL';\nEND $$;"}	hotfix_sla_columns_safe	redestvgmulti@gmail.com	\N	\N
20260112105433	{"-- HOTFIX PRODUÇÃO: Remover constraint perigoso (PRODUCTION-SAFE)\n-- CRÍTICO: Elimina risco de deadlock, NÃO altera dados\n\n-- 1. Remover constraint arriscado (causa deadlock)\nALTER TABLE tarefas_itens\nDROP CONSTRAINT IF EXISTS check_profissional_empresa;\n\n-- 2. Criar índice otimizado para acelerar validações\nCREATE INDEX IF NOT EXISTS idx_empresa_profissionais_lookup\nON empresa_profissionais(profissional_id, empresa_id)\nWHERE ativo = true;\n\n-- 3. Criar função de validação SAFE\nCREATE OR REPLACE FUNCTION validar_profissional_empresa()\nRETURNS TRIGGER AS $$\nDECLARE\n  v_empresa_id UUID;\n  v_vinculo_existe BOOLEAN;\nBEGIN\n  -- Ignorar se tarefa não tem empresa (NULL é válido)\n  SELECT empresa_id INTO v_empresa_id\n  FROM tarefas\n  WHERE id = NEW.tarefa_id;\n\n  IF v_empresa_id IS NULL THEN\n    RETURN NEW;\n  END IF;\n\n  -- Verificar vínculo ativo\n  SELECT EXISTS (\n    SELECT 1\n    FROM empresa_profissionais\n    WHERE profissional_id = NEW.profissional_id\n    AND empresa_id = v_empresa_id\n    AND ativo = true\n  ) INTO v_vinculo_existe;\n\n  -- Rejeitar se não houver vínculo\n  IF NOT v_vinculo_existe THEN\n    RAISE EXCEPTION 'Profissional não está vinculado à empresa';\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql STABLE;\n\n-- 4. Criar trigger (só valida novos registros)\nDROP TRIGGER IF EXISTS trigger_validar_prof_empresa ON tarefas_itens;\n\nCREATE TRIGGER trigger_validar_prof_empresa\nBEFORE INSERT OR UPDATE OF profissional_id, tarefa_id\nON tarefas_itens\nFOR EACH ROW\nEXECUTE FUNCTION validar_profissional_empresa();"}	hotfix_remove_constraint_safe	redestvgmulti@gmail.com	\N	\N
20260112135214	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1023: Correction RLS Task Comments (Defensive Trigger)\n-- Date: 2026-01-12\n-- Description: Creates a BEFORE INSERT trigger to ensure author_id matches\n-- auth.uid() preventing RLS violations if frontend/triggers send wrong ID.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Create Defensive Function\nCREATE OR REPLACE FUNCTION fix_comment_author_id()\nRETURNS TRIGGER\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n    -- If user is authenticated\n    IF auth.uid() IS NOT NULL THEN\n        -- Allow admin to impersonate (optional, strictly typically admins also use their own ID)\n        -- But for safety, we enforce auth.uid() for everyone unless logic dictates otherwise.\n        -- Let's check is_admin_safe for exception? NO. \n        -- RLS policy \\"Criar comentário na OS\\" STRICTLY requires author_id = auth.uid().\n        -- So we MUST set it to auth.uid().\n        \n        IF NEW.author_id != auth.uid() THEN\n            NEW.author_id := auth.uid();\n        END IF;\n    END IF;\n    \n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- 2. Create Trigger\nDROP TRIGGER IF EXISTS trg_fix_comment_author_before_insert ON task_comments;\nCREATE TRIGGER trg_fix_comment_author_before_insert\n    BEFORE INSERT ON task_comments\n    FOR EACH ROW\n    EXECUTE FUNCTION fix_comment_author_id();\n\n-- 3. Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1023: Trigger trg_fix_comment_author_before_insert created.';\nEND $$;\n\nCOMMIT;"}	1023_fix_task_comments_rls	redestvgmulti@gmail.com	\N	\N
20260112140130	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1024: Fix Task Comments RLS (Permissive Insert)\n-- Date: 2026-01-12\n-- Description: Allows any authenticated staff member to insert comments.\n--              Replaces restrictiver policies for INSERT action.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Enable RLS (Ensure it's on)\nALTER TABLE task_comments ENABLE ROW LEVEL SECURITY;\n\n-- 2. Drop potential conflicting or restrictive old policies if intended to be replaced\n-- (Dropping \\"Criar comentário na OS\\" from 1010 to avoid confusion, though PostgreSQL policies are OR'ed)\nDROP POLICY IF EXISTS \\"Criar comentário na OS\\" ON task_comments;\nDROP POLICY IF EXISTS \\"Admin can insert comments\\" ON task_comments;\nDROP POLICY IF EXISTS \\"Professionals insert comments on accessible tasks\\" ON task_comments;\n\n-- 3. Create Permissive Policy\nCREATE POLICY \\"Staff can insert comments\\"\nON task_comments\nFOR INSERT\nTO authenticated\nWITH CHECK (\n    -- Any authenticated user can comment\n    auth.uid() IS NOT NULL\n);\n\n-- 4. Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1024: Policy \\"Staff can insert comments\\" created. All auth users can now comment.';\nEND $$;\n\nCOMMIT;"}	1024_fix_task_comments_rls	redestvgmulti@gmail.com	\N	\N
20260112141807	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1025: Fix User Role for Evandro\n-- Date: 2026-01-12\n-- Description: Updates the role of user 'evandro@tvgflow.com' to 'admin'.\n--              This ensures he sees the Admin Dashboard and 'Criar nova tarefa'.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Update the role in profissionais table\n-- Assuming the table uses 'role' column (based on 001_initial_schema.sql)\nUPDATE profissionais\nSET role = 'admin'\nWHERE email = 'evandro@tvgflow.com';\n\n-- Verify update (raise notice)\nDO $$\nDECLARE\n    rows_updated integer;\nBEGIN\n    GET DIAGNOSTICS rows_updated = ROW_COUNT;\n    IF rows_updated > 0 THEN\n        RAISE NOTICE '✅ User evandro@tvgflow.com updated to ADMIN.';\n    ELSE\n        RAISE NOTICE '⚠️ User evandro@tvgflow.com NOT FOUND in professionals table.';\n    END IF;\nEND $$;\n\nCOMMIT;"}	1025_fix_user_role_evandro	redestvgmulti@gmail.com	\N	\N
20260112142424	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1026: Fix Tarefas Update RLS for Admins\n-- Date: 2026-01-12\n-- Description: Explicitly grants Admins permission to UPDATE any task.\n--              Solves issue where Admins cannot complete tasks created by others.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Create Policy: Admins can update all tasks\n-- Using is_admin_safe() to prevent recursion\nCREATE POLICY \\"Admins can update all tasks\\"\nON tarefas FOR UPDATE\nTO authenticated\nUSING (\n    is_admin_safe()\n)\nWITH CHECK (\n    is_admin_safe()\n);\n\n-- 2. Log\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1026: Admin UPDATE policy created for tarefas.';\nEND $$;\n\nCOMMIT;"}	1026_fix_tarefas_update_rls	redestvgmulti@gmail.com	\N	\N
20260112142608	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1027: Adjust User Roles\n-- Date: 2026-01-12\n-- Description: Reverts Evandro to 'profissional' and ensures Administracao is 'admin'.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- 1. Revert Evandro to 'profissional' (Staff)\nUPDATE profissionais\nSET role = 'profissional'\nWHERE email = 'evandro@tvgflow.com';\n\n-- 2. Set Administracao to 'admin'\nUPDATE profissionais\nSET role = 'admin'\nWHERE email = 'adminstracao@tvgflow.com';\n\n-- 3. Log results\nDO $$\nDECLARE\n    evandro_count integer;\n    admin_count integer;\nBEGIN\n    -- Check Evandro update (we can't get ROW_COUNT for specific previous statements easily in a block like this without multiple GET DIAGNOSTICS, so we'll just check state)\n    SELECT COUNT(*) INTO evandro_count FROM profissionais WHERE email = 'evandro@tvgflow.com' AND role = 'profissional';\n    SELECT COUNT(*) INTO admin_count FROM profissionais WHERE email = 'adminstracao@tvgflow.com' AND role = 'admin';\n\n    IF evandro_count > 0 THEN\n        RAISE NOTICE '✅ Evandro reverted to STAFF (profissional).';\n    ELSE\n        RAISE NOTICE '⚠️ Evandro NOT updated or not found.';\n    END IF;\n\n    IF admin_count > 0 THEN\n        RAISE NOTICE '✅ Administracao set to ADMIN.';\n    ELSE\n        RAISE NOTICE '⚠️ Administracao NOT updated or not found. Check if the user exists in the database.';\n    END IF;\nEND $$;\n\nCOMMIT;"}	1027_adjust_user_roles	redestvgmulti@gmail.com	\N	\N
20260112143206	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1028: Fix Global Task Completion RLS\n-- Date: 2026-01-12\n-- Description: Fixes the 'tarefas' UPDATE policy which was too restrictive.\n--              1. Adds check for 'tarefas_micro' (fixes 029 mismatch).\n--              2. Restores access for 'assigned_to' (legacy/simple tasks).\n--              3. Restores access for 'created_by'.\n--              NOTE: Removed check for 'tarefas_itens' as table may not exist/be active.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Drop the restrictive/broken policy from Migration 029\nDROP POLICY IF EXISTS \\"Professionals update only assigned tasks\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Professionals can update accessible tasks\\" ON tarefas; -- Clean up if partially created\n\n-- Create the robust, correct policy\nCREATE POLICY \\"Professionals can update accessible tasks\\"\nON tarefas FOR UPDATE\nTO authenticated\nUSING (\n    -- 1. Admin (Safe Check)\n    is_admin_safe()\n    OR\n    -- 2. Direct Assignment (Legacy/Simple Tasks)\n    assigned_to = auth.uid()\n    OR\n    -- 3. Creator (Can usually edit their own requests)\n    created_by = auth.uid()\n    OR\n    -- 4. Micro-Task Assignment (Complex Tasks) - CORRECT TABLE 'tarefas_micro'\n    EXISTS (\n        SELECT 1 FROM tarefas_micro tm\n        WHERE tm.tarefa_id = tarefas.id\n        AND tm.profissional_id = auth.uid()\n    )\n)\nWITH CHECK (\n    -- Symmetric Check\n    is_admin_safe()\n    OR\n    assigned_to = auth.uid()\n    OR\n    created_by = auth.uid()\n    OR\n    EXISTS (\n        SELECT 1 FROM tarefas_micro tm\n        WHERE tm.tarefa_id = tarefas.id\n        AND tm.profissional_id = auth.uid()\n    )\n);\n\n-- Log success\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1028: Fixed tarefas UPDATE RLS (Added tarefas_micro + Legacy roles)';\nEND $$;\n\nCOMMIT;"}	1028_fix_tarefas_update_rls_all_roles	redestvgmulti@gmail.com	\N	\N
20260112143304	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- Migration 1028: Fix Global Task Completion RLS\n-- Date: 2026-01-12\n-- Description: Fixes the 'tarefas' UPDATE policy which was too restrictive.\n--              1. Adds check for 'tarefas_micro' (fixes 029 mismatch).\n--              2. Restores access for 'assigned_to' (legacy/simple tasks).\n--              3. Restores access for 'created_by'.\n--              NOTE: Removed check for 'tarefas_itens' as table may not exist/be active.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nBEGIN;\n\n-- Drop the restrictive/broken policy from Migration 029\nDROP POLICY IF EXISTS \\"Professionals update only assigned tasks\\" ON tarefas;\nDROP POLICY IF EXISTS \\"Professionals can update accessible tasks\\" ON tarefas; -- Clean up if partially created\n\n-- Create the robust, correct policy\nCREATE POLICY \\"Professionals can update accessible tasks\\"\nON tarefas FOR UPDATE\nTO authenticated\nUSING (\n    -- 1. Admin (Safe Check)\n    is_admin_safe()\n    OR\n    -- 2. Direct Assignment (Legacy/Simple Tasks)\n    assigned_to = auth.uid()\n    OR\n    -- 3. Creator (Can usually edit their own requests)\n    created_by = auth.uid()\n    OR\n    -- 4. Micro-Task Assignment (Complex Tasks) - CORRECT TABLE 'tarefas_micro'\n    EXISTS (\n        SELECT 1 FROM tarefas_micro tm\n        WHERE tm.tarefa_id = tarefas.id\n        AND tm.profissional_id = auth.uid()\n    )\n)\nWITH CHECK (\n    -- Symmetric Check\n    is_admin_safe()\n    OR\n    assigned_to = auth.uid()\n    OR\n    created_by = auth.uid()\n    OR\n    EXISTS (\n        SELECT 1 FROM tarefas_micro tm\n        WHERE tm.tarefa_id = tarefas.id\n        AND tm.profissional_id = auth.uid()\n    )\n);\n\n-- Log success\nDO $$\nBEGIN\n    RAISE NOTICE '✅ Migration 1028: Fixed tarefas UPDATE RLS (Added tarefas_micro + Legacy roles)';\nEND $$;\n\nCOMMIT;"}	1028_fix_tarefas_update_rls_all_roles	redestvgmulti@gmail.com	\N	\N
20260112172010	{"-- Fix profissionais role constraint to include 'staff'\nALTER TABLE profissionais DROP CONSTRAINT IF EXISTS profissionais_role_check;\nALTER TABLE profissionais ADD CONSTRAINT profissionais_role_check \n    CHECK (role IN ('admin', 'profissional', 'super_admin', 'staff'));"}	fix_profissionais_role_constraint	redestvgmulti@gmail.com	\N	\N
20260112172035	{"-- CRITICAL FIX: Correção Imediata de Administração TVG\nDO $$\nDECLARE\n    admin_id UUID;\n    admin_role TEXT;\n    admin_ativo BOOLEAN;\n    tenant_id UUID;\n    tenant_nome TEXT;\n    has_link BOOLEAN;\nBEGIN\n    RAISE NOTICE '========== INICIANDO CORREÇÃO ==========';\n    \n    -- Buscar administracao\n    SELECT id, role, ativo INTO admin_id, admin_role, admin_ativo\n    FROM profissionais\n    WHERE email = 'administracao@tvgflow.com';\n\n    IF admin_id IS NULL THEN\n        RAISE EXCEPTION 'User administracao@tvgflow.com not found';\n    END IF;\n\n    RAISE NOTICE '[1/5] User encontrado: % | Role: % | Ativo: %', \n        admin_id, admin_role, admin_ativo;\n\n    -- Garantir que está ativo\n    IF NOT admin_ativo THEN\n        UPDATE profissionais\n        SET ativo = true\n        WHERE id = admin_id;\n        RAISE NOTICE '[1.5/5] User ativado';\n    END IF;\n\n    -- Garantir que role está como admin\n    IF admin_role != 'admin' THEN\n        UPDATE profissionais\n        SET role = 'admin'\n        WHERE id = admin_id;\n        \n        RAISE NOTICE '[2/5] Role atualizada: % → admin', admin_role;\n    ELSE\n        RAISE NOTICE '[2/5] Role já é admin';\n    END IF;\n\n    -- Buscar empresa TVG (tenant)\n    SELECT id, nome INTO tenant_id, tenant_nome\n    FROM empresas\n    WHERE nome ILIKE '%TVG%'\n      AND empresa_tipo = 'tenant'\n      AND ativo = true\n    LIMIT 1;\n\n    IF tenant_id IS NULL THEN\n        RAISE EXCEPTION 'TVG tenant empresa not found. Cannot proceed.';\n    END IF;\n\n    RAISE NOTICE '[3/5] Tenant TVG encontrado: % (%)', tenant_nome, tenant_id;\n\n    -- Verificar se já tem vínculo ativo\n    SELECT EXISTS (\n        SELECT 1\n        FROM empresa_profissionais ep\n        WHERE ep.profissional_id = admin_id\n          AND ep.empresa_id = tenant_id\n          AND ep.ativo = true\n    ) INTO has_link;\n\n    IF has_link THEN\n        RAISE NOTICE '[4/5] Vínculo já existe e está ativo';\n    ELSE\n        RAISE NOTICE '[4/5] Criando vínculo...';\n        \n        -- Criar vínculo\n        INSERT INTO empresa_profissionais (\n            profissional_id,\n            empresa_id,\n            funcao,\n            ativo,\n            created_at\n        ) VALUES (\n            admin_id,\n            tenant_id,\n            'Administração',\n            true,\n            NOW()\n        )\n        ON CONFLICT DO NOTHING;\n\n        RAISE NOTICE '[4/5] Vínculo criado com sucesso!';\n    END IF;\n    \n    RAISE NOTICE '========== CORREÇÃO CONCLUÍDA ==========';\nEND $$;\n\n-- Downgrade evandro para staff\nUPDATE profissionais\nSET role = 'staff'\nWHERE email = 'evandro@tvgflow.com'\n  AND role != 'staff';\n\n-- Validação final\nDO $$\nDECLARE\n    admin_result RECORD;\nBEGIN\n    RAISE NOTICE '========== VALIDAÇÃO FINAL ==========';\n    \n    FOR admin_result IN\n        SELECT \n            p.email,\n            p.role,\n            p.ativo,\n            COUNT(ep.id) FILTER (WHERE e.empresa_tipo = 'tenant' AND ep.ativo = true) as tenant_links\n        FROM profissionais p\n        LEFT JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n        LEFT JOIN empresas e ON e.id = ep.empresa_id\n        WHERE p.email IN ('administracao@tvgflow.com', 'evandro@tvgflow.com')\n        GROUP BY p.id, p.email, p.role, p.ativo\n    LOOP\n        RAISE NOTICE 'User: % | Role: % | Ativo: % | Tenant Links: %',\n            admin_result.email,\n            admin_result.role,\n            admin_result.ativo,\n            admin_result.tenant_links;\n    END LOOP;\n    \n    RAISE NOTICE '======================================';\nEND $$;"}	fix_administracao_tenant_link_v2	redestvgmulti@gmail.com	\N	\N
20260112172702	{"-- Migration: Tenant Context Integrity Enforcement\n-- This migration ensures that NO admin can exist without a valid tenant link\n\n-- Function: Check if admin has active tenant link\nCREATE OR REPLACE FUNCTION has_active_tenant_link(prof_id UUID)\nRETURNS BOOLEAN AS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM empresa_profissionais ep\n        JOIN empresas e ON e.id = ep.empresa_id\n        WHERE ep.profissional_id = prof_id\n          AND ep.ativo = true\n          AND e.empresa_tipo = 'tenant'\n          AND e.ativo = true\n    );\n$$ LANGUAGE SQL STABLE;\n\n-- Trigger Function: Validate admin has tenant (empresa_profissionais table)\nCREATE OR REPLACE FUNCTION enforce_admin_tenant_link()\nRETURNS TRIGGER AS $$\nDECLARE\n    prof_role TEXT;\n    prof_email TEXT;\n    has_tenant BOOLEAN;\nBEGIN\n    -- Get professional role and email\n    SELECT role, email INTO prof_role, prof_email\n    FROM profissionais\n    WHERE id = COALESCE(NEW.profissional_id, OLD.profissional_id);\n\n    -- Only enforce for admins\n    IF prof_role IS NULL OR prof_role != 'admin' THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    -- On DELETE or UPDATE to ativo=false: Check if removing last tenant link\n    IF (TG_OP = 'DELETE') OR (TG_OP = 'UPDATE' AND NEW.ativo = false AND OLD.ativo = true) THEN\n        -- Count remaining active tenant links AFTER this operation\n        SELECT EXISTS (\n            SELECT 1\n            FROM empresa_profissionais ep\n            JOIN empresas e ON e.id = ep.empresa_id\n            WHERE ep.profissional_id = OLD.profissional_id\n              AND ep.ativo = true\n              AND e.empresa_tipo = 'tenant'\n              AND e.ativo = true\n              AND ep.id != OLD.id  -- Exclude the row being deleted/deactivated\n        ) INTO has_tenant;\n\n        IF NOT has_tenant THEN\n            RAISE EXCEPTION 'TENANT_LINK_REQUIRED: Cannot remove last active tenant link for admin % (%). Admins must have at least one active tenant.',\n                prof_email, OLD.profissional_id\n                USING HINT = 'Deactivate admin role first, or create alternate tenant link before removing this one';\n        END IF;\n    END IF;\n\n    RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Create trigger on empresa_profissionais\nDROP TRIGGER IF EXISTS trg_enforce_admin_tenant_link ON empresa_profissionais;\nCREATE TRIGGER trg_enforce_admin_tenant_link\n    BEFORE UPDATE OR DELETE ON empresa_profissionais\n    FOR EACH ROW\n    EXECUTE FUNCTION enforce_admin_tenant_link();\n\n-- Trigger Function: Validate role promotion requires tenant\nCREATE OR REPLACE FUNCTION enforce_admin_role_requires_tenant()\nRETURNS TRIGGER AS $$\nDECLARE\n    has_tenant BOOLEAN;\nBEGIN\n    -- Only validate when PROMOTING to admin (role change TO admin)\n    IF NEW.role = 'admin' AND (OLD.role IS NULL OR OLD.role != 'admin') THEN\n        \n        -- Check if user has active tenant link\n        SELECT has_active_tenant_link(NEW.id) INTO has_tenant;\n\n        IF NOT has_tenant THEN\n            RAISE EXCEPTION 'TENANT_LINK_REQUIRED: Cannot promote % to admin without active tenant link',\n                NEW.email\n                USING HINT = 'Create active tenant link in empresa_profissionais before promoting to admin role';\n        END IF;\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Create trigger on profissionais\nDROP TRIGGER IF EXISTS trg_enforce_admin_role_requires_tenant ON profissionais;\nCREATE TRIGGER trg_enforce_admin_role_requires_tenant\n    BEFORE INSERT OR UPDATE ON profissionais\n    FOR EACH ROW\n    EXECUTE FUNCTION enforce_admin_role_requires_tenant();\n\n-- Create compliance monitoring view\nCREATE OR REPLACE VIEW vw_admin_tenant_compliance AS\nSELECT \n    p.id,\n    p.email,\n    p.role,\n    p.ativo as profissional_ativo,\n    COUNT(ep.empresa_id) FILTER (\n        WHERE e.empresa_tipo = 'tenant' \n        AND ep.ativo = true \n        AND e.ativo = true\n    ) as tenant_link_count,\n    CASE \n        WHEN p.role = 'admin' AND COUNT(ep.empresa_id) FILTER (\n            WHERE e.empresa_tipo = 'tenant' \n            AND ep.ativo = true \n            AND e.ativo = true\n        ) = 0 THEN 'INVALID'\n        WHEN p.role = 'admin' AND COUNT(ep.empresa_id) FILTER (\n            WHERE e.empresa_tipo = 'tenant' \n            AND ep.ativo = true \n            AND e.ativo = true\n        ) > 0 THEN 'VALID'\n        ELSE 'N/A'\n    END as compliance_status\nFROM profissionais p\nLEFT JOIN empresa_profissionais ep ON ep.profissional_id = p.id\nLEFT JOIN empresas e ON e.id = ep.empresa_id\nWHERE p.role IN ('admin', 'super_admin', 'staff')\n  AND p.ativo = true\nGROUP BY p.id, p.email, p.role, p.ativo\nORDER BY compliance_status DESC, p.email;"}	ensure_admin_tenant_integrity	redestvgmulti@gmail.com	\N	\N
20260112173422	{"-- TEST SUITE: Post-Deployment Verification\nDO $$\nDECLARE\n    invalid_count INTEGER;\n    admin_check RECORD;\n    trigger_exists BOOLEAN;\nBEGIN\n    RAISE NOTICE 'Starting Automated Tests...';\n\n    -- TEST 1: Check Admin Compliance View\n    SELECT COUNT(*) INTO invalid_count\n    FROM vw_admin_tenant_compliance\n    WHERE compliance_status = 'INVALID';\n\n    IF invalid_count > 0 THEN\n        RAISE EXCEPTION 'TEST FAILED: Found % invalid admins in vw_admin_tenant_compliance', invalid_count;\n    ELSE\n        RAISE NOTICE 'TEST PASSED: No invalid admins found.';\n    END IF;\n\n    -- TEST 2: Verify Target Admin (administracao@tvgflow.com)\n    SELECT * INTO admin_check\n    FROM vw_admin_tenant_compliance\n    WHERE email = 'administracao@tvgflow.com';\n\n    IF admin_check IS NULL THEN\n        RAISE EXCEPTION 'TEST FAILED: User administracao@tvgflow.com not found in compliance view. (Maybe not promoted yet?)';\n    END IF;\n\n    IF admin_check.compliance_status != 'VALID' THEN\n        RAISE EXCEPTION 'TEST FAILED: User administracao@tvgflow.com is % (Expected: VALID)', admin_check.compliance_status;\n    ELSE\n        RAISE NOTICE 'TEST PASSED: User administracao@tvgflow.com is VALID.';\n    END IF;\n\n    -- TEST 3: Verify Trigger Existence\n    SELECT EXISTS (\n        SELECT 1 FROM information_schema.triggers \n        WHERE trigger_name = 'trg_enforce_admin_tenant_link'\n    ) INTO trigger_exists;\n\n    IF NOT trigger_exists THEN\n        RAISE EXCEPTION 'TEST FAILED: Trigger trg_enforce_admin_tenant_link is missing';\n    ELSE\n        RAISE NOTICE 'TEST PASSED: Enforcement trigger exists.';\n    END IF;\n\n    RAISE NOTICE 'ALL AUTOMATED TESTS PASSED SUCCESSFULLY.';\nEND $$;"}	test_suite_runner	redestvgmulti@gmail.com	\N	\N
20260112181437	{"DO $$\nDECLARE\n    target_tenant_id UUID;\n    target_tenant_name TEXT;\n    invalid_admin RECORD;\n    fixed_count INTEGER := 0;\n    link_exists BOOLEAN;\nBEGIN\n    SELECT id, nome INTO target_tenant_id, target_tenant_name\n    FROM empresas\n    WHERE empresa_tipo = 'tenant'\n      AND ativo = true\n    ORDER BY created_at ASC\n    LIMIT 1;\n\n    IF target_tenant_id IS NULL THEN\n        RAISE WARNING 'SKIPPING FIX: No active tenant company found.';\n        RETURN;\n    END IF;\n\n    FOR invalid_admin IN\n        SELECT p.id, p.email, p.role\n        FROM profissionais p\n        WHERE p.role IN ('admin', 'super_admin')\n          AND p.ativo = true\n          AND NOT EXISTS (\n              SELECT 1\n              FROM empresa_profissionais ep\n              JOIN empresas e ON e.id = ep.empresa_id\n              WHERE ep.profissional_id = p.id\n                AND ep.ativo = true\n                AND e.empresa_tipo = 'tenant'\n                AND e.ativo = true\n          )\n    LOOP\n        SELECT EXISTS (\n            SELECT 1 FROM empresa_profissionais \n            WHERE profissional_id = invalid_admin.id \n            AND empresa_id = target_tenant_id\n        ) INTO link_exists;\n\n        IF link_exists THEN\n            UPDATE empresa_profissionais\n            SET ativo = true, funcao = 'Administração (Restored)'\n            WHERE profissional_id = invalid_admin.id \n            AND empresa_id = target_tenant_id;\n        ELSE\n            INSERT INTO empresa_profissionais (\n                profissional_id,\n                empresa_id,\n                funcao,\n                ativo,\n                created_at\n            ) VALUES (\n                invalid_admin.id,\n                target_tenant_id,\n                'Administração (Auto-Fix)',\n                true,\n                NOW()\n            );\n        END IF;\n\n        fixed_count := fixed_count + 1;\n    END LOOP;\nEND $$;"}	fix_admin_tenants	redestvgmulti@gmail.com	\N	\N
20260112181439	{"CREATE OR REPLACE FUNCTION bootstrap_admin_tenant_link_after()\nRETURNS TRIGGER AS $$\nDECLARE\n    target_tenant_id UUID;\n    link_exists BOOLEAN;\nBEGIN\n    IF NEW.role NOT IN ('admin', 'super_admin') THEN\n        RETURN NEW;\n    END IF;\n\n    SELECT EXISTS (\n        SELECT 1\n        FROM empresa_profissionais ep\n        JOIN empresas e ON e.id = ep.empresa_id\n        WHERE ep.profissional_id = NEW.id\n          AND ep.ativo = true\n          AND e.empresa_tipo = 'tenant'\n          AND e.ativo = true\n    ) INTO link_exists;\n\n    IF link_exists THEN\n        RETURN NEW;\n    END IF;\n\n    SELECT id INTO target_tenant_id\n    FROM empresas\n    WHERE empresa_tipo = 'tenant'\n      AND ativo = true\n    ORDER BY created_at ASC\n    LIMIT 1;\n\n    IF target_tenant_id IS NOT NULL THEN\n        INSERT INTO empresa_profissionais (\n            profissional_id,\n            empresa_id,\n            funcao,\n            ativo,\n            created_at\n        ) VALUES (\n            NEW.id,\n            target_tenant_id,\n            'Administração (Bootstrap)',\n            true,\n            NOW()\n        )\n        ON CONFLICT DO NOTHING;\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_bootstrap_admin_tenant ON profissionais;\n\nCREATE TRIGGER trg_bootstrap_admin_tenant\n    AFTER INSERT OR UPDATE ON profissionais\n    FOR EACH ROW\n    EXECUTE FUNCTION bootstrap_admin_tenant_link_after();"}	bootstrap_trigger	redestvgmulti@gmail.com	\N	\N
20260112212432	{"-- Migration: Fix Orphan Admins & Bootstrap Trigger\n-- Description: \n-- 1. Repairs data: Links all orphan admins to the first available Tenant company.\n-- 2. Automation: Adds trigger to ensure future admins are automatically linked.\n\n-- ==========================================\n-- SECTION 1: DATA REPAIR (One-off Fix)\n-- ==========================================\n\nDO $$\nDECLARE\n    target_tenant_id UUID;\n    orphan_count INTEGER := 0;\nBEGIN\n    -- 1. Identify the default tenant (Target for repairs)\n    -- We assume the first active tenant found is the correct \\"Headquarters\\"\n    SELECT id INTO target_tenant_id\n    FROM empresas\n    WHERE empresa_tipo = 'tenant' AND ativo = true\n    LIMIT 1;\n\n    IF target_tenant_id IS NULL THEN\n        RAISE WARNING 'ABORTING REPAIR: No active tenant company found. Please create a tenant company first.';\n        RETURN;\n    END IF;\n\n    -- 2. Find and Fix Orphan Admins\n    -- Logic: Admins who have ZERO links to a tenant company\n    INSERT INTO empresa_profissionais (id, empresa_id, profissional_id, funcao, ativo, created_at)\n    SELECT \n        gen_random_uuid(),         -- New ID\n        target_tenant_id,          -- The Tenant Company\n        p.id,                      -- The Orphan Admin\n        'Admin Repaired',          -- Role description\n        true,                      -- Active\n        NOW()                      -- Created now\n    FROM profissionais p\n    WHERE p.role = 'admin' AND p.ativo = true\n    AND NOT EXISTS (\n        SELECT 1 \n        FROM empresa_profissionais ep \n        JOIN empresas e ON e.id = ep.empresa_id \n        WHERE ep.profissional_id = p.id \n          AND e.empresa_tipo = 'tenant'\n          AND ep.ativo = true\n    );\n\n    GET DIAGNOSTICS orphan_count = ROW_COUNT;\n\n    IF orphan_count > 0 THEN\n        RAISE NOTICE 'SUCCESS: Repaired % orphan admin(s). Linked to Tenant ID: %', orphan_count, target_tenant_id;\n    ELSE\n        RAISE NOTICE 'NO REPAIRS NEEDED: All admins already valid.';\n    END IF;\n\nEND $$;\n\n-- ==========================================\n-- SECTION 2: BOOTSTRAP AUTOMATION (Future Proofing)\n-- ==========================================\n\n-- Function: Auto-link admin to tenant on promotion/creation\nCREATE OR REPLACE FUNCTION bootstrap_admin_tenant_link()\nRETURNS TRIGGER AS $$\nDECLARE\n    default_tenant_id UUID;\nBEGIN\n    -- Only run if user is ADMIN and ACTIVE\n    IF NEW.role = 'admin' AND NEW.ativo = true THEN\n        \n        -- Check if link already exists\n        IF NOT EXISTS (\n            SELECT 1 \n            FROM empresa_profissionais ep \n            JOIN empresas e ON e.id = ep.empresa_id \n            WHERE ep.profissional_id = NEW.id \n              AND e.empresa_tipo = 'tenant'\n              AND ep.ativo = true\n        ) THEN\n            -- Find default tenant\n            SELECT id INTO default_tenant_id\n            FROM empresas\n            WHERE empresa_tipo = 'tenant' AND ativo = true\n            LIMIT 1;\n\n            IF default_tenant_id IS NOT NULL THEN\n                -- Create the link safely\n                INSERT INTO empresa_profissionais (id, empresa_id, profissional_id, funcao, ativo)\n                VALUES (gen_random_uuid(), default_tenant_id, NEW.id, 'Admin Auto-Linked', true);\n                \n                RAISE NOTICE 'BOOTSTRAP: Auto-linked admin % to tenant %', NEW.email, default_tenant_id;\n            ELSE\n                RAISE WARNING 'BOOTSTRAP FAILED: No tenant found for admin %', NEW.email;\n            END IF;\n        END IF;\n\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Trigger: Run BEFORE updates/inserts on `profissionais`\n-- We use AFTER to avoid circular dependency locks if possible, but BEFORE is fine for logic validation. \n-- However, for inserting into ANOTHER table (`empresa_profissionais`), AFTER is safer to ensure `profissionais` row exists.\nDROP TRIGGER IF EXISTS trg_bootstrap_admin_tenant ON profissionais;\n\nCREATE TRIGGER trg_bootstrap_admin_tenant\n    AFTER INSERT OR UPDATE ON profissionais\n    FOR EACH ROW\n    EXECUTE FUNCTION bootstrap_admin_tenant_link();\n\nCOMMENT ON TRIGGER trg_bootstrap_admin_tenant ON profissionais IS \n    'Automatically links admins to the default tenant if no link exists, ensuring integrity.';"}	fix_orphan_admins_and_bootstrap	redestvgmulti@gmail.com	\N	\N
20260112214304	{"-- Migration to link orphaned active staff users to the default tenant\n-- Created at: 2026-01-12 18:50:00\n\nDO $$\nDECLARE\n    v_tenant_id uuid;\n    v_count integer := 0;\nBEGIN\n    -- 1. Get the default tenant ID (assuming the first active tenant found is the default)\n    SELECT id INTO v_tenant_id\n    FROM empresas\n    WHERE empresa_tipo = 'tenant' AND ativo = true\n    LIMIT 1;\n\n    IF v_tenant_id IS NULL THEN\n        RAISE EXCEPTION 'No active tenant found to link orphaned staff users.';\n    END IF;\n\n    -- 2. Identify and link orphaned ACTIVE professionals (excluding super_admin just in case, though they bypass this)\n    -- We insert into empresa_profissionais for users who have NO records in that table.\n    \n    WITH orphans AS (\n        SELECT p.id, p.email\n        FROM profissionais p\n        LEFT JOIN empresa_profissionais ep ON p.id = ep.profissional_id\n        WHERE p.ativo = true\n          AND p.role != 'super_admin' -- Super admin handles their own context\n          AND ep.id IS NULL\n    ),\n    inserted AS (\n        INSERT INTO empresa_profissionais (empresa_id, profissional_id, funcao, ativo, created_at)\n        SELECT \n            v_tenant_id, \n            orphans.id, \n            'Colaborador', -- Default function name\n            true, \n            NOW()\n        FROM orphans\n        RETURNING profissional_id\n    )\n    SELECT count(*) INTO v_count FROM inserted;\n\n    RAISE NOTICE 'Linked % orphaned staff users to tenant %', v_count, v_tenant_id;\n\nEND $$;"}	fix_orphan_staff	redestvgmulti@gmail.com	\N	\N
20260113124257	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FlowOS - Permission-Based Professional Access\n-- Create empresa_profissionais_permitidos table\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- \n-- Purpose: Track which professionals (from a tenant) can work on which \n--          operational companies. This is PERMISSION, not OWNERSHIP.\n--\n-- Key Principles:\n--   - Professionals belong to the TENANT (ownership)\n--   - This table defines AUTHORIZATION to work on operational companies\n--   - Removing permission does NOT remove the professional from tenant\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Create the permissions table\nCREATE TABLE IF NOT EXISTS empresa_profissionais_permitidos (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id UUID NOT NULL,\n  empresa_operacional_id UUID NOT NULL,\n  profissional_id UUID NOT NULL,\n  ativo BOOLEAN DEFAULT true,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n\n  -- Foreign Keys\n  CONSTRAINT fk_empresa_operacional\n    FOREIGN KEY (empresa_operacional_id)\n    REFERENCES empresas(id)\n    ON DELETE CASCADE,\n\n  CONSTRAINT fk_profissional\n    FOREIGN KEY (profissional_id)\n    REFERENCES profissionais(id)\n    ON DELETE CASCADE,\n\n  -- Ensure tenant consistency\n  CONSTRAINT fk_tenant\n    FOREIGN KEY (tenant_id)\n    REFERENCES empresas(id)\n    ON DELETE CASCADE,\n\n  -- Prevent duplicate permissions\n  CONSTRAINT unique_profissional_empresa\n    UNIQUE (empresa_operacional_id, profissional_id)\n);\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- INDICES FOR PERFORMANCE\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE INDEX IF NOT EXISTS idx_epp_tenant \n  ON empresa_profissionais_permitidos(tenant_id);\n\nCREATE INDEX IF NOT EXISTS idx_epp_empresa \n  ON empresa_profissionais_permitidos(empresa_operacional_id);\n\nCREATE INDEX IF NOT EXISTS idx_epp_profissional \n  ON empresa_profissionais_permitidos(profissional_id);\n\nCREATE INDEX IF NOT EXISTS idx_epp_ativo \n  ON empresa_profissionais_permitidos(ativo);\n\n-- Composite index for the most common query pattern\nCREATE INDEX IF NOT EXISTS idx_epp_empresa_ativo \n  ON empresa_profissionais_permitidos(empresa_operacional_id, ativo);\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- SECURITY: ROW LEVEL SECURITY POLICIES\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Enable RLS\nALTER TABLE empresa_profissionais_permitidos ENABLE ROW LEVEL SECURITY;\n\n-- SELECT: Users can only see permissions for their tenant\nCREATE POLICY \\"Users can view permissions within their tenant\\"\n  ON empresa_profissionais_permitidos\n  FOR SELECT\n  USING (\n    tenant_id IN (\n      SELECT DISTINCT COALESCE(e.tenant_id, e.id)\n      FROM empresas e\n      JOIN empresa_profissionais ep ON ep.empresa_id = e.id\n      WHERE ep.profissional_id = auth.uid()\n        AND ep.ativo = true\n        AND e.ativo = true\n    )\n  );\n\n-- INSERT: Only admins can create permissions\nCREATE POLICY \\"Admins can create permissions for their tenant\\"\n  ON empresa_profissionais_permitidos\n  FOR INSERT\n  WITH CHECK (\n    EXISTS (\n      SELECT 1\n      FROM profissionais p\n      JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n      JOIN empresas e ON e.id = ep.empresa_id\n      WHERE p.id = auth.uid()\n        AND p.role = 'admin'\n        AND p.ativo = true\n        AND COALESCE(e.tenant_id, e.id) = tenant_id\n    )\n  );\n\n-- UPDATE: Only admins can update permissions\nCREATE POLICY \\"Admins can update permissions for their tenant\\"\n  ON empresa_profissionais_permitidos\n  FOR UPDATE\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM profissionais p\n      JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n      JOIN empresas e ON e.id = ep.empresa_id\n      WHERE p.id = auth.uid()\n        AND p.role = 'admin'\n        AND p.ativo = true\n        AND COALESCE(e.tenant_id, e.id) = tenant_id\n    )\n  );\n\n-- DELETE: Only admins can delete permissions\nCREATE POLICY \\"Admins can delete permissions for their tenant\\"\n  ON empresa_profissionais_permitidos\n  FOR DELETE\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM profissionais p\n      JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n      JOIN empresas e ON e.id = ep.empresa_id\n      WHERE p.id = auth.uid()\n        AND p.role = 'admin'\n        AND p.ativo = true\n        AND COALESCE(e.tenant_id, e.id) = tenant_id\n    )\n  );\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- TRIGGER: Auto-update updated_at\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION update_empresa_profissionais_permitidos_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = NOW();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trigger_update_epp_updated_at\n  BEFORE UPDATE ON empresa_profissionais_permitidos\n  FOR EACH ROW\n  EXECUTE FUNCTION update_empresa_profissionais_permitidos_updated_at();\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- COMMENTS\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCOMMENT ON TABLE empresa_profissionais_permitidos IS \n  'Permission table: Which professionals can work on which operational companies. This is authorization, not ownership.';\n\nCOMMENT ON COLUMN empresa_profissionais_permitidos.tenant_id IS \n  'Tenant that owns both the professional and the operational company';\n\nCOMMENT ON COLUMN empresa_profissionais_permitidos.empresa_operacional_id IS \n  'Operational company the professional is allowed to work on';\n\nCOMMENT ON COLUMN empresa_profissionais_permitidos.profissional_id IS \n  'Professional who has permission to work on this company';\n\nCOMMENT ON COLUMN empresa_profissionais_permitidos.ativo IS \n  'Whether the permission is currently active';"}	create_empresa_profissionais_permitidos	redestvgmulti@gmail.com	\N	\N
20260113124322	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FlowOS - Backfill Professional Permissions\n-- Populate empresa_profissionais_permitidos from existing data\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- \n-- Purpose: Migrate existing empresa_profissionais relationships to the new\n--          permission-based model WITHOUT breaking current functionality.\n--\n-- Strategy:\n--   1. For each professional linked to an operational company\n--   2. Create a permission record allowing them to work on that company\n--   3. Preserve existing UX while implementing the correct architecture\n-- \n-- SAFETY:\n--   - Uses ON CONFLICT DO NOTHING to be idempotent\n--   - Only migrates operational companies (empresa_tipo = 'operacional')\n--   - Does NOT modify or delete existing data\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Backfill permissions from existing empresa_profissionais links\nINSERT INTO empresa_profissionais_permitidos (\n  tenant_id,\n  empresa_operacional_id,\n  profissional_id,\n  ativo,\n  created_at\n)\nSELECT\n  COALESCE(e.tenant_id, e.id) as tenant_id,  -- Resolve tenant_id correctly\n  e.id as empresa_operacional_id,             -- The operational company\n  ep.profissional_id,                          -- The professional\n  ep.ativo,                                    -- Preserve active status\n  ep.created_at                                -- Preserve creation timestamp\nFROM empresa_profissionais ep\nJOIN empresas e ON e.id = ep.empresa_id\nWHERE e.empresa_tipo = 'operacional'          -- Only operational companies\n  AND e.ativo = true                           -- Only active companies\n  AND ep.ativo = true                          -- Only active relationships\nON CONFLICT (empresa_operacional_id, profissional_id) \nDO NOTHING;                                    -- Skip duplicates (idempotent)\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- VALIDATION QUERIES (for manual verification)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Count how many permissions were created\nDO $$\nDECLARE\n  permission_count INT;\n  source_count INT;\nBEGIN\n  SELECT COUNT(*) INTO permission_count \n  FROM empresa_profissionais_permitidos;\n  \n  SELECT COUNT(*) INTO source_count\n  FROM empresa_profissionais ep\n  JOIN empresas e ON e.id = ep.empresa_id\n  WHERE e.empresa_tipo = 'operacional'\n    AND e.ativo = true\n    AND ep.ativo = true;\n  \n  RAISE NOTICE 'Backfill Complete:';\n  RAISE NOTICE '  - Permissions created: %', permission_count;\n  RAISE NOTICE '  - Source records processed: %', source_count;\n  \n  -- Validation: counts should match (assuming no pre-existing duplicates)\n  IF permission_count < source_count THEN\n    RAISE WARNING 'Permission count is lower than source count. This may indicate duplicates or conflicts.';\n  END IF;\nEND $$;"}	backfill_professional_permissions	redestvgmulti@gmail.com	\N	\N
20260113125015	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FlowOS - Function Permission Layer\n-- Create empresa_funcoes_permitidas table\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- \n-- Purpose: Track which functions are available for which operational companies.\n--          This enables workflow mode to list available functions correctly.\n--\n-- Key Principles:\n--   - Functions define WHAT work can be done on a company\n--   - Professionals are mapped to functions via empresa_profissionais\n--   - This table is the source of truth for workflow function selection\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Create the function permissions table\nCREATE TABLE IF NOT EXISTS empresa_funcoes_permitidas (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id UUID NOT NULL,\n  empresa_operacional_id UUID NOT NULL,\n  funcao TEXT NOT NULL,\n  ativo BOOLEAN DEFAULT true,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n\n  -- Foreign Keys\n  CONSTRAINT fk_empresa_operacional\n    FOREIGN KEY (empresa_operacional_id)\n    REFERENCES empresas(id)\n    ON DELETE CASCADE,\n\n  CONSTRAINT fk_tenant\n    FOREIGN KEY (tenant_id)\n    REFERENCES empresas(id)\n    ON DELETE CASCADE,\n\n  -- Prevent duplicate function permissions per company\n  CONSTRAINT unique_empresa_funcao\n    UNIQUE (empresa_operacional_id, funcao)\n);\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- INDICES FOR PERFORMANCE\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE INDEX IF NOT EXISTS idx_efp_tenant \n  ON empresa_funcoes_permitidas(tenant_id);\n\nCREATE INDEX IF NOT EXISTS idx_efp_empresa \n  ON empresa_funcoes_permitidas(empresa_operacional_id);\n\nCREATE INDEX IF NOT EXISTS idx_efp_funcao \n  ON empresa_funcoes_permitidas(funcao);\n\nCREATE INDEX IF NOT EXISTS idx_efp_ativo \n  ON empresa_funcoes_permitidas(ativo);\n\n-- Composite index for the most common query pattern\nCREATE INDEX IF NOT EXISTS idx_efp_empresa_ativo \n  ON empresa_funcoes_permitidas(empresa_operacional_id, ativo);\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- SECURITY: ROW LEVEL SECURITY POLICIES\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Enable RLS\nALTER TABLE empresa_funcoes_permitidas ENABLE ROW LEVEL SECURITY;\n\n-- SELECT: Users can only see functions for their tenant\nCREATE POLICY \\"Users can view functions within their tenant\\"\n  ON empresa_funcoes_permitidas\n  FOR SELECT\n  USING (\n    tenant_id IN (\n      SELECT DISTINCT COALESCE(e.tenant_id, e.id)\n      FROM empresas e\n      JOIN empresa_profissionais ep ON ep.empresa_id = e.id\n      WHERE ep.profissional_id = auth.uid()\n        AND ep.ativo = true\n        AND e.ativo = true\n    )\n  );\n\n-- INSERT: Only admins can create function permissions\nCREATE POLICY \\"Admins can create function permissions for their tenant\\"\n  ON empresa_funcoes_permitidas\n  FOR INSERT\n  WITH CHECK (\n    EXISTS (\n      SELECT 1\n      FROM profissionais p\n      JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n      JOIN empresas e ON e.id = ep.empresa_id\n      WHERE p.id = auth.uid()\n        AND p.role = 'admin'\n        AND p.ativo = true\n        AND COALESCE(e.tenant_id, e.id) = tenant_id\n    )\n  );\n\n-- UPDATE: Only admins can update function permissions\nCREATE POLICY \\"Admins can update function permissions for their tenant\\"\n  ON empresa_funcoes_permitidas\n  FOR UPDATE\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM profissionais p\n      JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n      JOIN empresas e ON e.id = ep.empresa_id\n      WHERE p.id = auth.uid()\n        AND p.role = 'admin'\n        AND p.ativo = true\n        AND COALESCE(e.tenant_id, e.id) = tenant_id\n    )\n  );\n\n-- DELETE: Only admins can delete function permissions\nCREATE POLICY \\"Admins can delete function permissions for their tenant\\"\n  ON empresa_funcoes_permitidas\n  FOR DELETE\n  USING (\n    EXISTS (\n      SELECT 1\n      FROM profissionais p\n      JOIN empresa_profissionais ep ON ep.profissional_id = p.id\n      JOIN empresas e ON e.id = ep.empresa_id\n      WHERE p.id = auth.uid()\n        AND p.role = 'admin'\n        AND p.ativo = true\n        AND COALESCE(e.tenant_id, e.id) = tenant_id\n    )\n  );\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- TRIGGER: Auto-update updated_at\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION update_empresa_funcoes_permitidas_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = NOW();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trigger_update_efp_updated_at\n  BEFORE UPDATE ON empresa_funcoes_permitidas\n  FOR EACH ROW\n  EXECUTE FUNCTION update_empresa_funcoes_permitidas_updated_at();\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- COMMENTS\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCOMMENT ON TABLE empresa_funcoes_permitidas IS \n  'Function permission table: Which functions are available for which operational companies. Source of truth for workflow mode.';\n\nCOMMENT ON COLUMN empresa_funcoes_permitidas.tenant_id IS \n  'Tenant that owns the operational company';\n\nCOMMENT ON COLUMN empresa_funcoes_permitidas.empresa_operacional_id IS \n  'Operational company where this function is available';\n\nCOMMENT ON COLUMN empresa_funcoes_permitidas.funcao IS \n  'Function name (e.g., \\"Designer\\", \\"Redator\\", \\"Social Media\\")';\n\nCOMMENT ON COLUMN empresa_funcoes_permitidas.ativo IS \n  'Whether this function permission is currently active';"}	create_empresa_funcoes_permitidas	redestvgmulti@gmail.com	\N	\N
20260113125019	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FlowOS - Backfill Function Permissions\n-- Populate empresa_funcoes_permitidas from existing data\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- \n-- Purpose: Migrate existing function definitions from empresa_profissionais\n--          to the new function permission table.\n--\n-- Strategy:\n--   1. For each unique function in each operational company\n--   2. Create a function permission record\n--   3. Preserve workflow functionality\n-- \n-- SAFETY:\n--   - Uses DISTINCT to avoid duplicates\n--   - Uses ON CONFLICT DO NOTHING to be idempotent\n--   - Only migrates operational companies (empresa_tipo = 'operacional')\n--   - Only migrates non-null functions\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Backfill function permissions from existing empresa_profissionais links\nINSERT INTO empresa_funcoes_permitidas (\n  tenant_id,\n  empresa_operacional_id,\n  funcao,\n  ativo,\n  created_at\n)\nSELECT DISTINCT\n  COALESCE(e.tenant_id, e.id) as tenant_id,  -- Resolve tenant_id correctly\n  e.id as empresa_operacional_id,             -- The operational company\n  ep.funcao,                                   -- The function name\n  true as ativo,                               -- All backfilled functions are active\n  MIN(ep.created_at) as created_at            -- Use earliest creation timestamp\nFROM empresa_profissionais ep\nJOIN empresas e ON e.id = ep.empresa_id\nWHERE e.empresa_tipo = 'operacional'          -- Only operational companies\n  AND e.ativo = true                           -- Only active companies\n  AND ep.funcao IS NOT NULL                    -- Only records with functions defined\n  AND ep.ativo = true                          -- Only active relationships\nGROUP BY \n  COALESCE(e.tenant_id, e.id),\n  e.id,\n  ep.funcao\nON CONFLICT (empresa_operacional_id, funcao) \nDO NOTHING;                                    -- Skip duplicates (idempotent)\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- VALIDATION QUERIES (for manual verification)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Count how many function permissions were created\nDO $$\nDECLARE\n  function_permission_count INT;\n  source_function_count INT;\nBEGIN\n  SELECT COUNT(*) INTO function_permission_count \n  FROM empresa_funcoes_permitidas;\n  \n  SELECT COUNT(DISTINCT (e.id, ep.funcao)) INTO source_function_count\n  FROM empresa_profissionais ep\n  JOIN empresas e ON e.id = ep.empresa_id\n  WHERE e.empresa_tipo = 'operacional'\n    AND e.ativo = true\n    AND ep.funcao IS NOT NULL\n    AND ep.ativo = true;\n  \n  RAISE NOTICE 'Function Permission Backfill Complete:';\n  RAISE NOTICE '  - Function permissions created: %', function_permission_count;\n  RAISE NOTICE '  - Unique source functions processed: %', source_function_count;\n  \n  -- Validation\n  IF function_permission_count = 0 THEN\n    RAISE WARNING 'No function permissions were created. Check if empresa_profissionais has funcao data.';\n  END IF;\nEND $$;"}	backfill_function_permissions	redestvgmulti@gmail.com	\N	\N
20260113125809	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- FlowOS - HOTFIX: Backfill Function Permissions (Corrected)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- \n-- Purpose: Populate empresa_funcoes_permitidas with existing function data\n--\n-- DIAGNOSIS: Previous backfill likely failed due to GROUP BY on aggregated field\n-- FIX: Simplified query without MIN() aggregation\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- First, let's check what data exists in the source table\nDO $$\nDECLARE\n  source_count INT;\n  operational_company_count INT;\nBEGIN\n  -- Count distinct functions in empresa_profissionais\n  SELECT COUNT(DISTINCT (ep.empresa_id, ep.funcao)) INTO source_count\n  FROM empresa_profissionais ep\n  JOIN empresas e ON e.id = ep.empresa_id\n  WHERE ep.funcao IS NOT NULL\n    AND ep.ativo = true\n    AND e.ativo = true;\n  \n  -- Count operational companies\n  SELECT COUNT(*) INTO operational_company_count\n  FROM empresas\n  WHERE empresa_tipo = 'operacional'\n    AND ativo = true;\n  \n  RAISE NOTICE '=== DIAGNOSTIC INFO ===';\n  RAISE NOTICE 'Distinct (company, function) pairs found: %', source_count;\n  RAISE NOTICE 'Active operational companies: %', operational_company_count;\nEND $$;\n\n-- Now perform the backfill with corrected query\nINSERT INTO empresa_funcoes_permitidas (\n  tenant_id,\n  empresa_operacional_id,\n  funcao,\n  ativo\n)\nSELECT DISTINCT ON (e.id, ep.funcao)\n  COALESCE(e.tenant_id, e.id) as tenant_id,\n  e.id as empresa_operacional_id,\n  ep.funcao,\n  true as ativo\nFROM empresa_profissionais ep\nJOIN empresas e ON e.id = ep.empresa_id\nWHERE ep.funcao IS NOT NULL\n  AND ep.ativo = true\n  AND e.ativo = true\nORDER BY e.id, ep.funcao, ep.created_at\nON CONFLICT (empresa_operacional_id, funcao) \nDO NOTHING;\n\n-- Validation\nDO $$\nDECLARE\n  inserted_count INT;\nBEGIN\n  SELECT COUNT(*) INTO inserted_count \n  FROM empresa_funcoes_permitidas;\n  \n  RAISE NOTICE '=== BACKFILL RESULT ===';\n  RAISE NOTICE 'Function permissions created: %', inserted_count;\n  \n  IF inserted_count = 0 THEN\n    RAISE WARNING 'NO FUNCTION PERMISSIONS CREATED! Check if empresa_profissionais has funcao data.';\n  ELSE\n    RAISE NOTICE 'SUCCESS: Function permissions backfilled successfully!';\n  END IF;\nEND $$;"}	backfill_function_permissions_fixed	redestvgmulti@gmail.com	\N	\N
20260113130020	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- EMERGENCY FIX: Manually Populate Function Permissions\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- This script will:\n-- 1. Check if empresa_profissionais has funcao data\n-- 2. If YES but empresa_funcoes_permitidas is empty, populate it\n-- 3. If NO, create default functions for each operational company\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- STEP 1: Diagnostic\nDO $$\nDECLARE\n  ep_funcao_count INT;\n  efp_count INT;\n  operational_companies INT;\nBEGIN\n  -- Count funcao records in empresa_profissionais\n  SELECT COUNT(*) INTO ep_funcao_count\n  FROM empresa_profissionais\n  WHERE funcao IS NOT NULL AND ativo = true;\n  \n  -- Count records in empresa_funcoes_permitidas\n  SELECT COUNT(*) INTO efp_count\n  FROM empresa_funcoes_permitidas;\n  \n  -- Count operational companies\n  SELECT COUNT(*) INTO operational_companies\n  FROM empresas\n  WHERE empresa_tipo = 'operacional' AND ativo = true;\n  \n  RAISE NOTICE '========================================';\n  RAISE NOTICE 'DIAGNOSTIC REPORT';\n  RAISE NOTICE '========================================';\n  RAISE NOTICE 'empresa_profissionais with funcao: %', ep_funcao_count;\n  RAISE NOTICE 'empresa_funcoes_permitidas: %', efp_count;\n  RAISE NOTICE 'operational companies (active): %', operational_companies;\n  RAISE NOTICE '========================================';\nEND $$;\n\n-- STEP 2: Populate from existing data (if exists)\nINSERT INTO empresa_funcoes_permitidas (\n  tenant_id,\n  empresa_operacional_id,\n  funcao,\n  ativo\n)\nSELECT DISTINCT ON (e.id, ep.funcao)\n  COALESCE(e.tenant_id, e.id) as tenant_id,\n  e.id as empresa_operacional_id,\n  ep.funcao,\n  true\nFROM empresa_profissionais ep\nJOIN empresas e ON e.id = ep.empresa_id\nWHERE ep.funcao IS NOT NULL\n  AND ep.ativo = true\n  AND e.ativo = true\nORDER BY e.id, ep.funcao\nON CONFLICT (empresa_operacional_id, funcao) DO NOTHING;\n\n-- STEP 3: If still empty, create default functions for ALL operational companies\n-- This ensures workflow mode works even if empresa_profissionais doesn't have funcao data\nINSERT INTO empresa_funcoes_permitidas (\n  tenant_id,\n  empresa_operacional_id,\n  funcao,\n  ativo\n)\nSELECT \n  COALESCE(e.tenant_id, e.id) as tenant_id,\n  e.id,\n  f.funcao,\n  true\nFROM empresas e\nCROSS JOIN (\n  VALUES \n    ('Designer'),\n    ('Redator'),\n    ('Social Media'),\n    ('Revisor')\n) AS f(funcao)\nWHERE e.empresa_tipo = 'operacional'\n  AND e.ativo = true\n  AND NOT EXISTS (\n    SELECT 1 \n    FROM empresa_funcoes_permitidas efp \n    WHERE efp.empresa_operacional_id = e.id\n  )\nON CONFLICT (empresa_operacional_id, funcao) DO NOTHING;\n\n-- STEP 4: Final Report\nDO $$\nDECLARE\n  final_count INT;\n  companies_with_functions INT;\nBEGIN\n  SELECT COUNT(*) INTO final_count\n  FROM empresa_funcoes_permitidas;\n  \n  SELECT COUNT(DISTINCT empresa_operacional_id) INTO companies_with_functions\n  FROM empresa_funcoes_permitidas;\n  \n  RAISE NOTICE '========================================';\n  RAISE NOTICE 'FINAL REPORT';\n  RAISE NOTICE '========================================';\n  RAISE NOTICE 'Total function permissions: %', final_count;\n  RAISE NOTICE 'Companies with functions: %', companies_with_functions;\n  RAISE NOTICE '========================================';\n  \n  IF final_count = 0 THEN\n    RAISE WARNING 'STILL NO FUNCTIONS! Manual intervention required.';\n  ELSE\n    RAISE NOTICE 'SUCCESS! Functions are now available.';\n  END IF;\nEND $$;"}	emergency_populate_functions	redestvgmulti@gmail.com	\N	\N
20260113140127	{"-- PASSO 1: Remover usuário antigo do auth.users (se existir)\nDELETE FROM auth.users WHERE email = 'geovanepanini@agencyflow.com';\n\n-- PASSO 2: Criar/atualizar usuário correto no auth.users\nINSERT INTO auth.users (\n    id,\n    email,\n    email_confirmed_at,\n    encrypted_password,\n    raw_app_meta_data,\n    raw_user_meta_data,\n    created_at,\n    updated_at,\n    instance_id,\n    aud,\n    role\n)\nSELECT \n    gen_random_uuid(),\n    'geovanepanini@icloud.com',\n    now(),\n    crypt('G1eovane23*', gen_salt('bf')),\n    '{\\"provider\\": \\"email\\", \\"providers\\": [\\"email\\"]}'::jsonb,\n    '{\\"full_name\\": \\"Geovane Panini\\"}'::jsonb,\n    now(),\n    now(),\n    '00000000-0000-0000-0000-000000000000',\n    'authenticated',\n    'authenticated'\nWHERE NOT EXISTS (\n    SELECT 1 FROM auth.users WHERE email = 'geovanepanini@icloud.com'\n);\n\n-- PASSO 3: Atualizar tabela profissionais\nDO $$\nDECLARE\n    new_user_id UUID;\nBEGIN\n    SELECT id INTO new_user_id\n    FROM auth.users\n    WHERE email = 'geovanepanini@icloud.com';\n\n    INSERT INTO public.profissionais (id, email, nome, role, ativo, created_at)\n    VALUES (\n        new_user_id,\n        'geovanepanini@icloud.com',\n        'Geovane Panini',\n        'super_admin',\n        true,\n        now()\n    )\n    ON CONFLICT (id) DO UPDATE\n    SET \n        email = 'geovanepanini@icloud.com',\n        role = 'super_admin',\n        ativo = true,\n        nome = 'Geovane Panini';\n\n    DELETE FROM public.profissionais \n    WHERE email = 'geovanepanini@agencyflow.com'\n    AND id != new_user_id;\nEND $$;"}	migrate_super_admin_email_v2	redestvgmulti@gmail.com	\N	\N
20260113141032	{"-- Limpar dados antigos\nDELETE FROM auth.identities WHERE email = 'geovanepanini@icloud.com';\nDELETE FROM auth.users WHERE email = 'geovanepanini@icloud.com';\nDELETE FROM public.profissionais WHERE email = 'geovanepanini@icloud.com';"}	cleanup_and_prepare_super_admin	redestvgmulti@gmail.com	\N	\N
20260113152619	{"CREATE OR REPLACE FUNCTION get_super_admin_dashboard_stats()\nRETURNS JSON AS $$\nDECLARE\n    result JSON;\n    total_tenants INT;\n    active_tenants INT;\n    suspended_tenants INT;\n    growth_data JSON;\n    alerts_data JSON;\n    summary_text TEXT;\n    recent_growth INT;\nBEGIN\n    -- Security: Only super_admin can execute\n    IF NOT EXISTS (\n        SELECT 1 FROM profissionais\n        WHERE id = auth.uid() AND role = 'super_admin'\n    ) THEN\n        RAISE EXCEPTION 'Forbidden: Super Admin access required';\n    END IF;\n\n    -- Total tenants (empresa_tipo = 'tenant' ONLY)\n    SELECT COUNT(*) INTO total_tenants\n    FROM empresas\n    WHERE empresa_tipo = 'tenant';\n\n    -- Active tenants (last 7 days)\n    SELECT COUNT(*) INTO active_tenants\n    FROM empresas\n    WHERE empresa_tipo = 'tenant'\n    AND last_activity_at > NOW() - INTERVAL '7 days';\n\n    -- Suspended tenants\n    SELECT COUNT(*) INTO suspended_tenants\n    FROM empresas\n    WHERE empresa_tipo = 'tenant'\n    AND status_conta = 'suspended';\n\n    -- Growth data (last 30 days)\n    SELECT json_agg(\n        json_build_object(\n            'date', date_series::date,\n            'total', (\n                SELECT COUNT(*)\n                FROM empresas\n                WHERE empresa_tipo = 'tenant'\n                AND created_at::date <= date_series::date\n            )\n        )\n        ORDER BY date_series\n    ) INTO growth_data\n    FROM generate_series(\n        CURRENT_DATE - INTERVAL '29 days',\n        CURRENT_DATE,\n        INTERVAL '1 day'\n    ) AS date_series;\n\n    -- Alerts summary\n    SELECT json_build_object(\n        'critical', (\n            SELECT COUNT(*)\n            FROM empresas\n            WHERE empresa_tipo = 'tenant'\n            AND (\n                status_conta = 'suspended' OR\n                last_activity_at < NOW() - INTERVAL '14 days'\n            )\n        ),\n        'warning', (\n            SELECT COUNT(*)\n            FROM empresas\n            WHERE empresa_tipo = 'tenant'\n            AND last_activity_at > NOW() - INTERVAL '14 days'\n            AND last_activity_at <= NOW() - INTERVAL '7 days'\n        )\n    ) INTO alerts_data;\n\n    -- Recent growth (last 30 days)\n    SELECT COUNT(*) INTO recent_growth\n    FROM empresas\n    WHERE empresa_tipo = 'tenant'\n    AND created_at > NOW() - INTERVAL '30 days';\n\n    -- Executive summary\n    summary_text := total_tenants || ' empresa' || \n                   CASE WHEN total_tenants != 1 THEN 's' ELSE '' END ||\n                   ' ativa' || CASE WHEN total_tenants != 1 THEN 's' ELSE '' END ||\n                   ' no FlowOS, sistema estável e ' ||\n                   CASE WHEN recent_growth > 0 \n                       THEN 'crescimento consistente' \n                       ELSE 'sem novos clientes' \n                   END ||\n                   ' nos últimos 30 dias.';\n\n    -- Build final result\n    result := json_build_object(\n        'metrics', json_build_object(\n            'totalTenants', total_tenants,\n            'activeTenants', active_tenants,\n            'suspendedTenants', suspended_tenants,\n            'activeRatio', CASE \n                WHEN total_tenants > 0 \n                THEN ROUND((active_tenants::decimal / total_tenants * 100), 1)\n                ELSE 0 \n            END\n        ),\n        'growthData', growth_data,\n        'healthStatus', json_build_object(\n            'status', 'healthy',\n            'latency', 150\n        ),\n        'alerts', alerts_data,\n        'summary', summary_text\n    );\n\n    RETURN result;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Grant execute permission to authenticated users (RLS will check super_admin role)\nGRANT EXECUTE ON FUNCTION get_super_admin_dashboard_stats() TO authenticated;\n\n-- Comment\nCOMMENT ON FUNCTION get_super_admin_dashboard_stats() IS 'Returns dashboard statistics for Super Admin - TENANT companies only (empresa_tipo = tenant)';"}	super_admin_dashboard_stats	redestvgmulti@gmail.com	\N	\N
20260115164610	{"-- Enable Realtime for All Required Tables\n-- Ensures tarefas, tarefas_micro, and notifications support real-time subscriptions\n\n-- 1. NOTIFICATIONS TABLE\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_publication_tables \n        WHERE pubname = 'supabase_realtime' \n        AND tablename = 'notifications'\n    ) THEN\n        ALTER PUBLICATION supabase_realtime ADD TABLE notifications;\n    END IF;\nEND $$;\n\nALTER TABLE notifications REPLICA IDENTITY FULL;\nCOMMENT ON TABLE notifications IS 'Notifications table with Realtime enabled for instant updates';\n\n-- 2. TAREFAS TABLE (Used by Sidebar for task count updates)\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_publication_tables \n        WHERE pubname = 'supabase_realtime' \n        AND tablename = 'tarefas'\n    ) THEN\n        ALTER PUBLICATION supabase_realtime ADD TABLE tarefas;\n    END IF;\nEND $$;\n\nALTER TABLE tarefas REPLICA IDENTITY FULL;\nCOMMENT ON TABLE tarefas IS 'Macro tasks table with Realtime enabled for status updates';\n\n-- 3. TAREFAS_MICRO TABLE (Used by OperationalFeed for activity stream)\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_publication_tables \n        WHERE pubname = 'supabase_realtime' \n        AND tablename = 'tarefas_micro'\n    ) THEN\n        ALTER PUBLICATION supabase_realtime ADD TABLE tarefas_micro;\n    END IF;\nEND $$;\n\nALTER TABLE tarefas_micro REPLICA IDENTITY FULL;\nCOMMENT ON TABLE tarefas_micro IS 'Micro tasks table with Realtime enabled for activity feed';"}	enable_realtime_all_tables	redestvgmulti@gmail.com	\N	\N
20260115180147	{"CREATE OR REPLACE FUNCTION create_meeting_notification(\n    p_reuniao_id UUID,\n    p_profissional_id UUID,\n    p_titulo TEXT,\n    p_data_inicio TIMESTAMPTZ,\n    p_interval_minutes INT\n)\nRETURNS UUID AS $$\nDECLARE\n    v_notification_id UUID;\n    v_message TEXT;\n    v_tipo TEXT;\n    v_date_str TEXT;\n    v_time_str TEXT;\nBEGIN\n    -- Format date and time for message (DD/MM at HH:MM)\n    v_date_str := to_char(p_data_inicio AT TIME ZONE 'America/Sao_Paulo', 'DD/MM');\n    v_time_str := to_char(p_data_inicio AT TIME ZONE 'America/Sao_Paulo', 'HH24:MI');\n\n    -- Build clear, professional message (no emojis)\n    IF p_interval_minutes = 0 THEN\n        v_tipo := 'meeting_created';\n        v_message := format('Você foi incluído na reunião \\"%s\\". Data: %s às %s.', p_titulo, v_date_str, v_time_str);\n    ELSIF p_interval_minutes = 60 THEN\n        v_tipo := 'meeting_reminder';\n        v_message := format('Reunião \\"%s\\" começa em 1 hora', p_titulo);\n    ELSIF p_interval_minutes = 30 THEN\n        v_tipo := 'meeting_reminder';\n        v_message := format('Reunião \\"%s\\" começa em 30 minutos', p_titulo);\n    ELSIF p_interval_minutes = 10 THEN\n        v_tipo := 'meeting_reminder';\n        v_message := format('Reunião \\"%s\\" começa em 10 minutos', p_titulo);\n    ELSE\n        v_tipo := 'meeting_reminder';\n        v_message := format('Lembrete: Reunião \\"%s\\" está próxima', p_titulo);\n    END IF;\n\n    -- Check for duplicates for invites (interval 0) to prevent spam\n    IF p_interval_minutes = 0 THEN\n        IF EXISTS (\n            SELECT 1 FROM notificacoes \n            WHERE profissional_id = p_profissional_id \n            AND tipo = 'meeting_created' \n            AND metadata->>'reuniao_id' = p_reuniao_id::TEXT\n        ) THEN\n            RETURN NULL; -- Skip duplicate\n        END IF;\n    END IF;\n\n    -- Insert notification\n    INSERT INTO notificacoes (\n        profissional_id,\n        tipo,\n        mensagem,\n        metadata,\n        lida,\n        created_at\n    ) VALUES (\n        p_profissional_id,\n        v_tipo,\n        v_message,\n        jsonb_build_object(\n            'reuniao_id', p_reuniao_id,\n            'titulo', p_titulo,\n            'data_inicio', p_data_inicio,\n            'interval_minutes', p_interval_minutes\n        ),\n        FALSE,\n        NOW()\n    )\n    RETURNING id INTO v_notification_id;\n\n    RETURN v_notification_id;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;"}	meeting_invites_notification	redestvgmulti@gmail.com	\N	\N
20260115182703	{"-- 1. SCHEMA UPDATES\nALTER TABLE reunioes \nADD COLUMN IF NOT EXISTS cancelled_at TIMESTAMPTZ,\nADD COLUMN IF NOT EXISTS cancelled_by UUID REFERENCES auth.users(id);\n\nALTER TABLE reunioes_participantes \nADD COLUMN IF NOT EXISTS participou BOOLEAN DEFAULT FALSE,\nADD COLUMN IF NOT EXISTS checked_at TIMESTAMPTZ;\n\n-- 2. RLS POLICIES\nDROP POLICY IF EXISTS \\"Admin can update own meetings\\" ON reunioes;\nCREATE POLICY \\"Admin can update own meetings\\"\n    ON reunioes FOR UPDATE\n    USING (criada_por = auth.uid());\n\nDROP POLICY IF EXISTS \\"Staff can confirm presence\\" ON reunioes_participantes;\nCREATE POLICY \\"Staff can confirm presence\\"\n    ON reunioes_participantes FOR UPDATE\n    USING (profissional_id = auth.uid())\n    WITH CHECK (profissional_id = auth.uid());\n\n-- 3. FUNCTIONS\nCREATE OR REPLACE FUNCTION auto_close_meetings()\nRETURNS VOID AS $$\nBEGIN\n    UPDATE reunioes\n    SET status = 'realizada'\n    WHERE status = 'scheduled'\n    AND data_fim < NOW();\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Update Notification RPC\nCREATE OR REPLACE FUNCTION create_meeting_notification(\n    p_reuniao_id UUID,\n    p_profissional_id UUID,\n    p_titulo TEXT,\n    p_data_inicio TIMESTAMPTZ,\n    p_interval_minutes INT\n)\nRETURNS UUID AS $$\nDECLARE\n    v_notification_id UUID;\n    v_message TEXT;\n    v_tipo TEXT;\n    v_date_str TEXT;\n    v_time_str TEXT;\nBEGIN\n    v_date_str := to_char(p_data_inicio AT TIME ZONE 'America/Sao_Paulo', 'DD/MM');\n    v_time_str := to_char(p_data_inicio AT TIME ZONE 'America/Sao_Paulo', 'HH24:MI');\n\n    IF p_interval_minutes = 0 THEN\n        v_tipo := 'meeting_created';\n        v_message := format('Você foi incluído na reunião \\"%s\\". Data: %s às %s.', p_titulo, v_date_str, v_time_str);\n    ELSIF p_interval_minutes = -1 THEN\n        v_tipo := 'meeting_updated';\n        v_message := format('Reunião \\"%s\\" foi alterada para %s às %s.', p_titulo, v_date_str, v_time_str);\n    ELSIF p_interval_minutes = 60 THEN\n        v_tipo := 'meeting_reminder';\n        v_message := format('Reunião \\"%s\\" começa em 1 hora', p_titulo);\n    ELSIF p_interval_minutes = 30 THEN\n        v_tipo := 'meeting_reminder';\n        v_message := format('Reunião \\"%s\\" começa em 30 minutos', p_titulo);\n    ELSIF p_interval_minutes = 10 THEN\n        v_tipo := 'meeting_reminder';\n        v_message := format('Reunião \\"%s\\" começa em 10 minutos', p_titulo);\n    ELSE\n        v_tipo := 'meeting_reminder';\n        v_message := format('Lembrete: Reunião \\"%s\\" está próxima', p_titulo);\n    END IF;\n\n    IF p_interval_minutes = 0 THEN\n         IF EXISTS (SELECT 1 FROM notificacoes WHERE profissional_id = p_profissional_id AND tipo = 'meeting_created' AND metadata->>'reuniao_id' = p_reuniao_id::TEXT) THEN\n            RETURN NULL;\n         END IF;\n    END IF;\n\n    INSERT INTO notificacoes (\n        profissional_id, tipo, mensagem, metadata, lida, created_at\n    ) VALUES (\n        p_profissional_id, v_tipo, v_message,\n        jsonb_build_object('reuniao_id', p_reuniao_id, 'titulo', p_titulo, 'data_inicio', p_data_inicio, 'interval_minutes', p_interval_minutes),\n        FALSE, NOW()\n    )\n    RETURNING id INTO v_notification_id;\n\n    RETURN v_notification_id;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;"}	meeting_institutional_features	redestvgmulti@gmail.com	\N	\N
20260115183545	{"-- 1. FIX CHECK CONSTRAINT AND NORMALIZE STATUS\nALTER TABLE reunioes DROP CONSTRAINT IF EXISTS reunioes_status_check;\n\nUPDATE reunioes SET status = 'agendada' WHERE status = 'scheduled';\nUPDATE reunioes SET status = 'cancelada' WHERE status = 'cancelled';\nUPDATE reunioes SET status = 'realizada' WHERE status = 'completed';\n\n-- Add new constraint with PT-BR values\nALTER TABLE reunioes ADD CONSTRAINT reunioes_status_check \n    CHECK (status IN ('agendada', 'em_andamento', 'realizada', 'cancelada'));\n\n-- 2. UPDATE RLS POLICY FOR CHECK-IN\n-- Staff can only confirm presence if meeting is active and not ended\nDROP POLICY IF EXISTS \\"Staff can confirm presence\\" ON reunioes_participantes;\nCREATE POLICY \\"Staff can confirm presence\\"\n    ON reunioes_participantes FOR UPDATE\n    USING (\n        profissional_id = auth.uid()\n        AND EXISTS (\n            SELECT 1 FROM reunioes r\n            WHERE r.id = reunioes_participantes.reuniao_id\n            AND r.status IN ('agendada', 'em_andamento')\n            AND r.cancelled_at IS NULL\n            AND NOW() <= r.data_fim\n        )\n    )\n    WITH CHECK (\n        profissional_id = auth.uid()\n        AND EXISTS (\n             SELECT 1 FROM reunioes r\n             WHERE r.id = reunioes_participantes.reuniao_id\n             AND r.status IN ('agendada', 'em_andamento')\n             AND r.cancelled_at IS NULL\n             AND NOW() <= r.data_fim\n        )\n    );\n\n-- 3. IDEMPOTENT AUTO-CLOSE FUNCTION\nCREATE OR REPLACE FUNCTION auto_close_meetings()\nRETURNS VOID AS $$\nBEGIN\n    UPDATE reunioes\n    SET status = 'realizada'\n    WHERE data_fim < NOW()\n    AND status IN ('agendada', 'em_andamento')\n    AND cancelled_at IS NULL;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;"}	fix_meeting_status_and_policies	redestvgmulti@gmail.com	\N	\N
20260115190002	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- MIGRATION: OS Edit & Cancel Feature (Production Safe)\n-- DATE: 2026-01-15\n-- DESCRIPTION: Implements \\"soft\\" cancellation, editing capabilities for creators,\n-- and soft-delete for micro-tasks/attachments.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 1. SCHEMA UPDATES (Forward-Only)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- Safely update Status Constraint to include 'cancelada'\nDO $$\nBEGIN\n    -- Only attempt if the constraint exists or we need to ensure it covers 'cancelada'\n    ALTER TABLE tarefas DROP CONSTRAINT IF EXISTS tarefas_status_check;\n    \n    ALTER TABLE tarefas \n    ADD CONSTRAINT tarefas_status_check \n    CHECK (status IN ('pendente', 'em_execucao', 'concluida', 'atrasada', 'cancelada'));\nEND $$;\n\n-- Add Soft Delete support for Micro Tasks\nALTER TABLE tarefas_micro \nADD COLUMN IF NOT EXISTS ativo BOOLEAN DEFAULT true;\n\n-- Add Soft Delete support for Attachments\nALTER TABLE task_attachments \nADD COLUMN IF NOT EXISTS removed_at TIMESTAMPTZ,\nADD COLUMN IF NOT EXISTS removed_by UUID REFERENCES profissionais(id);\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 2. RPC: CANCEL OS\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION cancel_os(os_id UUID)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER -- Runs with elevated privileges to bypass strict RLS if needed, but we check logic manually\nSET search_path = public\nAS $$\nDECLARE\n    v_created_by UUID;\n    v_status TEXT;\nBEGIN\n    -- 1. Validate permissions\n    SELECT created_by, status INTO v_created_by, v_status\n    FROM tarefas\n    WHERE id = os_id;\n\n    IF v_created_by IS NULL THEN\n        RAISE EXCEPTION 'OS not found';\n    END IF;\n\n    IF v_created_by != auth.uid() THEN\n        RAISE EXCEPTION 'Permission denied: Only the creator can cancel this OS';\n    END IF;\n\n    IF v_status = 'cancelada' THEN\n        RAISE EXCEPTION 'OS is already cancelled';\n    END IF;\n\n    IF v_status = 'concluida' THEN\n        RAISE EXCEPTION 'Cannot cancel a completed OS';\n    END IF;\n\n    -- 2. Execute Soft Cancel\n    UPDATE tarefas\n    SET status = 'cancelada',\n        updated_at = NOW()\n    WHERE id = os_id;\n\n    -- 3. Audit Log (using existing mechanism or verify if we need to insert manually)\n    -- Assuming `logs_tarefas` triggers handle basic updates, but we'll add a specific log entry if needed.\n    -- The existing generic trigger should catch the status change.\n    \n    INSERT INTO logs_tarefas (tarefa_id, usuario_id, acao, dados_anteriores, dados_novos)\n    VALUES (os_id, auth.uid(), 'cancel_os', jsonb_build_object('status', v_status), jsonb_build_object('status', 'cancelada'));\n\nEND;\n$$;\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 3. RPC: UPDATE OS\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION update_os(\n    p_os_id UUID,\n    p_payload JSONB\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_tarefa RECORD;\n    v_micro_task JSONB;\n    v_attachment_id UUID;\n    v_new_micro_count INT := 0;\n    v_current_micro_count INT;\nBEGIN\n    -- 1. Fetch OS and Verify Permissions\n    SELECT * INTO v_tarefa FROM tarefas WHERE id = p_os_id;\n\n    IF v_tarefa.id IS NULL THEN\n        RAISE EXCEPTION 'OS not found';\n    END IF;\n\n    IF v_tarefa.created_by != auth.uid() THEN\n        RAISE EXCEPTION 'Permission denied: Only the creator can edit this OS';\n    END IF;\n\n    IF v_tarefa.status IN ('identificando', 'cancelada') THEN -- Safety check on status\n        RAISE EXCEPTION 'Cannot edit OS in current status';\n    END IF;\n\n    -- 2. Update Basic Fields\n    -- Only update if provided in payload and non-null\n    UPDATE tarefas\n    SET \n        titulo = COALESCE(p_payload->>'titulo', titulo),\n        descricao = COALESCE(p_payload->>'descricao', descricao),\n        deadline = COALESCE((p_payload->>'deadline')::TIMESTAMPTZ, deadline),\n        drive_link = COALESCE(p_payload->>'drive_link', drive_link),\n        updated_at = NOW()\n    WHERE id = p_os_id;\n\n    -- 3. Handle Micro Tasks (Workflow Only)\n    \n    -- Count existing micro tasks to determine if it's a workflow\n    SELECT COUNT(*) INTO v_current_micro_count FROM tarefas_micro WHERE tarefa_id = p_os_id AND ativo = true;\n\n    IF p_payload ? 'micro_tasks' THEN\n        -- CRITICA: Se for OS Simples (0 micro tasks) e tentar adicionar -> BLOQUEAR\n        -- A menos que a payload venha vazia, mas se vier com items...\n        IF v_current_micro_count = 0 AND jsonb_array_length(p_payload->'micro_tasks') > 0 THEN\n             -- Check if we really are adding new ones or just sending empty list\n             -- Actually, simpler rule: If current count is 0, we treat it as Simple OS.\n             -- But wait, maybe they want to Convert Simple -> Workflow?\n             -- User prompt says: \\"❌ NÃO podem virar workflow\\". So we MUST BLOCK.\n             RAISE EXCEPTION 'Cannot add micro-tasks to a Simple OS (Staff flow).';\n        END IF;\n\n        -- Iterate over provided micro tasks\n        FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'micro_tasks')\n        LOOP\n            IF (v_micro_task->>'id') IS NULL THEN\n                -- INSERT NEW (Only allowed if Workflow/Admin flow was original)\n                -- Double check logic: we established v_current_micro_count > 0 implies Workflow.\n                -- Use a flag or check existing count again? \n                -- Actually, if we passed the check above, and v_current_micro_count > 0, we are safe.\n                -- But if v_current_micro_count was 0 and we are here, we raised exception. \n                -- Wait, what if it WAS a workflow but all tasks were removed? Unlikely given logic.\n                -- We assume \\"Staff OS\\" implies creation flow didn't add tasks.\n                \n                INSERT INTO tarefas_micro (\n                    tarefa_id,\n                    profissional_id,\n                    funcao,\n                    peso,\n                    status\n                ) VALUES (\n                    p_os_id,\n                    (v_micro_task->>'profissional_id')::UUID,\n                    v_micro_task->>'funcao',\n                    COALESCE((v_micro_task->>'peso')::INT, 1),\n                    'pendente'\n                );\n            ELSE\n                -- CHECK FOR REMOVAL (Soft Delete)\n                -- Frontend sends explicit \\"deleted: true\\" or we infer from absence?\n                -- Payload design: Let's assume payload contains actions or list of \\"to be kept\\"?\n                -- Better: Payload contains \\"changes\\". \n                -- Let's assume the payload 'micro_tasks' is a list of tasks to UPSERT/SYNC.\n                -- Actually, implementing \\"Sync\\" logic is hard in SQL. \n                -- Simpler Approach: Payload has `added_micro_tasks` and `removed_micro_task_ids`.\n                -- But standard practice is usually a list. \n                -- Let's stick to: The payload contains a list of operations or users handle specific actions.\n                -- User prompt: \\"Criador pode Adicionar ... Remover\\".\n                -- Let's support specific keys in payload: `add_micro_tasks` (array) and `remove_micro_task_ids` (array of UUIDs).\n                NULL; -- See specific block below\n            END IF;\n        END LOOP;\n        \n        -- Handling \\"add_micro_tasks\\" specifically to be cleaner\n        IF p_payload ? 'add_micro_tasks' THEN\n             IF v_current_micro_count = 0 THEN\n                 RAISE EXCEPTION 'Cannot add micro-tasks to a Simple OS.';\n             END IF;\n             \n             FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'add_micro_tasks')\n             LOOP\n                INSERT INTO tarefas_micro (\n                    tarefa_id,\n                    profissional_id,\n                    funcao,\n                    peso,\n                    status\n                ) VALUES (\n                    p_os_id,\n                    (v_micro_task->>'profissional_id')::UUID,\n                    v_micro_task->>'funcao',\n                    COALESCE((v_micro_task->>'peso')::INT, 1),\n                    'pendente'\n                );\n             END LOOP;\n        END IF;\n\n        -- Handling \\"remove_micro_task_ids\\"\n        IF p_payload ? 'remove_micro_task_ids' THEN\n            FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'remove_micro_task_ids')\n            LOOP\n                -- Validate Status\n                DECLARE\n                    v_mt_status TEXT;\n                    v_mt_id UUID := (v_micro_task::text)::UUID; -- extracting UUID from jsonb string\n                BEGIN\n                    SELECT status INTO v_mt_status FROM tarefas_micro WHERE id = v_mt_id AND tarefa_id = p_os_id;\n                    \n                    IF v_mt_status IN ('em_execucao', 'concluida') THEN\n                        RAISE EXCEPTION 'Cannot remove micro-task % because it is %', v_mt_id, v_mt_status;\n                    END IF;\n                    \n                    -- Soft Delete\n                    UPDATE tarefas_micro SET ativo = false WHERE id = v_mt_id;\n                END;\n            END LOOP;\n        END IF;\n\n    END IF;\n\n    -- 4. Handle Attachments (Soft Delete only)\n    IF p_payload ? 'remove_attachment_ids' THEN\n        FOR v_attachment_id IN SELECT * FROM jsonb_array_elements_text(p_payload->'remove_attachment_ids')\n        LOOP\n            UPDATE task_attachments \n            SET removed_at = NOW(),\n            removed_by = auth.uid()\n            WHERE id = v_attachment_id AND tarefa_id = p_os_id;\n        END LOOP;\n    END IF;\n    \n    -- Log update\n    INSERT INTO logs_tarefas (tarefa_id, usuario_id, acao, dados_novos)\n    VALUES (p_os_id, auth.uid(), 'update_os', p_payload);\n\nEND;\n$$;\n"}	20260115_edit_cancel_os_feature	redestvgmulti@gmail.com	\N	\N
20260115234341	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- RPC: count_unassigned_tasks\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- \n-- Conta tarefas que NÃO possuem nenhuma micro-task com profissional atribuído\n-- \n-- REGRAS:\n-- - Exclui tarefas concluídas e canceladas\n-- - Uma tarefa é \\"sem responsável\\" se NENHUMA de suas micro-tasks tem profissional_id\n-- - Performance: O(1) - query agregada única\n-- \n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION count_unassigned_tasks()\nRETURNS INTEGER\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nAS $$\n  SELECT COUNT(*)::INTEGER\n  FROM tarefas t\n  WHERE t.status NOT IN ('concluida', 'cancelada')\n  AND NOT EXISTS (\n    SELECT 1\n    FROM tarefas_micro tm\n    WHERE tm.tarefa_id = t.id\n    AND tm.profissional_id IS NOT NULL\n  );\n$$;\n\n-- Comentário descritivo\nCOMMENT ON FUNCTION count_unassigned_tasks IS \n  'Conta tarefas ativas/pendentes que não possuem nenhuma micro-task atribuída a um profissional. Usado para métrica \\"Sem Responsável\\" do Dashboard.';\n\n-- Grant execute permission to authenticated users\nGRANT EXECUTE ON FUNCTION count_unassigned_tasks TO authenticated;"}	add_rpc_count_unassigned_tasks	redestvgmulti@gmail.com	\N	\N
20260117192146	{"-- ✅ RLS Policy: Allow users to UPDATE their own professional record\n-- This fixes 401 errors on legitimate PATCH requests for presence/heartbeat updates\n\nCREATE POLICY \\"professionals_update_own\\"\nON profissionais\nFOR UPDATE\nUSING (id = auth.uid())\nWITH CHECK (id = auth.uid());\n\n-- Security verification comment:\n-- USING: User can only UPDATE if the record's id matches their auth.uid()\n-- WITH CHECK: After UPDATE, the id must still match auth.uid() (prevents changing id to another user)\n-- This maintains:\n-- - Multi-tenancy isolation ✅\n-- - LGPD compliance ✅  \n-- - Self-service updates only ✅\n-- - No cross-user access ✅"}	add_professionals_update_policy	redestvgmulti@gmail.com	\N	\N
20260118155018	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- MIGRATION 053: NOTIFICATION CENTER HARDENING (STAGES 1-3)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- STAGE 1: FUNCTIONAL FIX (MARK ALL AS READ)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION mark_all_notifications_as_read(\n    p_profissional_id UUID DEFAULT auth.uid()\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n    -- Security guard: Only self or admin can mark as read\n    IF p_profissional_id != auth.uid()\n       AND NOT EXISTS (\n           SELECT 1\n           FROM profissionais\n           WHERE id = auth.uid()\n             AND role = 'admin'\n       )\n    THEN\n        RAISE EXCEPTION 'Unauthorized';\n    END IF;\n\n    -- Atomic update for all unread notifications\n    UPDATE notifications\n    SET read_at = NOW()\n    WHERE profissional_id = p_profissional_id\n      AND read_at IS NULL;\nEND;\n$$;\n\nCOMMENT ON FUNCTION mark_all_notifications_as_read IS 'Atomic update to mark all notifications as read for a user.';\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- STAGE 2: ELIMINATION OF TIMEOUT RISK (BULK INSERT)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION bulk_create_deadline_notifications(\n    payloads JSONB\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    inserted_count INT;\nBEGIN\n    -- Bulk insert from JSONB array\n    INSERT INTO notifications (\n        profissional_id,\n        tipo,\n        mensagem,\n        metadata,\n        created_at\n    )\n    SELECT\n        (p->>'profissional_id')::UUID,\n        'deadline_reminder',\n        p->>'message',\n        p->'metadata',\n        NOW()\n    FROM jsonb_to_recordset(payloads) AS p(\n        profissional_id TEXT,\n        message TEXT,\n        metadata JSONB\n    );\n\n    GET DIAGNOSTICS inserted_count = ROW_COUNT;\n\n    RETURN jsonb_build_object(\n        'inserted', inserted_count\n    );\nEND;\n$$;\n\nCOMMENT ON FUNCTION bulk_create_deadline_notifications IS 'Bulk insert for deadline notifications to avoid Edge Function timeouts.';\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- STAGE 3: RETENTION POLICY (CLEANUP)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION cleanup_old_notifications()\nRETURNS INT\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    deleted_count INT;\nBEGIN\n    WITH deleted AS (\n        DELETE FROM notifications\n        WHERE\n            -- 1. Garbage (Soft Deleted > 30 days)\n            (cleared_at < NOW() - INTERVAL '30 days')\n         OR \n            -- 2. Archive (Read > 90 days)\n            (read_at < NOW() - INTERVAL '90 days')\n         OR \n            -- 3. Zombies (Created > 1 year)\n            (created_at < NOW() - INTERVAL '1 year')\n        RETURNING id\n    )\n    SELECT COUNT(*) INTO deleted_count FROM deleted;\n\n    RETURN deleted_count;\nEND;\n$$;\n\nCOMMENT ON FUNCTION cleanup_old_notifications IS 'Cleanup policy: 30 days for cleared, 90 days for read, 1 year max retention.';\n"}	053_notification_hardening_rpc	redestvgmulti@gmail.com	\N	\N
20260119184415	{"-- Fix meeting notifications constraint\n-- Root cause: Constraint blocks notificacoes without os_id or evento_id\n-- Solution: Allow metadata-based reuniao_id\n\nBEGIN;\n\n-- Remove blocking constraint\nALTER TABLE notificacoes\nDROP CONSTRAINT IF EXISTS tem_referencia;\n\n-- Recreate constraint allowing meeting notifications\nALTER TABLE notificacoes\nADD CONSTRAINT tem_referencia\nCHECK (\n    os_id IS NOT NULL\n    OR evento_id IS NOT NULL\n    OR (metadata->>'reuniao_id') IS NOT NULL\n);\n\nCOMMENT ON CONSTRAINT tem_referencia ON notificacoes IS\n'Ensures notification is linked to an OS (os_id), event (evento_id), or meeting (metadata.reuniao_id).';\n\n-- Validation\nDO $$\nDECLARE\n    v_violating_count INT;\nBEGIN\n    SELECT COUNT(*)\n    INTO v_violating_count\n    FROM notificacoes\n    WHERE os_id IS NULL \n      AND evento_id IS NULL \n      AND (metadata->>'reuniao_id') IS NULL;\n    \n    IF v_violating_count > 0 THEN\n        RAISE EXCEPTION 'Migration aborted: % existing row(s) would violate new constraint', v_violating_count;\n    END IF;\n    \n    RAISE NOTICE '✅ Validation passed: All existing rows satisfy new constraint';\n    RAISE NOTICE '✅ Meeting notifications now enabled via metadata.reuniao_id';\nEND $$;\n\nCOMMIT;"}	fix_notificacoes_reuniao_constraint	redestvgmulti@gmail.com	\N	\N
20260120165153	{"-- Fix notification context loss\nBEGIN;\n\nALTER TABLE notifications \nADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}'::jsonb;\n\nALTER TABLE notifications \nADD COLUMN IF NOT EXISTS read_at TIMESTAMPTZ;\n\nCREATE OR REPLACE FUNCTION process_notification_queue()\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_batch_size INT := 100;\n    v_queue_record RECORD;\n    v_admin_ids UUID[];\nBEGIN\n    SELECT ARRAY_AGG(id) INTO v_admin_ids\n    FROM profissionais\n    WHERE role IN ('admin', 'manager', 'master')\n      AND ativo = true;\n\n    IF v_admin_ids IS NULL THEN\n        RETURN;\n    END IF;\n\n    FOR v_queue_record IN\n        SELECT *\n        FROM notification_queue\n        WHERE status = 'pending'\n          AND entity_id IS NOT NULL\n          AND entity_type IS NOT NULL\n        ORDER BY created_at\n        LIMIT v_batch_size\n        FOR UPDATE SKIP LOCKED\n    LOOP\n        BEGIN\n            UPDATE notification_queue\n            SET status = 'processing',\n                retry_count = retry_count + 1\n            WHERE id = v_queue_record.id;\n\n            IF v_queue_record.event_type IN ('macro_completed', 'micro_completed', 'micro_returned') THEN\n                INSERT INTO notifications (\n                    profissional_id,\n                    type,\n                    title,\n                    message,\n                    link,\n                    entity_id,\n                    entity_type,\n                    metadata,\n                    read_at\n                )\n                SELECT\n                    admin_id,\n                    CASE v_queue_record.event_type\n                        WHEN 'macro_completed' THEN 'macro_task_completed'\n                        WHEN 'micro_completed' THEN 'micro_task_completed'\n                        WHEN 'micro_returned' THEN 'micro_task_returned'\n                    END,\n                    v_queue_record.payload->>'title',\n                    v_queue_record.payload->>'message',\n                    v_queue_record.payload->>'link',\n                    v_queue_record.entity_id,\n                    v_queue_record.entity_type,\n                    jsonb_build_object(\n                        'event_type', v_queue_record.event_type,\n                        'entity_id', v_queue_record.entity_id,\n                        'entity_type', v_queue_record.entity_type,\n                        'payload', v_queue_record.payload,\n                        'profissional_target', admin_id,\n                        'queued_at', v_queue_record.created_at\n                    ),\n                    NULL\n                FROM UNNEST(v_admin_ids) AS admin_id\n                WHERE NOT EXISTS (\n                    SELECT 1\n                    FROM notifications n\n                    WHERE n.entity_id = v_queue_record.entity_id\n                      AND n.type = CASE v_queue_record.event_type\n                            WHEN 'macro_completed' THEN 'macro_task_completed'\n                            WHEN 'micro_completed' THEN 'micro_task_completed'\n                            WHEN 'micro_returned' THEN 'micro_task_returned'\n                      END\n                      AND n.profissional_id = admin_id\n                      AND n.created_at > NOW() - INTERVAL '1 hour'\n                );\n            END IF;\n\n            UPDATE notification_queue\n            SET status = 'completed',\n                processed_at = NOW(),\n                error = NULL\n            WHERE id = v_queue_record.id;\n\n        EXCEPTION WHEN OTHERS THEN\n            UPDATE notification_queue\n            SET status = 'failed',\n                error = 'processing_error',\n                processed_at = NOW()\n            WHERE id = v_queue_record.id;\n        END;\n    END LOOP;\n    \n    DELETE FROM notification_queue\n    WHERE status IN ('completed', 'failed')\n      AND processed_at < NOW() - INTERVAL '7 days';\nEND;\n$$;\n\nCOMMIT;"}	fix_notification_context	redestvgmulti@gmail.com	\N	\N
20260121011715	{"-- Migration: Fix Create Tenant RPC Order of Operations\n-- Description: Updates safe_create_tenant_db to prevent TENANT_LINK_REQUIRED error by ensuring tenant link exists before admin promotion.\n\nCREATE OR REPLACE FUNCTION create_tenant_db(\n    p_company_name TEXT,\n    p_cnpj TEXT,\n    p_admin_id UUID,\n    p_admin_name TEXT,\n    p_admin_email TEXT\n) RETURNS UUID AS $$\nDECLARE\n    new_company_id UUID;\nBEGIN\n    -- 1. Create Company\n    INSERT INTO empresas (nome, cnpj, status_conta, icp_status, tipo_negocio)\n    VALUES (p_company_name, p_cnpj, 'active', 'correct', 'other')\n    RETURNING id INTO new_company_id;\n\n    -- 2. Ensure Professional Profile Exists\n    -- CRITICAL FIX: Do NOT set 'admin' role yet. Insert with safe default if new.\n    -- If they exist, keep their current role.\n    INSERT INTO profissionais (id, nome, email, ativo)\n    VALUES (p_admin_id, p_admin_name, p_admin_email, true)\n    ON CONFLICT (id) DO UPDATE\n    SET nome = p_admin_name, ativo = true;\n    -- Note: We intentionally do NOT update or set 'role' here to avoid triggering constraints.\n\n    -- 3. Link Admin to Company\n    INSERT INTO empresa_profissionais (empresa_id, profissional_id)\n    VALUES (new_company_id, p_admin_id)\n    ON CONFLICT (empresa_id, profissional_id) DO NOTHING;\n\n    -- 4. Promote to Admin (Now safe because tenant link exists)\n    UPDATE profissionais\n    SET role = 'admin'\n    WHERE id = p_admin_id;\n\n    RETURN new_company_id;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n"}	fix_create_tenant_rpc	redestvgmulti@gmail.com	\N	\N
20260121012041	{"-- Migration: Fix Create Tenant RPC Order of Operations\n-- Description: Updates safe_create_tenant_db to prevent TENANT_LINK_REQUIRED error by ensuring tenant link exists before admin promotion.\n-- Fixes NULL role constraint by initializing as 'staff'.\n\nCREATE OR REPLACE FUNCTION create_tenant_db(\n    p_company_name TEXT,\n    p_cnpj TEXT,\n    p_admin_id UUID,\n    p_admin_name TEXT,\n    p_admin_email TEXT\n) RETURNS UUID AS $$\nDECLARE\n    new_company_id UUID;\nBEGIN\n    -- 1. Create Company\n    INSERT INTO empresas (nome, cnpj, status_conta, icp_status, tipo_negocio)\n    VALUES (p_company_name, p_cnpj, 'active', 'correct', 'other')\n    RETURNING id INTO new_company_id;\n\n    -- 2. Ensure Professional Profile Exists\n    -- CRITICAL FIX: Do NOT set 'admin' role yet. Insert with safe default 'staff'.\n    -- The role column is NOT NULL, so we must provide a value. 'staff' is safe.\n    INSERT INTO profissionais (id, nome, email, ativo, role)\n    VALUES (p_admin_id, p_admin_name, p_admin_email, true, 'staff')\n    ON CONFLICT (id) DO UPDATE\n    SET nome = p_admin_name, ativo = true;\n    -- Note: We intentionally do NOT update role on conflict to avoid demoting existing admins if any \n    -- (though this flow is for new tenants, handling conflict is good practice).\n\n    -- 3. Link Admin to Company\n    INSERT INTO empresa_profissionais (empresa_id, profissional_id)\n    VALUES (new_company_id, p_admin_id)\n    ON CONFLICT (empresa_id, profissional_id) DO NOTHING;\n\n    -- 4. Promote to Admin (Now safe because tenant link exists)\n    UPDATE profissionais\n    SET role = 'admin'\n    WHERE id = p_admin_id;\n\n    RETURN new_company_id;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n"}	fix_create_tenant_rpc_v2	redestvgmulti@gmail.com	\N	\N
20260121012610	{"-- Migration: Add UNIQUE constraint to empresa_profissionais\n-- Description: Ensures one-to-one mapping between company and professional, enabling safe ON CONFLICT clauses.\n-- This migration is idempotent and safe for production (non-destructive).\n\nDO $$\nBEGIN\n    -- Check if constraint already exists to avoid errors on re-run\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_constraint WHERE conname = 'empresa_profissionais_unique'\n    ) THEN\n        -- Attempt to add the constraint.\n        -- If duplicate data exists, this will FAIL safely (rolling back the transaction),\n        -- protecting the existing data as requested by the user.\n        ALTER TABLE empresa_profissionais\n        ADD CONSTRAINT empresa_profissionais_unique UNIQUE (empresa_id, profissional_id);\n    END IF;\nEND $$;\n"}	add_empresa_profissionais_unique_constraint	redestvgmulti@gmail.com	\N	\N
20260121173940	{"BEGIN;\n\nCREATE OR REPLACE FUNCTION public.get_dashboard_stats(\n    p_start_date TIMESTAMPTZ,\n    p_end_date TIMESTAMPTZ\n)\nRETURNS TABLE(\n    total BIGINT,\n    aberto BIGINT,\n    em_andamento BIGINT,\n    resolvido BIGINT,\n    atrasado BIGINT\n) \nLANGUAGE plpgsql\nSECURITY INVOKER\nSET search_path = public\nAS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        COUNT(*)::BIGINT as total,\n        COUNT(*) FILTER (WHERE status = 'aberto')::BIGINT as aberto,\n        COUNT(*) FILTER (WHERE status = 'em_andamento')::BIGINT as em_andamento,\n        COUNT(*) FILTER (WHERE status = 'resolvido')::BIGINT as resolvido,\n        COUNT(*) FILTER (WHERE status = 'atrasado')::BIGINT as atrasado\n    FROM solicitacoes\n    WHERE created_at >= p_start_date AND created_at <= p_end_date;\nEND;\n$$;\n\nNOTIFY pgrst, 'reload config';\n\nCOMMIT;"}	hotfix_secure_dashboard_stats	redestvgmulti@gmail.com	\N	\N
20260122212248	{"CREATE OR REPLACE FUNCTION is_super_admin()\nRETURNS BOOLEAN\nLANGUAGE sql\nSECURITY DEFINER\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM profissionais\n    WHERE id = auth.uid()\n      AND role = 'super_admin'\n      AND ativo = true\n  );\n$$;\n\nCOMMENT ON FUNCTION is_super_admin IS 'Canonical check for Super Admin role. Source: public.profissionais.role only.';\n\nCREATE OR REPLACE FUNCTION is_admin_in_empresa(empresa_uuid UUID)\nRETURNS BOOLEAN AS $$\nBEGIN\n    RETURN EXISTS (\n        SELECT 1\n        FROM empresa_profissionais ep\n        INNER JOIN profissionais p ON ep.profissional_id = p.id\n        WHERE ep.empresa_id = empresa_uuid\n            AND p.id = auth.uid()\n            AND p.role = 'admin' \n            AND ep.ativo = TRUE\n    );\nEND;\n$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;\n\nCOMMENT ON FUNCTION is_admin_in_empresa IS 'Checks if user is an explicit admin for the specific company. Super Admins are excluded explicitly.';\n\nCREATE OR REPLACE FUNCTION ensure_profissional_on_auth_user()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO profissionais (id, email, role, ativo)\n  VALUES (NEW.id, NEW.email, 'staff', true)\n  ON CONFLICT (id) DO NOTHING;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;\n\nCREATE TRIGGER on_auth_user_created\nAFTER INSERT ON auth.users\nFOR EACH ROW\nEXECUTE FUNCTION ensure_profissional_on_auth_user();\n\nCOMMENT ON FUNCTION ensure_profissional_on_auth_user IS 'Automatically creates a professional profile for new Auth users to prevent \\"zombie\\" users without roles.';"}	fix_rbac_canonical	redestvgmulti@gmail.com	\N	\N
20260123124707	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- MIGRATION: FIX OS PERMISSIONS (Admin & Super Admin Override)\n-- DATE: 2026-01-23\n-- DESCRIPTION: Updates update_os and cancel_os to allow Admins and Super Admins\n-- to edit/cancel ANY Service Order, not just the ones they created.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 1. RPC: CANCEL OS (UPDATED)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION cancel_os(os_id UUID)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER -- Runs with elevated privileges\nSET search_path = public\nAS $$\nDECLARE\n    v_created_by UUID;\n    v_status TEXT;\n    v_is_authorized BOOLEAN;\nBEGIN\n    -- 1. Validate existence\n    SELECT created_by, status INTO v_created_by, v_status\n    FROM tarefas\n    WHERE id = os_id;\n\n    IF v_created_by IS NULL THEN\n        RAISE EXCEPTION 'OS not found';\n    END IF;\n\n    -- 2. Validate Permissions (Creator OR Admin OR Super Admin)\n    -- We check these roles explicitly using our canonical functions or direct checks if functions are not available in this scope context (but they are in public).\n    -- Using direct boolean logic for clarity.\n    v_is_authorized := (\n        v_created_by = auth.uid() OR \n        is_admin() OR \n        is_super_admin()\n    );\n\n    IF NOT v_is_authorized THEN\n        RAISE EXCEPTION 'Permission denied: Only the creator or admins can cancel this OS';\n    END IF;\n\n    IF v_status = 'cancelada' THEN\n        RAISE EXCEPTION 'OS is already cancelled';\n    END IF;\n\n    IF v_status = 'concluida' THEN\n        RAISE EXCEPTION 'Cannot cancel a completed OS';\n    END IF;\n\n    -- 3. Execute Soft Cancel\n    UPDATE tarefas\n    SET status = 'cancelada',\n        updated_at = NOW()\n    WHERE id = os_id;\n\n    -- 4. Audit Log\n    INSERT INTO logs_tarefas (tarefa_id, usuario_id, acao, dados_anteriores, dados_novos)\n    VALUES (os_id, auth.uid(), 'cancel_os', jsonb_build_object('status', v_status), jsonb_build_object('status', 'cancelada'));\n\nEND;\n$$;\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 2. RPC: UPDATE OS (UPDATED)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION update_os(\n    p_os_id UUID,\n    p_payload JSONB\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_tarefa RECORD;\n    v_micro_task JSONB;\n    v_attachment_id UUID;\n    v_new_micro_count INT := 0;\n    v_current_micro_count INT;\n    v_is_authorized BOOLEAN;\nBEGIN\n    -- 1. Fetch OS\n    SELECT * INTO v_tarefa FROM tarefas WHERE id = p_os_id;\n\n    IF v_tarefa.id IS NULL THEN\n        RAISE EXCEPTION 'OS not found';\n    END IF;\n\n    -- 2. Verify Permissions (Creator OR Admin OR Super Admin)\n    v_is_authorized := (\n        v_tarefa.created_by = auth.uid() OR \n        is_admin() OR \n        is_super_admin()\n    );\n\n    IF NOT v_is_authorized THEN\n        RAISE EXCEPTION 'Permission denied: Only the creator or admins can edit this OS';\n    END IF;\n\n    IF v_tarefa.status IN ('identificando', 'cancelada') THEN -- Safety check on status\n        RAISE EXCEPTION 'Cannot edit OS in current status';\n    END IF;\n\n    -- 3. Update Basic Fields\n    -- Only update if provided in payload and non-null\n    UPDATE tarefas\n    SET \n        titulo = COALESCE(p_payload->>'titulo', titulo),\n        descricao = COALESCE(p_payload->>'descricao', descricao),\n        deadline = COALESCE((p_payload->>'deadline')::TIMESTAMPTZ, deadline),\n        drive_link = COALESCE(p_payload->>'drive_link', drive_link),\n        updated_at = NOW()\n    WHERE id = p_os_id;\n\n    -- 4. Handle Micro Tasks (Workflow Only)\n    \n    -- Count existing micro tasks\n    SELECT COUNT(*) INTO v_current_micro_count FROM tarefas_micro WHERE tarefa_id = p_os_id AND ativo = true;\n\n    IF p_payload ? 'micro_tasks' THEN\n        -- CRITICA: Se for OS Simples (0 micro tasks) e tentar adicionar -> BLOQUEAR\n        IF v_current_micro_count = 0 AND jsonb_array_length(p_payload->'micro_tasks') > 0 THEN\n             RAISE EXCEPTION 'Cannot add micro-tasks to a Simple OS (Staff flow).';\n        END IF;\n\n        -- Iterate and Insert implicit \\"New\\" ones if structure matches\n        FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'micro_tasks')\n        LOOP\n            IF (v_micro_task->>'id') IS NULL THEN\n                 -- Logic handled in add_micro_tasks block usually, but kept for compatibility\n                INSERT INTO tarefas_micro (\n                    tarefa_id,\n                    profissional_id,\n                    funcao,\n                    peso,\n                    status\n                ) VALUES (\n                    p_os_id,\n                    (v_micro_task->>'profissional_id')::UUID,\n                    v_micro_task->>'funcao',\n                    COALESCE((v_micro_task->>'peso')::INT, 1),\n                    'pendente'\n                );\n            END IF;\n        END LOOP;\n        \n        -- Handling \\"add_micro_tasks\\" specifically\n        IF p_payload ? 'add_micro_tasks' THEN\n             IF v_current_micro_count = 0 THEN\n                 RAISE EXCEPTION 'Cannot add micro-tasks to a Simple OS.';\n             END IF;\n             \n             FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'add_micro_tasks')\n             LOOP\n                INSERT INTO tarefas_micro (\n                    tarefa_id,\n                    profissional_id,\n                    funcao,\n                    peso,\n                    status\n                ) VALUES (\n                    p_os_id,\n                    (v_micro_task->>'profissional_id')::UUID,\n                    v_micro_task->>'funcao',\n                    COALESCE((v_micro_task->>'peso')::INT, 1),\n                    'pendente'\n                );\n             END LOOP;\n        END IF;\n\n        -- Handling \\"remove_micro_task_ids\\"\n        IF p_payload ? 'remove_micro_task_ids' THEN\n            FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'remove_micro_task_ids')\n            LOOP\n                -- Validate Status\n                DECLARE\n                    v_mt_status TEXT;\n                    v_mt_id UUID := (v_micro_task::text)::UUID;\n                BEGIN\n                    SELECT status INTO v_mt_status FROM tarefas_micro WHERE id = v_mt_id AND tarefa_id = p_os_id;\n                    \n                    IF v_mt_status IN ('em_execucao', 'concluida') THEN\n                        RAISE EXCEPTION 'Cannot remove micro-task % because it is %', v_mt_id, v_mt_status;\n                    END IF;\n                    \n                    -- Soft Delete\n                    UPDATE tarefas_micro SET ativo = false WHERE id = v_mt_id;\n                END;\n            END LOOP;\n        END IF;\n\n    END IF;\n\n    -- 5. Handle Handle Attachments (Soft Delete only)\n    IF p_payload ? 'remove_attachment_ids' THEN\n        FOR v_attachment_id IN SELECT * FROM jsonb_array_elements_text(p_payload->'remove_attachment_ids')\n        LOOP\n            UPDATE task_attachments \n            SET removed_at = NOW(),\n                removed_by = auth.uid()\n            WHERE id = v_attachment_id AND tarefa_id = p_os_id;\n        END LOOP;\n    END IF;\n    \n    -- Log update\n    INSERT INTO logs_tarefas (tarefa_id, usuario_id, acao, dados_novos)\n    VALUES (p_os_id, auth.uid(), 'update_os', p_payload);\n\nEND;\n$$;\n"}	fix_os_permissions	redestvgmulti@gmail.com	\N	\N
20260123130221	{"-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- HOTFIX: BLOCK CROSS-TENANT ACCESS IN RPCs\n-- DATE: 2026-01-23\n-- DESCRIPTION: Enforces strict tenant isolation in update_os and cancel_os.\n-- Removes global Super Admin access from these operational flows.\n-- Requires Admin to be part of the OS's company.\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 1. RPC: CANCEL OS (SECURED)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION cancel_os(os_id UUID)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_created_by UUID;\n    v_empresa_id UUID;\n    v_status TEXT;\n    v_is_authorized BOOLEAN;\nBEGIN\n    -- 1. Validate existence & Get Context\n    SELECT created_by, empresa_id, status \n    INTO v_created_by, v_empresa_id, v_status\n    FROM tarefas\n    WHERE id = os_id;\n\n    IF v_created_by IS NULL THEN\n        RAISE EXCEPTION 'OS not found';\n    END IF;\n\n    -- 2. Validate Permissions (Creator OR Tenant Admin)\n    -- STRICTLY BLOCK CROSS-TENANT: Admin must be in the specific company\n    -- STRICTLY BLOCK SUPER ADMIN: Operational flows are for tenant users only\n    v_is_authorized := (\n        (v_created_by = auth.uid()) \n        OR \n        (is_admin() AND is_admin_in_empresa(v_empresa_id))\n    );\n\n    IF NOT v_is_authorized THEN\n        RAISE EXCEPTION 'Permission denied: Only the creator or a company admin can cancel this OS';\n    END IF;\n\n    IF v_status = 'cancelada' THEN\n        RAISE EXCEPTION 'OS is already cancelled';\n    END IF;\n\n    IF v_status = 'concluida' THEN\n        RAISE EXCEPTION 'Cannot cancel a completed OS';\n    END IF;\n\n    -- 3. Execute Soft Cancel\n    UPDATE tarefas\n    SET status = 'cancelada',\n        updated_at = NOW()\n    WHERE id = os_id;\n\n    -- 4. Audit Log\n    INSERT INTO logs_tarefas (tarefa_id, usuario_id, acao, dados_anteriores, dados_novos)\n    VALUES (os_id, auth.uid(), 'cancel_os', jsonb_build_object('status', v_status), jsonb_build_object('status', 'cancelada'));\n\nEND;\n$$;\n\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n-- 2. RPC: UPDATE OS (SECURED)\n-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCREATE OR REPLACE FUNCTION update_os(\n    p_os_id UUID,\n    p_payload JSONB\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_tarefa RECORD;\n    v_micro_task JSONB;\n    v_attachment_id UUID;\n    v_new_micro_count INT := 0;\n    v_current_micro_count INT;\n    v_is_authorized BOOLEAN;\nBEGIN\n    -- 1. Fetch OS\n    SELECT * INTO v_tarefa FROM tarefas WHERE id = p_os_id;\n\n    IF v_tarefa.id IS NULL THEN\n        RAISE EXCEPTION 'OS not found';\n    END IF;\n\n    -- 2. Verify Permissions (Creator OR Tenant Admin)\n    -- STRICTLY BLOCK CROSS-TENANT: Admin must be in the specific company\n    -- STRICTLY BLOCK SUPER ADMIN: Operational flows are for tenant users only\n    v_is_authorized := (\n        (v_tarefa.created_by = auth.uid()) \n        OR \n        (is_admin() AND is_admin_in_empresa(v_tarefa.empresa_id))\n    );\n\n    IF NOT v_is_authorized THEN\n        RAISE EXCEPTION 'Permission denied: Only the creator or a company admin can edit this OS';\n    END IF;\n\n    IF v_tarefa.status IN ('identificando', 'cancelada') THEN -- Safety check on status\n        RAISE EXCEPTION 'Cannot edit OS in current status';\n    END IF;\n\n    -- 3. Update Basic Fields\n    -- Only update if provided in payload and non-null\n    UPDATE tarefas\n    SET \n        titulo = COALESCE(p_payload->>'titulo', titulo),\n        descricao = COALESCE(p_payload->>'descricao', descricao),\n        deadline = COALESCE((p_payload->>'deadline')::TIMESTAMPTZ, deadline),\n        drive_link = COALESCE(p_payload->>'drive_link', drive_link),\n        updated_at = NOW()\n    WHERE id = p_os_id;\n\n    -- 4. Handle Micro Tasks (Workflow Only)\n    \n    -- Count existing micro tasks\n    SELECT COUNT(*) INTO v_current_micro_count FROM tarefas_micro WHERE tarefa_id = p_os_id AND ativo = true;\n\n    IF p_payload ? 'micro_tasks' THEN\n        -- CRITICA: Se for OS Simples (0 micro tasks) e tentar adicionar -> BLOQUEAR\n        IF v_current_micro_count = 0 AND jsonb_array_length(p_payload->'micro_tasks') > 0 THEN\n             RAISE EXCEPTION 'Cannot add micro-tasks to a Simple OS (Staff flow).';\n        END IF;\n\n        -- Iterate and Insert\n        FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'micro_tasks')\n        LOOP\n            IF (v_micro_task->>'id') IS NULL THEN\n                INSERT INTO tarefas_micro (\n                    tarefa_id,\n                    profissional_id,\n                    funcao,\n                    peso,\n                    status\n                ) VALUES (\n                    p_os_id,\n                    (v_micro_task->>'profissional_id')::UUID,\n                    v_micro_task->>'funcao',\n                    COALESCE((v_micro_task->>'peso')::INT, 1),\n                    'pendente'\n                );\n            END IF;\n        END LOOP;\n        \n        -- Handling \\"add_micro_tasks\\" specifically\n        IF p_payload ? 'add_micro_tasks' THEN\n             IF v_current_micro_count = 0 THEN\n                 RAISE EXCEPTION 'Cannot add micro-tasks to a Simple OS.';\n             END IF;\n             \n             FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'add_micro_tasks')\n             LOOP\n                INSERT INTO tarefas_micro (\n                    tarefa_id,\n                    profissional_id,\n                    funcao,\n                    peso,\n                    status\n                ) VALUES (\n                    p_os_id,\n                    (v_micro_task->>'profissional_id')::UUID,\n                    v_micro_task->>'funcao',\n                    COALESCE((v_micro_task->>'peso')::INT, 1),\n                    'pendente'\n                );\n             END LOOP;\n        END IF;\n\n        -- Handling \\"remove_micro_task_ids\\"\n        IF p_payload ? 'remove_micro_task_ids' THEN\n            FOR v_micro_task IN SELECT * FROM jsonb_array_elements(p_payload->'remove_micro_task_ids')\n            LOOP\n                -- Validate Status\n                DECLARE\n                    v_mt_status TEXT;\n                    v_mt_id UUID := (v_micro_task::text)::UUID;\n                BEGIN\n                    SELECT status INTO v_mt_status FROM tarefas_micro WHERE id = v_mt_id AND tarefa_id = p_os_id;\n                    \n                    IF v_mt_status IN ('em_execucao', 'concluida') THEN\n                        RAISE EXCEPTION 'Cannot remove micro-task % because it is %', v_mt_id, v_mt_status;\n                    END IF;\n                    \n                    -- Soft Delete\n                    UPDATE tarefas_micro SET ativo = false WHERE id = v_mt_id;\n                END;\n            END LOOP;\n        END IF;\n\n    END IF;\n\n    -- 5. Handle Handle Attachments (Soft Delete only)\n    IF p_payload ? 'remove_attachment_ids' THEN\n        FOR v_attachment_id IN SELECT * FROM jsonb_array_elements_text(p_payload->'remove_attachment_ids')\n        LOOP\n            UPDATE task_attachments \n            SET removed_at = NOW(),\n                removed_by = auth.uid()\n            WHERE id = v_attachment_id AND tarefa_id = p_os_id;\n        END LOOP;\n    END IF;\n    \n    -- Log update\n    INSERT INTO logs_tarefas (tarefa_id, usuario_id, acao, dados_novos)\n    VALUES (p_os_id, auth.uid(), 'update_os', p_payload);\n\nEND;\n$$;\n"}	hotfix_cross_tenant_rpcs	redestvgmulti@gmail.com	\N	\N
