20260125141244	{"-- ==============================================================================\n-- MIGRATION: FIX FOUNDATION SCHEMA (MISSING TENANT TABLE)\n-- Data: 25/01/2026\n-- Descrição: Recria a tabela 'cidades' que está faltando no ambiente, \n--            essencial para o funcionamento do Feed e RLS.\n-- ==============================================================================\n\nBEGIN;\n\n-- 1. Create 'cidades' table if not exists\nCREATE TABLE IF NOT EXISTS public.cidades (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    nome TEXT NOT NULL,\n    dominio TEXT UNIQUE,\n    slug TEXT UNIQUE,\n    ativo BOOLEAN DEFAULT true,\n    configuracoes JSONB DEFAULT '{}'::jsonb,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- 2. Enable RLS\nALTER TABLE public.cidades ENABLE ROW LEVEL SECURITY;\n\n-- 3. Basic Policy (Public Read for Domain Resolution)\nCREATE POLICY \\"public_read_cidades\\" ON public.cidades\n    FOR SELECT USING (true);\n\n-- 4. Seed Default City if empty (Safe Fallback)\nINSERT INTO public.cidades (nome, dominio, slug, ativo)\nSELECT 'Cidade Modelo', 'demo.cityos.cloud', 'demo', true\nWHERE NOT EXISTS (SELECT 1 FROM public.cidades);\n\nCOMMIT;"}	20260125_fix_foundation_schema	redestvgmulti@gmail.com	\N	\N
20260125141326	{"-- ==============================================================================\n-- MIGRATION: IMPLEMENTAÇÃO FASE 2 - BACKEND DO FEED INSTITUCIONAL\n-- Data: 22/01/2026\n-- Ref: CITYOS_ESPECIFICACAO_FASE_2.md\n-- Descrição: Cria toda a estrutura de banco de dados, views e RPCs para o Feed.\n-- ==============================================================================\n\nBEGIN;\n\n-- 1. ENUMS E TIPOS\n-- ==============================================================================\n\nDO $$ BEGIN\n    CREATE TYPE feed_post_type AS ENUM (\n        'official_news',\n        'emergency_alert',\n        'service_update',\n        'public_event'\n    );\nEXCEPTION\n    WHEN duplicate_object THEN null;\nEND $$;\n\nDO $$ BEGIN\n    CREATE TYPE feed_post_status AS ENUM (\n        'draft',\n        'published',\n        'archived'\n    );\nEXCEPTION\n    WHEN duplicate_object THEN null;\nEND $$;\n\n-- 2. TABELA PRINCIPAL: feed_posts\n-- ==============================================================================\n\nCREATE TABLE IF NOT EXISTS public.feed_posts (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cidade_id UUID NOT NULL REFERENCES public.cidades(id) ON DELETE RESTRICT,\n    tipo feed_post_type NOT NULL,\n    status feed_post_status NOT NULL DEFAULT 'draft',\n    titulo VARCHAR(140) NOT NULL,\n    resumo VARCHAR(280) NOT NULL,\n    corpo TEXT,\n    imagem_capa TEXT,\n    link_externo TEXT,\n    link_texto VARCHAR(30),\n    published_at TIMESTAMPTZ,\n    expires_at TIMESTAMPTZ,\n    created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, -- Audit (quem criou tecnicamente)\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,\n    deleted_at TIMESTAMPTZ, -- Soft Delete\n\n    CONSTRAINT check_dates CHECK (expires_at > published_at),\n    CONSTRAINT check_link_label CHECK (link_texto IS NULL OR link_externo IS NOT NULL)\n);\n\n-- Índices para Performance de Leitura\nCREATE INDEX IF NOT EXISTS idx_feed_posts_read_public \n    ON public.feed_posts(cidade_id, published_at DESC) \n    WHERE status = 'published' AND deleted_at IS NULL;\n\nCREATE INDEX IF NOT EXISTS idx_feed_posts_admin \n    ON public.feed_posts(cidade_id, status);\n\n-- Trigger de Updated At\nCREATE OR REPLACE FUNCTION update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$$ language 'plpgsql';\n\nDROP TRIGGER IF EXISTS update_feed_posts_modtime ON public.feed_posts;\nCREATE TRIGGER update_feed_posts_modtime \n    BEFORE UPDATE ON public.feed_posts \n    FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();\n\n\n-- 3. HELPER FUNCTION (RLS) - Garantir que existe e é segura\n-- ==============================================================================\nCREATE OR REPLACE FUNCTION public.current_cidade_id()\nRETURNS UUID\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n    SELECT COALESCE(\n        (current_setting('request.jwt.claims', true)::jsonb -> 'app_metadata' ->> 'cidade_id')::uuid,\n        NULL\n    );\n$$;\n\n\n-- 4. ROW LEVEL SECURITY (RLS)\n-- ==============================================================================\nALTER TABLE public.feed_posts ENABLE ROW LEVEL SECURITY;\n\n-- 4.1. Leitura Cidadão (Anon/Auth)\n-- Regra: Apenas publicados, da sua cidade, não deletados, data válida.\n-- Reforçaremos isso na View, mas o RLS é a barreira final.\nCREATE POLICY \\"feed_select_public\\" ON public.feed_posts\nFOR SELECT\nUSING (\n    (auth.role() = 'anon' OR auth.role() = 'authenticated') AND\n    cidade_id = public.current_cidade_id() AND\n    status = 'published' AND\n    deleted_at IS NULL AND\n    (published_at <= NOW() OR published_at IS NULL)\n);\n\n-- 4.2. Leitura e Escrita Staff (Admin/Secretário)\n-- Staff vê tudo da sua cidade.\nCREATE POLICY \\"feed_all_staff\\" ON public.feed_posts\nUSING (\n    (auth.jwt() -> 'app_metadata' ->> 'role' IN ('admin', 'secretario', 'master_admin')) AND\n    (\n        cidade_id = public.current_cidade_id() OR\n        auth.jwt() -> 'app_metadata' ->> 'role' = 'master_admin'\n    )\n);\n\n-- 4.3. Bloqueio de Escrita Direta (INSERT/UPDATE/DELETE) para Public\n-- As policies acima já cobrem implicitamente, mas garantimos:\n-- Apenas Staff tem policy com USING/CHECK permissivo.\n\n\n-- 5. VIEW UNIFICADA DE LEITURA (PÚBLICA)\n-- ==============================================================================\n\nDROP VIEW IF EXISTS public.v_feed_institucional_publico;\n\nCREATE VIEW public.v_feed_institucional_publico \nWITH (security_invoker = true) -- Respeita RLS do usuário logado\nAS\nSELECT \n    id,\n    cidade_id,\n    tipo,\n    titulo,\n    resumo,\n    imagem_capa as imagem_url,\n    link_externo as action_link,\n    link_texto as action_label,\n    published_at as data_publicacao,\n    (tipo = 'emergency_alert') as is_alert,\n    -- Opcionalmente: corpo as conteudo_html (se o frontend precisar carregar na lista)\n    status -- Apenas para debug/admin, frontend deve ignorar\nFROM \n    public.feed_posts\nWHERE \n    status = 'published'\n    AND deleted_at IS NULL\n    AND published_at <= NOW()\n    AND (expires_at > NOW() OR expires_at IS NULL);\n\n\n-- 6. RPCs DE MUTAÇÃO (ESCRITA SEGURA)\n-- ==============================================================================\n\n-- 6.1. Criar Post (Draft)\nCREATE OR REPLACE FUNCTION public.create_feed_post(\n    p_tipo feed_post_type,\n    p_titulo text,\n    p_resumo text,\n    p_corpo text DEFAULT NULL,\n    p_imagem_capa text DEFAULT NULL,\n    p_link_externo text DEFAULT NULL,\n    p_link_texto text DEFAULT NULL,\n    p_agendar_para timestamptz DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_cidade_id UUID;\n    v_user_id UUID;\n    v_new_id UUID;\nBEGIN\n    -- Contexto\n    v_user_id := auth.uid();\n    v_cidade_id := public.current_cidade_id();\n    \n    IF v_cidade_id IS NULL THEN\n        RAISE EXCEPTION 'Usuário sem cidade definida no token.';\n    END IF;\n\n    -- Validar permissão (Apenas Staff)\n    IF NOT (SELECT (auth.jwt() -> 'app_metadata' ->> 'role') IN ('admin', 'secretario', 'master_admin')) THEN\n         RAISE EXCEPTION 'Acesso negado: Apenas staff pode criar posts.';\n    END IF;\n\n    -- Insert\n    INSERT INTO public.feed_posts (\n        cidade_id, tipo, status, titulo, resumo, corpo, imagem_capa, \n        link_externo, link_texto, published_at, created_by\n    ) VALUES (\n        v_cidade_id, \n        p_tipo, \n        'draft', -- Sempre nasce draft\n        p_titulo, \n        p_resumo, \n        p_corpo, \n        p_imagem_capa, \n        p_link_externo, \n        p_link_texto, \n        p_agendar_para, -- Se NULL e for publicar, será setado depois\n        v_user_id\n    ) RETURNING id INTO v_new_id;\n\n    RETURN jsonb_build_object('success', true, 'id', v_new_id);\nEND;\n$$;\n\n\n-- 6.2. Publicar Post\nCREATE OR REPLACE FUNCTION public.publish_feed_post(\n    p_post_id uuid,\n    p_disparar_push boolean DEFAULT false\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_cidade_id UUID;\n    v_role TEXT;\n    v_post_cidade_id UUID;\nBEGIN\n    v_cidade_id := public.current_cidade_id();\n    v_role := auth.jwt() -> 'app_metadata' ->> 'role';\n\n    -- Validar Role (Secretário NÃO pode publicar)\n    IF v_role NOT IN ('admin', 'master_admin') THEN\n        RAISE EXCEPTION 'Permissão insuficiente: Requer aprovação de Admin.';\n    END IF;\n\n    -- Verificar Propriedade\n    SELECT cidade_id INTO v_post_cidade_id FROM public.feed_posts WHERE id = p_post_id;\n    \n    IF v_post_cidade_id IS DISTINCT FROM v_cidade_id AND v_role <> 'master_admin' THEN\n        RAISE EXCEPTION 'Post não pertence à sua cidade.';\n    END IF;\n\n    -- Update\n    UPDATE public.feed_posts\n    SET \n        status = 'published',\n        published_at = COALESCE(published_at, NOW()), -- Se já tinha data (agendado), mantém. Senão põe agora.\n        updated_by = auth.uid()\n    WHERE id = p_post_id;\n\n    -- TODO: Integração com Push Notification aqui (Fila Async)\n    -- IF p_disparar_push THEN ... END IF;\n\n    RETURN jsonb_build_object('success', true, 'status', 'published');\nEND;\n$$;\n\n\n-- 6.3. Arquivar (Soft Delete)\nCREATE OR REPLACE FUNCTION public.archive_feed_post(\n    p_post_id uuid\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_cidade_id UUID;\n    v_role TEXT;\nBEGIN\n    v_cidade_id := public.current_cidade_id();\n    v_role := auth.jwt() -> 'app_metadata' ->> 'role';\n\n    IF v_role NOT IN ('admin', 'master_admin') THEN\n         RAISE EXCEPTION 'Permissão insuficiente.';\n    END IF;\n\n    UPDATE public.feed_posts\n    SET \n        status = 'archived',\n        deleted_at = NOW(),\n        updated_by = auth.uid()\n    WHERE id = p_post_id \n      AND (cidade_id = v_cidade_id OR v_role = 'master_admin');\n\n    RETURN jsonb_build_object('success', true);\nEND;\n$$;\n\n\n-- 7. AUDITORIA (INTEGRAÇÃO COM LOGS EXISTENTES)\n-- ==============================================================================\n-- Assume que a tabela audit_logs e a função audit_trigger_func já existem da Fase 1.\n-- Apenas aplicamos o trigger.\n\nDO $$ BEGIN\n    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'audit_trigger_func') THEN\n        CREATE TRIGGER audit_feed_posts\n        AFTER INSERT OR UPDATE OR DELETE ON public.feed_posts\n        FOR EACH ROW EXECUTE PROCEDURE audit_trigger_func();\n    END IF;\nEND $$;\n\n\nCOMMIT;"}	20260122_phase2_feed_backend	redestvgmulti@gmail.com	\N	\N
20260125141333	{"-- ==============================================================================\n-- MIGRATION: API CONSTITUCIONAL - FEED INSTITUCIONAL (READ-ONLY)\n-- Data: 25/01/2026\n-- Descrição: RPC segura para leitura do feed, com resolução de tenant.\n-- ==============================================================================\n\n-- 1. Helper para Resolver Cidade (Public/Auth)\n-- Tenta resolver por JWT (Auth) ou, futuramente, por Domínio/Header (Anon).\n-- OBS: Por enquanto, assumiremos que o frontend envia 'x-cidade-id' no header para anônimos\n-- ou que existe um mapeamento. Para MVP, focaremos no JWT ou Header explícito validado.\nCREATE OR REPLACE FUNCTION public.resolve_current_city_id()\nRETURNS UUID\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_cidade_id UUID;\n    v_claims JSONB;\nBEGIN\n    -- 1. Tentar via JWT (Usuário Logado)\n    v_claims := current_setting('request.jwt.claims', true)::jsonb;\n    \n    IF v_claims IS NOT NULL AND (v_claims -> 'app_metadata' ->> 'cidade_id') IS NOT NULL THEN\n        RETURN (v_claims -> 'app_metadata' ->> 'cidade_id')::uuid;\n    END IF;\n\n    -- 2. Tentar via Header 'x-city-os-tenant' (Acesso Público Seguro)\n    -- O gateway/frontend deve garantir que este header corresponde ao domínio acessado.\n    BEGIN\n        v_cidade_id := (current_setting('request.headers', true)::jsonb ->> 'x-city-os-tenant')::uuid;\n        IF v_cidade_id IS NOT NULL THEN\n            RETURN v_cidade_id;\n        END IF;\n    EXCEPTION \n        WHEN OTHERS THEN NULL; -- Ignora erros de cast\n    END;\n\n    -- Se não encontrou, retorna NULL (RPC deve tratar)\n    RETURN NULL;\nEND;\n$$;\n\n-- 2. RPC: Get Institutional Feed\nCREATE OR REPLACE FUNCTION public.get_institutional_feed(\n    p_page INTEGER DEFAULT 1,\n    p_page_size INTEGER DEFAULT 10,\n    p_tipo_filtro feed_post_type DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER -- Necessário para ler tabela filtrada manualmente\nSET search_path = public\nAS $$\nDECLARE\n    v_cidade_id UUID;\n    v_offset INTEGER;\n    v_total INTEGER;\n    v_has_more BOOLEAN;\n    v_items JSONB;\nBEGIN\n    -- 1. Contexto\n    v_cidade_id := public.resolve_current_city_id();\n    \n    IF v_cidade_id IS NULL THEN\n        -- Fallback seguro: Retorna vazio ou erro? Para API pública, erro 400 é melhor.\n        RETURN jsonb_build_object(\n            'success', false,\n            'error', 'Tenant context not found. Please provide credentials or strict tenant header.'\n        );\n    END IF;\n\n    -- 2. Paginação\n    p_page := GREATEST(1, p_page);\n    p_page_size := GREATEST(1, LEAST(50, p_page_size)); -- Max 50\n    v_offset := (p_page - 1) * p_page_size;\n\n    -- 3. Contagem Total (Cachear se possível no front)\n    SELECT COUNT(*) INTO v_total\n    FROM public.feed_posts\n    WHERE cidade_id = v_cidade_id\n      AND status = 'published'\n      AND deleted_at IS NULL\n      AND (tipo = p_tipo_filtro OR p_tipo_filtro IS NULL);\n\n    -- 4. Query Relational -> JSON\n    SELECT jsonb_agg(\n        jsonb_build_object(\n            'id', f.id,\n            'tipo', f.tipo,\n            'titulo', f.titulo,\n            'resumo', f.resumo,\n            'imagem_url', f.imagem_capa,\n            'data_publicacao', f.published_at,\n            'action_link', f.link_externo,\n            'action_label', f.link_texto,\n            'is_alert', (f.tipo = 'emergency_alert')\n        ) ORDER BY f.published_at DESC\n    )\n    INTO v_items\n    FROM (\n        SELECT * \n        FROM public.feed_posts\n        WHERE cidade_id = v_cidade_id\n          AND status = 'published'\n          AND deleted_at IS NULL\n          AND (tipo = p_tipo_filtro OR p_tipo_filtro IS NULL)\n        ORDER BY published_at DESC\n        LIMIT p_page_size OFFSET v_offset\n    ) f;\n\n    -- 5. Resultado\n    v_has_more := (v_offset + p_page_size) < v_total;\n\n    RETURN jsonb_build_object(\n        'success', true,\n        'data', COALESCE(v_items, '[]'::jsonb),\n        'meta', jsonb_build_object(\n            'page', p_page,\n            'size', p_page_size,\n            'total', v_total,\n            'has_more', v_has_more,\n            'tenant_id', v_cidade_id -- Debug/Confirmation\n        )\n    );\nEND;\n$$;"}	20260125_feed_api_rpc	redestvgmulti@gmail.com	\N	\N
20260125141549	{"-- ==============================================================================\n-- MIGRATION: FOUNDATION RECOVERY (REBUILD OPERATIONAL SCHEMA)\n-- Data: 25/01/2026\n-- Descrição: Recria tabelas core que estão faltando (Solicitações, Tipos, Secretarias).\n-- ==============================================================================\n\nBEGIN;\n\n-- 1. SECRETARIAS (Copied from 008-cityos-core)\nCREATE TABLE IF NOT EXISTS public.secretarias (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  cidade_id UUID NOT NULL REFERENCES public.cidades(id),\n  nome TEXT NOT NULL,\n  nome_secretario TEXT,\n  email TEXT,\n  telefone TEXT,\n  descricao TEXT,\n  criado_em TIMESTAMPTZ DEFAULT now()\n);\nALTER TABLE public.secretarias ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"public_read_secretarias\\" ON secretarias FOR SELECT USING (true);\n\n\n-- 2. TIPOS DE SOLICITAÇÃO\nCREATE TABLE IF NOT EXISTS public.tipos_solicitacao (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cidade_id UUID NOT NULL REFERENCES public.cidades(id),\n    secretaria_id UUID REFERENCES public.secretarias(id),\n    nome TEXT NOT NULL,\n    descricao TEXT,\n    prazo_dias INTEGER DEFAULT 15,\n    prioridade TEXT DEFAULT 'media',\n    ativo BOOLEAN DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\nALTER TABLE public.tipos_solicitacao ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"public_read_tipos\\" ON tipos_solicitacao FOR SELECT USING (true);\n\n\n-- 3. SOLICITAÇÕES\nCREATE TABLE IF NOT EXISTS public.solicitacoes (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    cidadao_id UUID REFERENCES auth.users(id), -- Nullable for anon? No, RPC enforces user.\n    cidade_id UUID NOT NULL REFERENCES public.cidades(id),\n    tipo_solicitacao_id UUID REFERENCES public.tipos_solicitacao(id),\n    tipo_ocorrencia TEXT CHECK (tipo_ocorrencia IN ('sugestao', 'reclamacao', 'elogio')),\n    titulo TEXT NOT NULL,\n    descricao TEXT,\n    endereco TEXT,\n    latitude FLOAT,\n    longitude FLOAT,\n    foto_url TEXT,\n    status TEXT DEFAULT 'aberto',\n    protocolo TEXT UNIQUE,\n    idempotency_key TEXT UNIQUE,\n    data_resolucao TIMESTAMPTZ,\n    comentario_resolucao TEXT,\n    fotos_resolucao TEXT[],\n    secretaria_id UUID REFERENCES public.secretarias(id), -- Denormalized for ease? Or join? RPC uses it.\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    deleted_at TIMESTAMPTZ\n);\nALTER TABLE public.solicitacoes ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"solicitacoes_own\\" ON solicitacoes USING (auth.uid() = cidadao_id);\n\n-- 4. PROTOCOL GENERATOR\nCREATE OR REPLACE FUNCTION generate_protocolo() RETURNS TRIGGER AS $$\nBEGIN\n    -- Format: YYYYMMDD-HHMISS-RAND\n    NEW.protocolo := to_char(now(), 'YYYYMMDD') || '-' || to_char(now(), 'HH24MISS') || '-' || substring(md5(random()::text) from 1 for 4);\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER set_protocolo\nBEFORE INSERT ON solicitacoes\nFOR EACH ROW\nWHEN (NEW.protocolo IS NULL)\nEXECUTE FUNCTION generate_protocolo();\n\n-- 5. Helper Tables (Comments/Attachments) referenced by RPCs\nCREATE TABLE IF NOT EXISTS public.comentarios (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    solicitacao_id UUID REFERENCES public.solicitacoes(id) ON DELETE CASCADE,\n    autor_id UUID REFERENCES auth.users(id),\n    texto TEXT NOT NULL,\n    interno BOOLEAN DEFAULT false,\n    autor_tipo TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW()\n);\nALTER TABLE public.comentarios ENABLE ROW LEVEL SECURITY;\n\nCREATE TABLE IF NOT EXISTS public.anexos (\n     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n     solicitacao_id UUID REFERENCES public.solicitacoes(id) ON DELETE CASCADE,\n     usuario_id UUID REFERENCES auth.users(id),\n     url TEXT NOT NULL,\n     tipo TEXT,\n     nome TEXT,\n     tamanho BIGINT,\n     created_at TIMESTAMPTZ DEFAULT NOW()\n);\nALTER TABLE public.anexos ENABLE ROW LEVEL SECURITY;\n\nCREATE TABLE IF NOT EXISTS public.historico_status (\n     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n     solicitacao_id UUID REFERENCES public.solicitacoes(id) ON DELETE CASCADE,\n     usuario_id UUID REFERENCES auth.users(id),\n     acao TEXT,\n     comentario TEXT,\n     created_at TIMESTAMPTZ DEFAULT NOW()\n);\nALTER TABLE public.historico_status ENABLE ROW LEVEL SECURITY;\n\n\nCOMMIT;"}	20260125_foundation_recovery	redestvgmulti@gmail.com	\N	\N
20260125141633	{"-- -----------------------------------------------------\n-- 0. Schema Updates (Idempotency)\n-- -----------------------------------------------------\nDO $$ \nBEGIN \n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'solicitacoes' AND column_name = 'idempotency_key') THEN\n        ALTER TABLE solicitacoes ADD COLUMN idempotency_key TEXT UNIQUE;\n        CREATE INDEX idx_solicitacoes_idempotency ON solicitacoes(idempotency_key);\n    END IF;\nEND $$;\n\n-- -----------------------------------------------------\n-- 1. RPC: Abrir Solicitação (Atomic & Tenant-Aware & Idempotent)\n-- -----------------------------------------------------\nCREATE OR REPLACE FUNCTION rpc_abrir_solicitacao(\n    p_tipo_solicitacao_id UUID,\n    p_tipo_ocorrencia TEXT, -- 'sugestao', 'reclamacao', 'elogio'\n    p_titulo TEXT,\n    p_descricao TEXT,\n    p_endereco TEXT,\n    p_latitude FLOAT DEFAULT NULL,\n    p_longitude FLOAT DEFAULT NULL,\n    p_foto_url TEXT DEFAULT NULL,\n    p_idempotency_key TEXT DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER -- Runs with owner privileges to ensure data integrity\nSET search_path = public\nAS $$\nDECLARE\n    v_user_id UUID;\n    v_cidade_id UUID;\n    v_solicitacao_id UUID;\n    v_protocolo TEXT;\n    v_novo_status TEXT := 'aberto';\n    v_existing_id UUID;\n    v_existing_protocolo TEXT;\nBEGIN\n    -- 1. Get Current User\n    v_user_id := auth.uid();\n    IF v_user_id IS NULL THEN\n        RAISE EXCEPTION 'Acesso negado: Usuário não autenticado.';\n    END IF;\n\n    -- 2. Derive Tenant (Cidade) from User Profile\n    -- STRICT isolation: Tenant is never passed by client\n    SELECT cidade_id INTO v_cidade_id\n    FROM usuarios\n    WHERE id = v_user_id;\n\n    IF v_cidade_id IS NULL THEN\n        RAISE EXCEPTION 'Erro de consistência: Usuário sem cidade vinculada.';\n    END IF;\n\n    -- 3. Idempotency Check\n    IF p_idempotency_key IS NOT NULL THEN\n        SELECT id, protocolo INTO v_existing_id, v_existing_protocolo\n        FROM solicitacoes\n        WHERE idempotency_key = p_idempotency_key;\n\n        IF v_existing_id IS NOT NULL THEN\n            RETURN jsonb_build_object(\n                'success', true,\n                'solicitacao_id', v_existing_id,\n                'protocolo', v_existing_protocolo,\n                'idempotent', true,\n                'message', 'Solicitação já processada anteriormente.'\n            );\n        END IF;\n    END IF;\n\n    -- 4. Validation\n    IF p_titulo IS NULL OR length(trim(p_titulo)) < 3 THEN\n        RAISE EXCEPTION 'O título é obrigatório e deve ter 3+ caracteres.';\n    END IF;\n\n    -- 5. INSERT (Atomic)\n    INSERT INTO solicitacoes (\n        cidadao_id,\n        cidade_id,\n        tipo_solicitacao_id,\n        tipo_ocorrencia,\n        titulo,\n        descricao,\n        endereco,\n        latitude,\n        longitude,\n        foto_url,\n        status,\n        idempotency_key,\n        created_at,\n        updated_at\n    )\n    VALUES (\n        v_user_id,\n        v_cidade_id,\n        p_tipo_solicitacao_id,\n        p_tipo_ocorrencia,\n        p_titulo,\n        p_descricao,\n        p_endereco,\n        p_latitude,\n        p_longitude,\n        p_foto_url,\n        v_novo_status,\n        p_idempotency_key,\n        NOW(),\n        NOW()\n    )\n    RETURNING id, protocolo INTO v_solicitacao_id, v_protocolo;\n\n    -- 6. [INTEGRATION] Feed Automático (Se solicitação pública e não anônima?)\n    -- Regra: Criar 'service_update' para nova abertura.\n    -- TODO: Verificar se solicitações privadas devem ir para o feed (provavelmente não).\n    INSERT INTO feed_posts (\n        cidade_id,\n        tipo,\n        status,\n        titulo,\n        resumo,\n        published_at,\n        created_by\n    ) VALUES (\n        v_cidade_id,\n        'service_update',\n        'published',\n        'Nova Solicitação: ' || p_titulo,\n        'Protocolo ' || v_protocolo || ': ' || substring(p_descricao from 1 for 100) || '...',\n        NOW(),\n        v_user_id\n    );\n\n    -- 6. Return audit payload\n    RETURN jsonb_build_object(\n        'success', true,\n        'solicitacao_id', v_solicitacao_id,\n        'protocolo', v_protocolo,\n        'idempotent', false\n    );\nEND;\n$$;\n\n-- -----------------------------------------------------\n-- 2. RPC: Atualizar Status (Transactional & Audit)\n-- -----------------------------------------------------\nCREATE OR REPLACE FUNCTION rpc_atualizar_status_solicitacao(\n    p_solicitacao_id UUID,\n    p_novo_status TEXT, -- 'aberto', 'em_andamento', 'resolvido', 'cancelado'\n    p_observacao_historico TEXT,\n    p_comentario_resolucao TEXT DEFAULT NULL,\n    p_fotos_resolucao TEXT[] DEFAULT NULL,\n    p_comentario_adicional TEXT DEFAULT NULL,\n    p_interno BOOLEAN DEFAULT FALSE\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_user_id UUID;\n    v_user_role TEXT;\n    v_user_cidade_id UUID;\n    v_user_secretaria_id UUID;\n    v_solicitacao_cidade_id UUID;\n    v_solicitacao_secretaria_id UUID;\n    v_current_status TEXT;\nBEGIN\n    -- 1. Get User Context\n    v_user_id := auth.uid();\n    IF v_user_id IS NULL THEN\n        RAISE EXCEPTION 'Acesso negado: Usuário não autenticado.';\n    END IF;\n\n    SELECT tipo_perfil, cidade_id, secretaria_id \n    INTO v_user_role, v_user_cidade_id, v_user_secretaria_id\n    FROM usuarios\n    WHERE id = v_user_id;\n\n    -- 2. Get Resource Context\n    SELECT cidade_id, secretaria_id, status \n    INTO v_solicitacao_cidade_id, v_solicitacao_secretaria_id, v_current_status\n    FROM solicitacoes\n    WHERE id = p_solicitacao_id;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Solicitação não encontrada.';\n    END IF;\n\n    -- 3. PERMISSION CHECK (Explicit RBAC & Tenant Isolation)\n    IF v_user_role = 'cidadao' THEN\n        -- Citizens: Can ONLY cancel THEIR OWN requests\n        DECLARE \n            v_owner_id UUID;\n        BEGIN\n            SELECT cidadao_id INTO v_owner_id FROM solicitacoes WHERE id = p_solicitacao_id;\n            \n            IF v_owner_id != v_user_id THEN\n                RAISE EXCEPTION 'Acesso negado: Você não é o autor desta solicitação.';\n            END IF;\n\n            IF p_novo_status != 'cancelado' THEN\n                RAISE EXCEPTION 'Acesso negado: Cidadãos só podem cancelar solicitações.';\n            END IF;\n        END;\n\n    ELSIF v_user_role NOT IN ('admin', 'secretario', 'master_admin') THEN\n        RAISE EXCEPTION 'Acesso negado: Perfil não autorizado.';\n    END IF;\n\n    -- Admin/Secretario Permissions\n    IF v_user_role IN ('admin', 'secretario') THEN\n        -- Must match City\n        IF v_user_cidade_id != v_solicitacao_cidade_id THEN\n            RAISE EXCEPTION 'Acesso negado: Este recurso pertence a outra cidade.';\n        END IF;\n\n        IF v_user_role = 'secretario' THEN\n             -- Must match Secretaria\n            IF v_solicitacao_secretaria_id IS NULL OR v_user_secretaria_id != v_solicitacao_secretaria_id THEN\n                 RAISE EXCEPTION 'Acesso negado: Esta solicitação não está atribuída à sua secretaria.';\n            END IF;\n        END IF;\n    END IF;\n\n    -- 4. Status Validation\n    IF p_novo_status = v_current_status THEN\n        RAISE EXCEPTION 'O novo status deve ser diferente do atual.';\n    END IF;\n\n    -- 5. ATOMIC UPDATE\n    UPDATE solicitacoes\n    SET \n        status = p_novo_status,\n        updated_at = NOW(),\n        data_resolucao = CASE WHEN p_novo_status = 'resolvido' THEN NOW() ELSE data_resolucao END,\n        comentario_resolucao = CASE WHEN p_novo_status = 'resolvido' THEN p_comentario_resolucao ELSE comentario_resolucao END,\n        fotos_resolucao = CASE WHEN p_novo_status = 'resolvido' THEN p_fotos_resolucao ELSE fotos_resolucao END\n    WHERE id = p_solicitacao_id;\n\n    -- 6. [INTEGRATION] Feed Automático (Status Concluído)\n    IF p_novo_status = 'resolvido' THEN\n        INSERT INTO feed_posts (\n            cidade_id,\n            tipo,\n            status,\n            titulo,\n            resumo,\n            imagem_capa,\n            published_at,\n            created_by\n        ) VALUES (\n            v_solicitacao_cidade_id,\n            'service_update',\n            'published',\n            'Solicitação Resolvida',\n            'A solicitação #' || p_solicitacao_id || ' (' || v_current_status || ' -> ' || p_novo_status || ') foi concluída com sucesso.',\n            (p_fotos_resolucao)[1], -- Tenta pegar a primeira foto se houver\n            NOW(),\n            v_user_id\n        );\n    END IF;\n\n    -- 6. Insert History (Audit Trail)\n    INSERT INTO historico_status (\n        solicitacao_id,\n        usuario_id,\n        acao,\n        comentario,\n        created_at\n    ) VALUES (\n        p_solicitacao_id,\n        v_user_id,\n        CASE \n            WHEN p_novo_status = 'em_andamento' THEN 'Solicitação Em Andamento'\n            WHEN p_novo_status = 'resolvido' THEN 'Solicitação Concluída'\n            WHEN p_novo_status = 'aberto' THEN 'Solicitação Reaberta'\n            WHEN p_novo_status = 'cancelado' THEN 'Solicitação Cancelada'\n            ELSE 'Status alterado para ' || p_novo_status\n        END,\n        p_observacao_historico,\n        NOW()\n    );\n\n    -- 7. Insert Additional Comment (Optional)\n    IF p_comentario_adicional IS NOT NULL AND length(trim(p_comentario_adicional)) > 0 THEN\n        INSERT INTO comentarios (\n            solicitacao_id,\n            autor_id,\n            texto,\n            interno,\n            autor_tipo,\n            created_at\n        ) VALUES (\n            p_solicitacao_id,\n            v_user_id,\n            p_comentario_adicional,\n            p_interno,\n            v_user_role,\n            NOW()\n        );\n    END IF;\n\n    -- 8. Return Success\n    RETURN jsonb_build_object(\n        'success', true,\n        'new_status', p_novo_status,\n        'timestamp', NOW()\n    );\nEND;\n$$;\n\n-- -----------------------------------------------------\n-- 3. RPC: Adicionar Comentário (Secure Insert)\n-- -----------------------------------------------------\nCREATE OR REPLACE FUNCTION rpc_adicionar_comentario(\n    p_solicitacao_id UUID,\n    p_texto TEXT,\n    p_interno BOOLEAN DEFAULT FALSE\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_user_id UUID;\n    v_user_role TEXT;\n    v_user_cidade_id UUID;\n    v_solicitacao_cidade_id UUID;\n    v_solicitacao_cidadao_id UUID;\n    v_comment_id UUID;\nBEGIN\n    -- 1. Get User Context\n    v_user_id := auth.uid();\n    IF v_user_id IS NULL THEN\n        RAISE EXCEPTION 'Acesso negado: Usuário não autenticado.';\n    END IF;\n\n    SELECT tipo_perfil, cidade_id \n    INTO v_user_role, v_user_cidade_id\n    FROM usuarios\n    WHERE id = v_user_id;\n\n    -- 2. Get Resource Context\n    SELECT cidade_id, cidadao_id\n    INTO v_solicitacao_cidade_id, v_solicitacao_cidadao_id\n    FROM solicitacoes\n    WHERE id = p_solicitacao_id;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Solicitação não encontrada.';\n    END IF;\n\n    -- 3. PERMISSION CHECK\n    IF v_user_role = 'cidadao' THEN\n        -- Citizens can only comment on THEIR requests and CANNOT mark as internal\n        IF v_solicitacao_cidadao_id != v_user_id THEN\n            RAISE EXCEPTION 'Acesso negado: Você só pode comentar em suas próprias solicitações.';\n        END IF;\n        IF p_interno IS TRUE THEN\n            RAISE EXCEPTION 'Acesso negado: Cidadãos não podem criar comentários internos.';\n        END IF;\n    \n    ELSIF v_user_role IN ('admin', 'secretario', 'master_admin') THEN\n        -- Admins must match City (Master matches all)\n        IF v_user_role != 'master_admin' AND v_user_cidade_id != v_solicitacao_cidade_id THEN\n             RAISE EXCEPTION 'Acesso negado: Este recurso pertence a outra cidade.';\n        END IF;\n    ELSE\n        RAISE EXCEPTION 'Perfil de usuário desconhecido.';\n    END IF;\n\n    -- 4. INSERT\n    INSERT INTO comentarios (\n        solicitacao_id,\n        autor_id,\n        texto,\n        interno,\n        autor_tipo,\n        created_at\n    ) VALUES (\n        p_solicitacao_id,\n        v_user_id,\n        p_texto,\n        p_interno,\n        v_user_role,\n        NOW()\n    )\n    RETURNING id INTO v_comment_id;\n\n    -- 5. Return Success\n    RETURN jsonb_build_object(\n        'success', true,\n        'id', v_comment_id\n    );\nEND;\n$$;\n\n-- -----------------------------------------------------\n-- 4. RPC: Adicionar Anexo (Secure Insert)\n-- -----------------------------------------------------\nCREATE OR REPLACE FUNCTION rpc_adicionar_anexo(\n    p_solicitacao_id UUID,\n    p_url TEXT,\n    p_tipo TEXT,\n    p_nome TEXT,\n    p_tamanho BIGINT\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_user_id UUID;\n    v_user_role TEXT;\n    v_user_cidade_id UUID;\n    v_solicitacao_cidade_id UUID;\n    v_solicitacao_cidadao_id UUID;\n    v_anexo_id UUID;\nBEGIN\n    -- 1. Get User Context\n    v_user_id := auth.uid();\n    IF v_user_id IS NULL THEN\n        RAISE EXCEPTION 'Acesso negado: Usuário não autenticado.';\n    END IF;\n\n    SELECT tipo_perfil, cidade_id \n    INTO v_user_role, v_user_cidade_id\n    FROM usuarios\n    WHERE id = v_user_id;\n\n    -- 2. Get Resource Context\n    SELECT cidade_id, cidadao_id\n    INTO v_solicitacao_cidade_id, v_solicitacao_cidadao_id\n    FROM solicitacoes\n    WHERE id = p_solicitacao_id;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Solicitação não encontrada.';\n    END IF;\n\n    -- 3. PERMISSION CHECK\n    IF v_user_role = 'cidadao' THEN\n        -- Citizens can only attach to their own requests\n        IF v_solicitacao_cidadao_id != v_user_id THEN\n            RAISE EXCEPTION 'Acesso negado: Você só pode adicionar anexos em suas próprias solicitações.';\n        END IF;\n    ELSIF v_user_role IN ('admin', 'secretario', 'master_admin') THEN\n         -- Must match City\n        IF v_user_role != 'master_admin' AND v_user_cidade_id != v_solicitacao_cidade_id THEN\n             RAISE EXCEPTION 'Acesso negado: Este recurso pertence a outra cidade.';\n        END IF;\n    END IF;\n\n    -- 4. INSERT\n    INSERT INTO anexos (\n        solicitacao_id,\n        usuario_id,\n        url,\n        tipo,\n        nome,\n        tamanho,\n        created_at\n    ) VALUES (\n        p_solicitacao_id,\n        v_user_id,\n        p_url,\n        p_tipo,\n        p_nome,\n        p_tamanho,\n        NOW()\n    )\n    RETURNING id INTO v_anexo_id;\n\n    -- 5. Return Success\n    RETURN jsonb_build_object(\n        'success', true,\n        'id', v_anexo_id,\n        'url', p_url\n    );\nEND;\n$$;"}	20260125_canonical_rpcs	redestvgmulti@gmail.com	\N	\N
20260125141825	{"-- ==============================================================================\n-- MIGRATION: FIX USUARIOS FOUNDATION\n-- Data: 25/01/2026\n-- Descrição: Recria tabela usuarios (profile) que falta.\n-- ==============================================================================\n\nBEGIN;\n\nCREATE TABLE IF NOT EXISTS public.usuarios (\n    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n    cidade_id UUID REFERENCES public.cidades(id),\n    secretaria_id UUID REFERENCES public.secretarias(id),\n    nome TEXT,\n    email TEXT,\n    tipo_perfil TEXT DEFAULT 'cidadao', -- 'cidadao', 'admin', 'secretario', 'master_admin'\n    cpf TEXT UNIQUE,\n    telefone TEXT,\n    avatar_url TEXT,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\nALTER TABLE public.usuarios ENABLE ROW LEVEL SECURITY;\n\n-- Basic Policies\nCREATE POLICY \\"Users can read own data\\" ON public.usuarios\n    FOR SELECT USING (auth.uid() = id);\n\nCREATE POLICY \\"Admins can read city users\\" ON public.usuarios\n    FOR SELECT USING (\n        EXISTS (\n            SELECT 1 FROM public.usuarios u \n            WHERE u.id = auth.uid() \n            AND u.tipo_perfil IN ('admin', 'master_admin') \n            AND (u.cidade_id = usuarios.cidade_id OR u.tipo_perfil = 'master_admin')\n        )\n    );\n\nCOMMIT;"}	20260125_fix_usuarios_foundation	redestvgmulti@gmail.com	\N	\N
20260125142444	{"-- ==============================================================================\n-- MIGRATION: PUBLIC METRICS RPC (FASE 1.2)\n-- Data: 25/01/2026\n-- Descrição: Endpoint RPC de leitura para métricas públicas de transparência.\n-- ==============================================================================\n\n-- 1. Create Index for Performance\n-- Acelera contagens por status e cidade, e cálculos de data\nCREATE INDEX IF NOT EXISTS idx_solicitacoes_metrics \nON public.solicitacoes (cidade_id, status, created_at, data_resolucao);\n\n-- 2. RPC: Get Public Metrics\nCREATE OR REPLACE FUNCTION public.get_public_metrics()\nRETURNS JSONB\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n    v_cidade_id UUID;\n    v_total BIGINT;\n    v_resolvidas BIGINT;\n    v_em_andamento BIGINT;\n    v_tempo_medio_dias NUMERIC(10, 2);\n    v_percentual_prazo NUMERIC(5, 2);\nBEGIN\n    -- 1. Resolve Tenant Context\n    v_cidade_id := public.resolve_current_city_id();\n\n    IF v_cidade_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'success', false, \n            'error', 'Tenant context not found.'\n        );\n    END IF;\n\n    -- 2. Calculate Aggregates\n    -- Using a single query with FILTER clauses is usually faster than multiple COUNT(*)\n    SELECT\n        COUNT(*),\n        COUNT(*) FILTER (WHERE status = 'resolvido'),\n        COUNT(*) FILTER (WHERE status IN ('aberto', 'em_andamento')),\n        -- Tempo Médio: Apenas resolvidos. Ignora cancelados.\n        COALESCE(\n            AVG(\n                EXTRACT(EPOCH FROM (data_resolucao - created_at)) / 86400.0\n            ) FILTER (WHERE status = 'resolvido'),\n            0\n        )\n    INTO\n        v_total,\n        v_resolvidas,\n        v_em_andamento,\n        v_tempo_medio_dias\n    FROM public.solicitacoes\n    WHERE cidade_id = v_cidade_id\n      AND deleted_at IS NULL; -- Soft deleted items excluded strictly\n\n    -- 3. Return Payload\n    RETURN jsonb_build_object(\n        'success', true,\n        'data', jsonb_build_object(\n            'total_solicitacoes', v_total,\n            'resolvidas', v_resolvidas,\n            'em_andamento', v_em_andamento,\n            'tempo_medio_resolucao_dias', ROUND(v_tempo_medio_dias, 1)\n        ),\n        'meta', jsonb_build_object(\n            'tenant_id', v_cidade_id,\n            'generated_at', NOW()\n        )\n    );\nEND;\n$$;"}	20260125_public_metrics_rpc	redestvgmulti@gmail.com	\N	\N
20260125142506	{"-- ==============================================================================\n-- VERIFICATION: PUBLIC METRICS SIMULATION\n-- Description: Inserts test data and verifies aggregate calculations.\n-- ==============================================================================\n\nDO $$\nDECLARE\n    v_cidade_id UUID;\n    v_user_id UUID := '00000000-0000-0000-0000-000000000001'; \n    v_metrics JSONB;\nBEGIN\n    -- 1. Setup Context\n    SELECT id INTO v_cidade_id FROM cidades LIMIT 1;\n    IF v_cidade_id IS NULL THEN RAISE EXCEPTION 'No City Found'; END IF;\n\n    -- Setup Date Context (Mock logic handled via direct insert since we need specific dates for avg)\n    -- We can't use RPCs for backdated inserts easily, so we insert raw for *Verification Only*.\n    \n    -- Case 1: Resolved in 1 Day\n    INSERT INTO solicitacoes (\n        cidade_id, titulo, status, created_at, data_resolucao\n    ) VALUES (\n        v_cidade_id, 'Metrics Test 1', 'resolvido', NOW() - INTERVAL '2 days', NOW() - INTERVAL '1 days'\n    );\n\n    -- Case 2: Resolved in 3 Days\n    INSERT INTO solicitacoes (\n        cidade_id, titulo, status, created_at, data_resolucao\n    ) VALUES (\n        v_cidade_id, 'Metrics Test 2', 'resolvido', NOW() - INTERVAL '5 days', NOW() - INTERVAL '2 days'\n    );\n\n    -- Case 3: In Progress (Should not affect time)\n    INSERT INTO solicitacoes (\n        cidade_id, titulo, status, created_at\n    ) VALUES (\n        v_cidade_id, 'Metrics Test 3', 'em_andamento', NOW()\n    );\n\n    -- 2. Mock Auth (needed for RPC tenant resolution)\n    PERFORM set_config('request.jwt.claims', jsonb_build_object(\n        'sub', v_user_id,\n        'app_metadata', jsonb_build_object(\n            'cidade_id', v_cidade_id,\n            'role', 'admin'\n        )\n    )::text, true);\n\n    -- 3. Call RPC\n    SELECT get_public_metrics() INTO v_metrics;\n    \n    RAISE NOTICE 'Metrics Result: %', v_metrics;\n\n    -- 4. Assertions\n    -- We expect at least 2 resolved from our insert. Total might be higher due to previous tests.\n    -- Average Time: (1 day + 3 days) / 2 = 2 days.\n    \n    IF (v_metrics -> 'data' ->> 'tempo_medio_resolucao_dias')::numeric = 2.0 OR \n       (v_metrics -> 'data' ->> 'tempo_medio_resolucao_dias')::numeric > 0 THEN -- Loose check if previous data exists\n         RAISE NOTICE '✅ SUCCESS: Metrics calculated successfully.';\n    ELSE\n         RAISE WARNING '⚠️ CHECK: Average time might be affected by previous data. Result: %', (v_metrics -> 'data' ->> 'tempo_medio_resolucao_dias');\n    END IF;\n\n    -- Clean up test data\n    DELETE FROM solicitacoes WHERE titulo LIKE 'Metrics Test %';\n    \nEND $$;"}	verify_metrics_simulation	redestvgmulti@gmail.com	\N	\N
20260125143506	{"-- ==============================================================================\n-- MIGRATION: ENABLE REALTIME FEED (FASE 1.3)\n-- Data: 25/01/2026\n-- Descrição: Habilita publicação de eventos Realtime para a tabela feed_posts.\n-- ==============================================================================\n\nBEGIN;\n\n-- 1. Check if publication exists (standard supabase setup)\n-- If not, creating it might require superuser. \n-- We assume \\"supabase_realtime\\" exists as per standard Supabase projects.\n\n-- 2. Add table to publication\n-- This allows clients to listen to INSERT/UPDATE/DELETE on this table.\n-- RLS policies will still apply to the subscription if the user is authenticated.\n-- For anon users, RLS policy \\"feed_select_public\\" (See Phase 1.1) must allow read.\n\nALTER PUBLICATION supabase_realtime ADD TABLE public.feed_posts;\n\nCOMMIT;"}	20260125_enable_realtime_feed	redestvgmulti@gmail.com	\N	\N
